var FMT_CAT = {"construccion":{"n":"Construcción","i":[{"k":"antes-y-despues","n":"Inspección de antes y después","ft":"Cuando se levanta una observación en campo; el registro se cierra con la foto del después","c":[],"b":[["",[]]]},{"k":"epp-del-personal","n":"Equipos de protección personal","ft":"Verificación diaria del supervisor; inspección formal mensual por trabajador","c":["Nombres y apellidos","DNI","Cargo"],"b":[["EPP por trabajador",["Casco de seguridad","Lentes de seguridad","Barbiquejo","Zapatos de seguridad","Polo con cinta reflectiva","Pantalón drill","Chaleco","Guantes de cuero","Guantes de badana","Guantes de nitrilo","Protector auditivo","Respirador y filtros","Careta facial","Arnés de cuerpo entero","Línea de vida con absorbedor","Uniforme completo y limpio"]]]},{"k":"extintores","n":"Extintores","ft":"Verificación mensual por extintor; recarga anual y prueba hidrostática según norma","c":["Código","Serie","Ubicación","Tipo","Clase","Peso","Marca","Año de fabricación","Fecha de vencimiento","Última prueba hidrostática","Próxima prueba hidrostática"],"b":[["Estado del extintor",["La presión del manómetro está en la zona verde.","El precinto y el seguro están intactos.","La señalización del extintor es visible desde cualquier punto del área.","El acceso al extintor está libre de obstáculos.","La tarjeta de inspección está firmada y vigente.","La manguera y la boquilla están sin fisuras ni obstrucciones.","El cilindro no presenta abolladuras, corrosión ni pintura desprendida.","El soporte o gabinete está fijo y a la altura reglamentaria.","La cinta del color del mes corresponde al mes en curso.","El extintor está dentro de su fecha de vencimiento."]]]},{"k":"tableros-electricos","n":"Tableros eléctricos","ft":"Inspección mensual por tablero; prueba del diferencial mensual","c":["Código","Ubicación"],"b":[["Caja",["La caja es de material aislante o metálica con puesta a tierra.","Cuenta con parada de emergencia accesible e identificada.","El tablero está identificado con su código y el circuito que alimenta.","Tiene punto de bloqueo para candado (LOTO).","El candado de bloqueo está disponible en el tablero."]],["Protección e interior",["El interruptor diferencial está instalado y la prueba del botón de test quedó registrada.","La tapa interna está colocada y sin partes energizadas expuestas.","Los cables entran por prensaestopas, sin empalmes con cinta ni conductores sueltos.","Los bornes están ajustados y sin señales de recalentamiento.","El tablero cierra completamente y su puerta tiene seguro."]],["Señalización",["Tiene señal de riesgo eléctrico y la indicación del voltaje.","El diagrama unifilar está pegado en el interior y actualizado.","Está libre el espacio de trabajo frente al tablero.","Solo personal autorizado tiene acceso al tablero."]]]},{"k":"servicios-de-bienestar","n":"Servicios de bienestar (SSBB)","ft":"Inspección semanal; limpieza diaria con responsable asignado","c":[],"b":[["Baños y duchas",["La cantidad de servicios de bienestar corresponde al número de trabajadores y a su sexo.","El acceso a baños y duchas está libre de obstrucciones.","Las duchas y los lavamanos están operativos.","No hay fugas de agua en cañerías ni tuberías.","Los baños se mantienen limpios y desinfectados.","Cada baño cuenta con papelera.","Cada baño cuenta con jabonera abastecida.","Los inodoros tienen separaciones y puertas en buen estado.","Existen baños y duchas independientes para hombres y mujeres.","Las aguas servidas se conducen al alcantarillado.","Hay un encargado asignado para la limpieza de baños y duchas."]],["Vestidores",["Se cuenta con casillero para cada trabajador.","Los artículos personales están guardados dentro de los casilleros.","Los vestidores se mantienen limpios.","Los vestidores cuentan con iluminación y red eléctrica en buen estado.","Los vestidores tienen ventilación natural o artificial.","No se usan los vestidores como comedor.","No se usan los vestidores para almacenar materiales.","Los pisos se mantienen libres de acumulación de agua."]],["Comedor",["Hay bancas y mesas suficientes para los trabajadores.","Las mesas y bancas son de material fácilmente lavable.","El comedor tiene piso de cemento u otro material equivalente.","El comedor cuenta con ventilación adecuada.","Se cuenta con dispensador de agua abastecido.","Se cuenta con artefacto de refrigeración para los alimentos.","El comedor cuenta con iluminación y red eléctrica en buen estado.","Hay contenedores suficientes para la disposición de residuos.","El comedor cuenta con extintor operativo.","El comedor se mantiene ordenado y limpio.","Hay un encargado asignado para la limpieza del comedor."]]]},{"k":"productos-quimicos","n":"Manejo de productos químicos","ft":"Inspección mensual del almacén y del uso en campo","c":[],"b":[["Almacenamiento de materiales peligrosos",["Se cuenta con almacén exclusivo para productos químicos.","El almacén tiene bandeja antiderrame con capacidad para el 110% del volumen almacenado.","El almacén cuenta con señalización, candado y rombo NFPA.","Los productos químicos del almacén están etiquetados y rotulados.","El almacén tiene el listado actualizado de productos químicos y sus hojas MSDS en español con las 16 secciones.","El acceso al almacén está restringido a personal autorizado.","El almacén cuenta con kit antiderrame completo y extintor.","Los productos están almacenados según su compatibilidad.","El almacén está ordenado, sin derrames ni residuos peligrosos acumulados."]],["Manejo en campo",["Los productos químicos en campo tienen bandeja antiderrame, rombo NFPA, etiqueta y hoja MSDS.","Las bandejas antiderrame de campo cubren el 110% del volumen a contener.","Las bandejas antiderrame no presentan roturas ni fugas por desgaste.","Las hojas MSDS están en español, completas y con el rombo NFPA diferenciado por color.","Los envases y embudos son de material apropiado; no se usan recipientes de bebidas ni de alimentos."]],["Almacenamiento de combustible",["El contenedor de combustible y la cisterna cuentan con kit antiderrame y extintor.","El contenedor de combustible tiene techo y bandeja antiderrame.","El contenedor y la cisterna cuentan con señalización y hojas MSDS."]]]},{"k":"residuos-no-peligrosos","n":"Manejo de residuos no peligrosos","ft":"Inspección semanal de puntos de segregación y acopio","c":[],"b":[["Punto de segregación en la fuente",["Se cuenta con punto de segregación de residuos no peligrosos por código de colores.","El punto de segregación cuenta con su banner informativo.","El acceso a los puntos de segregación está libre de materiales, herramientas y equipos.","Los cilindros están rotulados, tienen tapa y llevan bolsa del color que corresponde.","Los residuos depositados están correctamente segregados por código de colores.","Hay retiro periódico hacia el acopio temporal, sin sobreacumulación."]],["Acopio temporal de residuos generales",["Se cuenta con punto de acopio temporal de residuos generales.","Los residuos del acopio temporal están correctamente segregados.","Hay retiro periódico hacia disposición final, sin sobreacumulación."]],["Acopio de fierro",["Se cuenta con punto de acopio temporal para fierro.","Los puntos de acopio están delimitados y señalizados.","Los residuos metálicos del acopio están correctamente segregados.","Hay retiro periódico de residuos metálicos hacia disposición final."]],["Acopio de madera y concreto",["Se cuenta con punto de acopio temporal para madera.","El acopio de madera está señalizado y delimitado.","Los residuos de madera están correctamente segregados.","Hay retiro periódico de residuos de madera hacia disposición final.","Existe punto de acopio temporal para residuos de concreto.","El acopio de concreto está señalizado y delimitado.","El acopio de concreto está segregado, sin residuos generales ni madera mezclados.","Hay retiro periódico del acopio de concreto hacia disposición final."]],["Campo y vestuarios",["Se retiran y limpian los residuos no peligrosos de las áreas de trabajo.","Se retiran y limpian los residuos no peligrosos del comedor y los vestuarios."]]]},{"k":"residuos-peligrosos","n":"Manejo de residuos peligrosos","ft":"Inspección semanal del almacén temporal y del manejo en campo","c":[],"b":[["Punto de segregación",["Los residuos peligrosos se segregan correctamente en la fuente por código de colores."]],["Almacén temporal",["Se cuenta con almacén temporal para residuos peligrosos.","El almacén tiene bandeja antiderrame, señalización, rombo NFPA y los residuos están etiquetados.","Los residuos del almacén están correctamente segregados.","El almacén cuenta con kit antiderrame y extintor.","Los residuos están almacenados según su compatibilidad."]],["Manejo en campo",["Se usan bolsas rojas para almacenar y transportar los residuos peligrosos hacia el almacén temporal.","Se retiran y limpian los residuos peligrosos de las áreas de trabajo."]],["Residuos biocontaminados",["Las bolsas de residuos biocontaminados son rojas, van amarradas con doble nudo y se desinfectan con hipoclorito al 1%."]]]},{"k":"botiquin","n":"Botiquín de primeros auxilios","ft":"Verificación mensual del contenido y de las fechas de vencimiento","c":[],"b":[["Botiquín de obra",["02 paquetes de guantes quirúrgicos.","01 frasco de yodopovidona 120 ml solución antiséptica.","01 frasco de agua oxigenada mediano 120 ml.","01 frasco de alcohol mediano 250 ml.","05 paquetes de gasas esterilizadas de 10 cm x 10 cm.","08 paquetes de apósitos.","01 rollo de esparadrapo de 5 cm x 4.50 m.","02 rollos de venda elástica de 3 pulgadas x 5 yardas.","02 rollos de venda elástica de 4 pulgadas x 5 yardas.","01 paquete de algodón x 100 g.","01 venda triangular.","10 paletas bajalenguas para entablillado de dedos.","10 venditas autoadhesivas.","01 frasco de cloruro de sodio al 9/1000 x 1 L para lavado de heridas.","02 paquetes de gasa tipo jelonet para quemaduras.","02 frascos de colirio de 10 ml.","01 tijera punta roma.","01 pinza.","01 frazada.","Resucitador manual o pocket mask.","Ningún insumo está vencido.","El botiquín está señalizado, cerrado y con acceso libre."]],["Botiquín de equipos y vehículos",["01 alcohol de 70° de 120 ml.","01 jabón antiséptico.","05 gasas esterilizadas fraccionadas de 10 cm x 10 cm.","01 apósito esterilizado de 10 cm x 10 cm.","01 esparadrapo de 2.5 cm x 5 cm.","01 venda elástica de 4 pulgadas x 5 yardas.","10 bandas adhesivas (curitas).","01 tijera punta roma de 3 pulgadas.","01 par de guantes quirúrgicos esterilizados 7 1/2.","01 paquete de algodón x 50 g."]]]},{"k":"estacion-de-emergencia","n":"Estación de emergencia","ft":"Verificación mensual de la estación completa","c":[],"b":[["Estación de emergencia",["Botiquín completo y señalizado.","Camilla rígida en buen estado.","Camilla tipo canastilla disponible.","Collarín regulable operativo.","Férula inmovilizadora completa.","Lavaojos portátil con solución vigente.","Frazada limpia y disponible.","Manual o instructivo de primeros auxilios a la vista.","Registro de control y salida de insumos al día.","Extintor operativo y con tarjeta vigente."]],["Camilla rígida y canastilla",["Inmovilizador de cabeza completo.","Correas de seguridad completas y en buen estado.","Collarín cervical regulable operativo.","Eslinga para canastilla de rescate certificada y sin daños."]]]},{"k":"trabajos-en-caliente","n":"Equipos para trabajos en caliente","ft":"Antes de cada trabajo en caliente, con permiso vigente","c":[],"b":[["Generales",["El área de trabajo en caliente está delimitada y señalizada.","Los trabajadores usan correctamente el EPP para trabajo en caliente.","Hay extintor operativo próximo al punto de trabajo.","Se cuenta con biombo contra proyección de chispas.","El ambiente de trabajo está bien ventilado.","La iluminación es adecuada para la tarea.","Los equipos están protegidos contra la intemperie.","No hay materiales inflamables ni combustibles a menos de 10 m del área de trabajo.","Los tomacorrientes están en buen estado, con tapa y sin cables expuestos ni deteriorados.","Las líneas eléctricas están tendidas de forma ordenada en todo el taller.","El tablero eléctrico tiene puesta a tierra, señal de riesgo eléctrico y acceso solo para personal autorizado."]],["Equipo de oxicorte",["El conjunto de oxicorte está en condiciones de uso.","El carro portacilindros es adecuado y tiene cadenas para asegurar los cilindros.","Las ruedas del carro están en buen estado.","Los cilindros cuentan con sus hojas de seguridad.","Los cilindros cumplen las especificaciones del fabricante.","Los reguladores de presión cumplen las especificaciones del fabricante.","Las mangueras están identificadas por color: verde para oxígeno y rojo para acetileno.","Las conexiones están hechas con abrazaderas.","La válvula antirretorno de flama funciona correctamente.","Los manómetros cumplen las especificaciones del fabricante."]],["Esmeril",["El esmeril cuenta con su guarda de seguridad.","Las RPM del disco son iguales o mayores que las del equipo.","El disco de desbaste está en óptimas condiciones, sin fisuras ni desgaste excesivo.","La tuerca de fijación del disco está en buen estado.","El equipo tiene soporte manual auxiliar.","Los cables y enchufes eléctricos están en buen estado."]],["Máquina de soldar",["La máquina de soldar está en condiciones de uso.","La máquina de soldar está debidamente aterrada.","Los empalmes y conexiones por donde circula la corriente están seguros y aislados.","Los cables tienen la capacidad de corriente, resistencia mecánica y aislamiento apropiados.","Los electrodos se conservan limpios y secos.","El asa de la máquina de soldar está en buenas condiciones."]]]},{"k":"senalizacion-y-codigo-de-colores","n":"Señalización y código de colores","ft":"Inspección mensual por área de trabajo","c":[],"b":[["Servicios de bienestar",["Las oficinas, servicios higiénicos y comedor están debidamente señalizados.","En servicios higiénicos y comedor se señaliza el correcto lavado y desinfección de manos.","Las vías de acceso a los servicios de bienestar están señalizadas.","Los tableros eléctricos internos tienen señal de riesgo eléctrico.","Los extintores del área están señalizados."]],["Estación de emergencia",["El compartimento del extintor está señalizado.","El extintor tiene la cinta del mes acorde a su inspección.","El compartimento del botiquín está señalizado.","El compartimento del lavaojos está señalizado."]],["Frentes de trabajo",["Las herramientas están inspeccionadas y con la cinta del color del mes.","El área se señaliza antes de comenzar la actividad.","El área cuenta con señal de prohibido el ingreso a personal no autorizado.","Los aparejos de izaje están inspeccionados y con la cinta del color del mes.","La grúa cuenta con señaléticas de punto ciego.","Las señales están ubicadas en lugares que permiten su clara visualización.","Se realiza limpieza y mantenimiento periódico de señaléticas y protecciones colectivas."]],["Taller de soldadura",["El taller de soldadura cuenta con la señalización adecuada.","Las áreas de especial peligro están señalizadas como de acceso restringido.","Está señalizada la obligatoriedad del uso de EPP en todas las zonas necesarias.","Los extintores del taller están señalizados.","Los tableros eléctricos del taller están señalizados."]]]},{"k":"andamios","n":"Andamios","ft":"Antes de cada uso y cada vez que se modifica el andamio; tarjeta de aprobación firmada del día","c":["Código de andamio","Ubicación exacta","Motivo del trabajo"],"b":[["Generales",["El andamio cuenta con tarjeta de aprobación firmada y con la fecha del día.","Se hizo el ATS, el PETAR de altura y el permiso de montaje del andamio.","Hay orden y limpieza en la plataforma de trabajo.","El perímetro está restringido con conos, cinta de seguridad y barras horizontales.","Está la señalización de caída de objetos, trabajos en altura y riesgo de caída."]],["Medidas de protección",["Las garruchas están en buen estado: ruedas, eje y freno.","Las garruchas están bloqueadas y con tacos.","Los husillos están en buen estado, fijos y nivelados.","Las barandas cumplen la medida normada: 1.05 m la superior y 0.54 m la intermedia.","Los rodapiés cumplen los 0.10 m, están completos, en buen estado y asegurados.","Los diagonales están completos, en buen estado y asegurados.","Los horizontales están completos, en buen estado y asegurados.","Las rosetas están en buen estado.","La plataforma metálica está completa y asegurada según especificación del fabricante.","La superficie del andamio es antideslizante.","Las bases de apoyo son firmes y sólidas.","El andamio está nivelado, respetando la relación 3 a 1 respecto de la dimensión más corta de la base.","El andamio de más de dos cuerpos está asegurado con vientos o amarrado a una estructura estable.","El andamio cuenta con escaleras en todos los niveles.","El andamio cuenta con escotillas.","Los estabilizadores están asegurados en dos puntos con grapas.","El contra andamio está colocado de acuerdo a la modulación.","La plataforma voladiza está colocada de acuerdo a la modulación.","La línea de vida externa es cable de acero de 1/2 pulgada.","La línea de vida tiene tres grapas en cada lado.","Las restricciones de uso están indicadas en la tarjeta del andamio."]]]},{"k":"trabajo-en-altura","n":"Trabajo en altura","ft":"Antes de cada trabajo sobre 1.80 m, con permiso vigente","c":[],"b":[["",["El trabajo sobre 1.80 m cuenta con permiso de trabajo en altura vigente y firmado.","El trabajador tiene examen médico de aptitud para trabajo en altura vigente.","El arnés de cuerpo entero está certificado, sin cortes, quemaduras ni costuras dañadas.","La línea de vida con absorbedor de impacto está vigente y sin señales de activación previa.","El punto de anclaje resiste la carga requerida y está validado.","La distancia de caída libre es adecuada al espacio disponible bajo el trabajador.","El EPP anticaídas está completo y es el que corresponde a la tarea.","El área inferior está delimitada y señalizada contra caída de objetos.","Las herramientas están aseguradas con drizas o portaherramientas.","Las aberturas en piso están cubiertas o protegidas con baranda.","Las condiciones climáticas permiten realizar el trabajo con seguridad.","El personal fue capacitado en trabajo en altura y la capacitación está vigente."]]]},{"k":"orden-y-limpieza","n":"Orden y limpieza","ft":"Verificación diaria del supervisor; inspección formal semanal","c":[],"b":[["",["Los pasillos y vías de circulación están libres y demarcados.","Los materiales están apilados de forma estable y dentro de zonas demarcadas.","Los residuos están segregados en los contenedores que corresponden.","Los cables y mangueras están ordenados y no cruzan vías de tránsito a nivel del piso.","Las herramientas están guardadas en su lugar asignado al terminar la jornada.","Las zonas de trabajo están demarcadas y señalizadas.","No hay clavos expuestos en la madera de encofrado retirada.","Los desniveles y aberturas están protegidos o señalizados.","El área está libre de acumulación de agua y de superficies resbaladizas.","Los accesos a extintores, botiquín y tableros están despejados."]]]},{"k":"herramientas-manuales","n":"Herramientas manuales y eléctricas","ft":"Inspección mensual por herramienta, con la cinta del color del mes","c":["Código","Tipo de herramienta","Responsable"],"b":[["Estado general",["La herramienta tiene la cinta del color del mes, vigente y visible.","La herramienta corresponde al trabajo que se va a hacer; no está improvisada ni modificada.","El mango está firme, sin rajaduras, astillas ni cinta que tape un defecto.","La cabeza o la parte útil no está deformada, rebabeada ni con filo mellado.","No hay uniones soldadas ni reparaciones caseras en partes que soportan esfuerzo.","La herramienta está limpia, sin grasa ni aceite en la zona de agarre."]],["Herramientas eléctricas",["El cable no tiene empalmes con cinta, cortes ni conductores a la vista.","El enchufe está completo, con espiga a tierra y sin quemaduras.","El interruptor prende y apaga con firmeza y no queda trabado.","La guarda de seguridad está instalada y no fue retirada ni bloqueada.","La carcasa no está rajada ni le faltan tornillos.","El disco o accesorio tiene RPM iguales o mayores que las del equipo.","El equipo se conecta a un tablero con interruptor diferencial.","El equipo tiene su ficha técnica o manual disponible y el operador está autorizado."]],["Uso y guardado",["La herramienta se transporta en portaherramientas o caja, no en el bolsillo ni en la mano al subir.","En altura la herramienta va asegurada con driza.","Al terminar la jornada se guarda en su lugar asignado.","Las herramientas observadas se retiran de servicio con tarjeta roja y no se dejan en el frente."]]]},{"k":"escaleras-portatiles","n":"Escaleras portátiles","ft":"Antes de cada uso, por quien la va a usar; revisión mensual con la cinta del color del mes","c":["Código","Tipo de escalera","Ubicación"],"b":[["Estado de la escalera",["Los largueros están completos, rectos y sin rajaduras, abolladuras ni corrosión.","Los peldaños están completos, firmes y a la misma distancia uno de otro.","No tiene peldaños, largueros ni uniones reparados con alambre, clavos o soldadura improvisada.","Tiene zapatas antideslizantes en buen estado en los dos largueros.","Está limpia: sin grasa, aceite ni barro en los peldaños.","Si es de tijera: los tirantes o seguros de apertura están completos y traban bien.","Si es extensible: los seguros y la cuerda traban bien, y los tramos se traslapan lo necesario.","No es metálica si el trabajo es cerca de instalaciones eléctricas.","Tiene su código y la cinta del color del mes."]],["Dónde y cómo se coloca",["Se apoya sobre piso firme y nivelado; nunca sobre cajas, ladrillos o cilindros.","La inclinación es de un metro de separación en la base por cada cuatro de altura.","Sobresale por lo menos un metro por encima del punto de llegada.","Está amarrada arriba o la sujeta otra persona mientras se usa.","El pie de la escalera está libre y señalizado: no queda frente a una puerta ni en una vía de paso sin resguardo."]],["Uso",["Sube y baja una persona a la vez, de frente a la escalera y con las manos libres.","Las herramientas y los materiales se suben con soga o en cinturón portaherramientas, no en las manos.","No se usa como plataforma, pasarela ni andamio.","Sobre 1.80 m de altura se usa arnés, anclado a un punto independiente de la escalera."]]]},{"k":"gruas","n":"Grúas y equipos de izaje","ft":"Antes de cada jornada, por el operador; mantenimiento y certificación según el fabricante","c":["Código de equipo","Tipo de grúa","Operador"],"b":[["Operador y documentos",["El operador está entrenado y autorizado para este equipo, y lleva su acreditación.","El rigger está designado, usa un chaleco reflectivo que lo distingue y conoce el código de señales.","El manual del fabricante y la tabla de cargas están en la cabina.","El equipo tiene vigente su certificado de operatividad y su mantenimiento al día.","Hay permiso de izaje para la maniobra de hoy, si es un izaje crítico."]],["Estructura y mecanismos",["La estructura, la pluma y los pasadores no tienen fisuras, deformaciones ni pernos flojos.","Los cables de izaje no tienen hilos rotos, dobleces ni ensortijados, y enrollan bien en el tambor.","El gancho gira libre, no está abierto ni deformado y tiene su pestillo de seguridad.","Las poleas y el bloque del gancho están en buen estado y lubricados.","No hay fugas de aceite hidráulico, combustible ni refrigerante.","Los frenos de izaje, de giro y de traslación responden bien.","Los mandos de la cabina funcionan y están identificados."]],["Dispositivos de seguridad",["El limitador de carga y el de fin de carrera del gancho funcionan.","La capacidad máxima de carga está a la vista en el equipo.","La bocina, la alarma de retroceso y las luces funcionan.","Tiene extintor de polvo químico seco ABC de 9 kg como mínimo, cargado y a la mano.","Los estabilizadores se extienden completos y apoyan sobre tacos en terreno firme (grúa móvil y camión grúa).","El anemómetro funciona (grúa torre)."]],["Accesorios de izaje",["Las eslingas, estrobos, grilletes y cadenas se revisaron antes de usar: sin cortes, hilos rotos ni deformaciones.","Cada accesorio tiene marcada su capacidad de carga y alcanza para el peso a izar.","Los accesorios dañados se retiraron de la obra."]],["Área de maniobra",["El área de maniobra está restringida y señalizada; no hay personas bajo la carga ni en el radio de giro.","El terreno está nivelado y soporta el peso del equipo y de la carga.","Se verificó la distancia a las líneas eléctricas aéreas.","El viento permite la maniobra: con más de 80 km/h se suspende.","La carga se levanta en vertical, con el gancho directamente encima, y se guía con vientos (sogas)."]]]}]},"mineria":{"n":"Minería","i":[{"k":"desate-y-sostenimiento","n":"Desate de rocas y sostenimiento de labores","ft":"Diaria, por cada guardia y a cargo del supervisor del área; verificación mensual en la inspección del Comité de SSO. Las pruebas de arranque (pull test) de pernos siguen el programa aprobado por Geomecánica.","c":[],"b":[["Antes de ingresar a la labor",["El IPERC continuo (Anexo 7) está llenado y firmado por el trabajador y el supervisor antes de iniciar la tarea.","La medición de gases al inicio de guardia está registrada y los valores están dentro de límite.","El acceso a la labor está libre de obstrucciones y la vía de escape está señalizada.","La labor cuenta con ventilación activa y con manga instalada donde corresponde."]],["Desatado de rocas",["Se ejecutó el desatado de techo, cajas y frente antes de iniciar cualquier actividad.","El desatado se realizó avanzando de zona segura hacia zona insegura, desde el área ya sostenida.","La barretilla es de longitud adecuada, no menor a 1.5 veces la altura de la labor.","La barretilla está sin dobleces, sin punta roma y con mango en buen estado.","Se usa desatador mecánico cuando la altura de la labor supera los 4 metros."]],["Sostenimiento",["El tipo de sostenimiento instalado corresponde al indicado por Geomecánica para el dominio estructural de la labor.","El sostenimiento está instalado hasta el tope del frente, sin tramos descubiertos.","Los pernos (split set, hydrabolt o helicoidal) están colocados según la malla de diseño.","Las platinas de los pernos están asentadas contra el macizo rocoso y con tuerca ajustada.","Las mallas están traslapadas, ancladas y sin zonas colgadas, rasgadas ni desprendidas.","El shotcrete tiene el espesor especificado y no presenta fisuras, oquedades ni desprendimientos.","Los cuadros de madera están completos con postes, sombrero, tirantes y encribado, sin rajaduras ni pandeo."]],["Control y registro",["No hay elementos de sostenimiento deformados, cortados o vencidos sin reemplazo.","La zona sin sostener o de riesgo está acordonada con malla o cinta y con letrero de no pasar.","La prueba de arranque (pull test) de pernos está ejecutada según programa y con registro vigente.","El mapeo geomecánico de la labor está actualizado y disponible en el punto de trabajo."]]]},{"k":"ventilacion-labores-subterraneas","n":"Ventilación de labores subterráneas","ft":"Evaluación integral del sistema de ventilación cada semestre y evaluaciones parciales cada vez que se reducen conexiones de labores o cambian los circuitos de aire (art. 252). Los planos de ventilación se actualizan mensualmente y la verificación de campo es diaria por guardia.","c":[],"b":[["Caudal y velocidad de aire",["El caudal de aire por trabajador cumple el mínimo según altitud: 3 m3/min por debajo de 1500 msnm.","El caudal es de 4 m3/min entre 1500 y 3000 msnm, 5 m3/min entre 3000 y 4000 msnm y 6 m3/min sobre 4000 msnm.","La velocidad del aire en labores de explotación no es menor a 20 m/min ni mayor a 250 m/min.","Donde se emplea ANFO la velocidad del aire no es menor a 25 m/min.","La medición de velocidad se realizó por el método de áreas iguales, con al menos 10 m de tramo recto libre de obstrucciones."]],["Ventiladores",["Los ventiladores principales están instalados en caseta incombustible y protegida contra derrumbes.","El ventilador principal cuenta con dos fuentes independientes de energía eléctrica.","El ventilador principal cuenta con dispositivo automático de alarma ante disminución de velocidad o parada.","El ventilador principal cuenta con dispositivo que permite invertir el sentido de la corriente de aire.","Los ventiladores secundarios están instalados en cámara de ventilación conforme al Anexo 17.","Las labores en avance con una sola vía de acceso y más de 60 m de longitud cuentan con ventilador auxiliar."]],["Mangas, tapones y control documentario",["Las mangas de ventilación están sin cortes, sin estrangulamientos y sin fugas.","La manga de ventilación llega a no más de 15 m del frente en labores de desarrollo y preparación.","Las labores paralizadas están tapeadas con puerta o tapón hermético, señalizadas y con prohibición de ingreso.","El plano de ventilación del mes está disponible, actualizado y firmado por el responsable.","El informe de la última evaluación integral semestral del sistema de ventilación está disponible."]]]},{"k":"medicion-de-gases-y-estaciones-de-monitoreo","n":"Medición de gases y estaciones de monitoreo","ft":"Medición al inicio de cada jornada y antes de ingresar a la labor minera. Monitoreo semanal de CO y NO2 en los gases de escape de equipos diésel (art. 254). Control mensual de gases por uso de ANFO (art. 291).","c":[],"b":[["Equipos de medición",["Los detectores multigas están operativos y cuentan con certificado de calibración vigente.","Se ejecutó el bump test del día a cada detector antes de entregarlo a la guardia.","El detector mide oxígeno, monóxido de carbono, dióxido de carbono, dióxido de nitrógeno y sulfuro de hidrógeno.","Los equipos asignados a la guardia están registrados con número de serie y trabajador responsable.","Las alarmas sonora y visual del detector se activan en la prueba de funcionamiento."]],["Parámetros medidos y registros",["La medición de gases se realizó al inicio de la guardia y antes de ingresar a la labor minera.","El porcentaje de oxígeno en la labor no es menor a 19.5%.","Las concentraciones de CO, CO2, NO2 y H2S están por debajo del límite del Anexo 15 del reglamento.","El polvo respirable no supera 3 mg/m3 y la sílice cristalina no supera 0.05 mg/m3 para jornada de 8 horas.","Los equipos diésel cuentan con registro semanal de CO menor a 500 ppm en el escape.","Los equipos diésel cuentan con registro semanal de NO2 menor a 100 ppm en el escape.","Las estaciones de monitoreo están identificadas, con placa de lectura y datos actualizados.","El registro de mediciones está firmado por el supervisor de guardia y disponible en la labor."]]]},{"k":"sistema-de-izaje-piques-y-winches","n":"Sistema de izaje, piques y winches","ft":"Inspección mensual de los cables de suspensión, winche, polea, pique, balde y jaula (art. 271 lit. b). Verificación diaria pre-uso y recorrido en vacío en cada cambio de guardia. La conexión a tierra de los equipos eléctricos asociados se verifica diariamente.","c":[],"b":[["Antes de operar",["Se recorrió la jaula o balde en vacío por todo el pique al inicio de la guardia.","El operador de winche cuenta con autorización interna vigente y ejecutó el check list pre-uso.","El código de señales del pique está publicado en sala de winche y en cada nivel, y es legible.","El sistema de comunicación entre niveles y sala de winche está operativo y fue probado."]],["Cables, poleas y frenos",["Existe registro mensual de inspección de los cables de suspensión, firmado por el responsable.","El cable no presenta hilos rotos por encima del criterio de descarte establecido.","El cable no presenta aplastamientos, jaulas de pájaro, torceduras ni corrosión avanzada.","La reducción de diámetro del cable está dentro del límite admisible y la medición está registrada.","La lubricación del cable está al día y registrada en la bitácora.","Poleas, chumaceras y guardas están íntegras, sin juego excesivo ni desgaste de canal.","Los frenos de servicio y de emergencia fueron probados y el resultado está registrado."]],["Pique, estructura y registros",["Los finales de carrera y limitadores de sobre-recorrido están instalados y operativos.","El pique, brocales, compuertas y guiaderas están libres de obstrucciones y el brocal está protegido.","La velocidad de izaje no supera el límite establecido según la profundidad del pique.","El libro o registro de inspección del sistema de izaje está firmado y al día."]]]},{"k":"jaulas-y-baldes-de-izaje","n":"Jaulas y baldes de izaje de personal","ft":"Prueba real en vacío de los sistemas de traba con periodicidad mensual. Recorrido de la jaula en vacío en cada cambio de guardia. Inspección de jaula y balde como mínimo mensual junto con winche, polea y pique.","c":["Código","Pique","Capacidad"],"b":[["Construcción y dispositivos de seguridad",["La jaula está construida con piezas metálicas y sus paredes, piso, techo y puertas impiden que los trabajadores o materiales se asomen accidentalmente.","La jaula cuenta con dispositivos mecánicos de traba (leonas) que impiden su caída libre por el pique.","Las puertas de la jaula cierran completamente y su apertura impide la operación del sistema.","El cartel con el número máximo de pasajeros está instalado, visible y legible.","La estructura de la jaula no presenta fisuras, deformaciones, soldaduras improvisadas ni corrosión.","El balde cuenta con guarda o dispositivo que impide el vuelco durante el transporte de personal."]],["Pruebas y operación",["Se ejecutó la prueba mensual en vacío de los sistemas de traba y el resultado está registrado.","La carga máxima autorizada de la jaula está determinada y señalizada en el equipo.","La velocidad de izaje no excede el límite según la profundidad del pique.","No se transporta personal y material en el mismo viaje cuando el procedimiento lo prohíbe.","La iluminación de la jaula y de los embarcaderos está operativa.","El registro de inspección de la jaula está firmado por el responsable y al día."]]]},{"k":"polvorines-y-explosivos","n":"Polvorines y manejo de explosivos","ft":"Inspección semanal coordinada por el Superintendente de Mina. Verificación mensual en la inspección del Comité de SSO. Control mensual de gases cuando se emplea ANFO (art. 291).","c":[],"b":[["Ubicación y construcción",["El polvorín mantiene una distancia mínima de 60 m a líneas eléctricas aéreas.","El polvorín mantiene una distancia mínima de 100 m a subestaciones eléctricas y a almacenes de combustible.","Cuenta con terraplenes o muros de defensa conforme al art. 280 del reglamento.","El piso es de concreto o material incombustible y las puertas son metálicas de doble hoja con cerradura."]],["Condiciones internas y almacenamiento",["El área perimetral está libre de pasto, arbustos y material combustible en al menos 10 m.","La ventilación natural o forzada es operativa y mantiene temperatura y humedad adecuadas.","Las cajas están apiladas a no más de 1.80 m de altura y sobre parihuelas de madera ignífuga.","Existe una separación mínima de 0.80 m entre las rumas y la pared más próxima.","Las cajas están dispuestas mostrando la etiqueta de contenido y con pasillos de circulación libres.","Los explosivos y los accesorios de voladura están almacenados en ambientes separados.","No se supera la capacidad máxima de almacenamiento autorizada para el polvorín."]],["Protección eléctrica y contra incendio",["La instalación eléctrica está entubada y los interruptores son a prueba de chispa.","El sistema de puesta a tierra está instalado y con medición de resistencia vigente.","El pararrayos está instalado en polvorines de superficie conforme al Código Nacional de Electricidad.","El dispositivo de descarga de estática está instalado en el exterior de la puerta de ingreso y es usado por el personal.","Cuenta con al menos dos extintores PQS ABC de 12 kg, uno interior y otro exterior, operativos y señalizados."]],["Control administrativo y acceso",["El KARDEX de explosivos y accesorios está al día y cuadra con el inventario físico.","Se aplica rotación de stock, consumiendo primero el material más antiguo.","Está publicado el listado con nombres y firmas de supervisores autorizados a emitir vales y de trabajadores autorizados al retiro.","El personal que ingresa cuenta con autorización SUCAMEC vigente y el acceso está custodiado las 24 horas."]]]},{"k":"chimeneas-y-labores-subterraneas","n":"Chimeneas y labores subterráneas","ft":"Verificación diaria por el supervisor como zona de alto riesgo, antes de autorizar el ingreso. Inspección semanal del conjunto de labores y verificación mensual del Comité de SSO.","c":[],"b":[["Chimeneas",["La chimenea cuenta con compartimento separado para el tránsito de personal y para el paso de mineral.","Las escaleras están ancladas, con peldaños completos y con descansos según la norma.","Los tapones, compuertas y parrillas están instalados y operativos.","El sostenimiento de la chimenea está completo, sin elementos vencidos ni deformados.","La chimenea cuenta con ventilación y la medición de gases previa al ingreso está registrada.","Los puntos de acceso a la chimenea están señalizados e iluminados.","El ingreso a la chimenea se realiza con PETAR vigente cuando el procedimiento lo exige."]],["Accesos y condiciones de la labor",["Las vías de escape están señalizadas, despejadas e iluminadas.","Las cunetas y drenajes están limpios y no generan acumulación de agua en la labor.","Las instalaciones de aire comprimido, agua y energía están ordenadas y sin fugas.","La señalización de la labor está instalada conforme al código de señales y colores del Anexo 17.","Los sardineles o bermas de seguridad están construidos en las labores de tránsito de equipos.","Las labores paralizadas están señalizadas y con barrera física que impide el ingreso."]]]},{"k":"tolvas-y-echaderos","n":"Tolvas, echaderos y puntos de carguío","ft":"Inspección semanal del conjunto y verificación diaria por el supervisor como zona de alto riesgo. Verificación mensual en la inspección del Comité de SSO.","c":[],"b":[["",["La tolva o echadero cuenta con parrilla instalada y con abertura no mayor a la de diseño.","Existe baranda o protección perimetral en el borde superior de la tolva.","Se cuenta con línea de vida y punto de anclaje certificado para trabajos sobre la parrilla.","El ingreso al interior de la tolva está prohibido y señalizado, y solo procede con PETAR.","El desatoro se realiza con procedimiento y herramientas autorizadas, nunca manualmente desde el interior.","El chute o compuerta de descarga opera correctamente y sin fugas de mineral.","La zona de descarga cuenta con tope o muro de seguridad para volquetes.","La iluminación y la señalización de la zona de carguío están operativas.","No hay acumulación de material colgado sin control ni señalización.","El acceso a la tolva está restringido con barrera o candado cuando no está en operación."]]]},{"k":"fajas-transportadoras","n":"Fajas transportadoras","ft":"Prueba mensual del cable de parada de emergencia y de los enclavamientos. Verificación diaria pre-turno de operatividad y limpieza, semanal de guardas y señalización, trimestral de estructuras y anual de contrapesos y sistemas de suspensión por persona competente.","c":[],"b":[["Guardas y puntos de atrapamiento",["Los polines portantes y de retorno, la polea motriz, deflectora, tensora y de retorno cuentan con guardas instaladas.","Las guardas están aseguradas, requieren herramienta para su retiro y están codificadas y pintadas de color amarillo.","No se opera la faja con guardas retiradas; todo retiro cuenta con autorización de la línea de supervisión.","Las zonas por debajo de la faja a menos de 2.50 m del piso cuentan con barrera de protección.","El personal del área no usa cabello suelto, ropa suelta, chalinas, cadenas, pulseras ni anillos."]],["Parada de emergencia y enclavamientos",["El cable de parada de emergencia recorre toda la longitud operativa a ambos lados accesibles y está libre de obstáculos.","El cable de parada de emergencia está señalizado como mínimo cada 25 m.","No se ha reemplazado el cable de parada de emergencia por pulsadores o botoneras.","Existe registro de la prueba mensual de funcionamiento del cable de parada de emergencia.","Los sensores de desalineamiento, de posición y de sobrecarga están operativos.","La alarma audible de arranque suena al menos 10 segundos antes de energizar la faja."]],["Accesos, pasarelas y señalización",["Hay pasarelas laterales a ambos lados con baranda superior de altura mínima 1.20 m e intermedia a 0.50 m.","Los cruces sobre la faja se realizan únicamente por los pasos peatonales diseñados y señalizados.","Las zonas de paso por debajo de la faja cuentan con cobertura contra caída de material.","Pasarelas, escaleras y caminos están libres de derrames, grasa, aceite y herramientas.","La señalización está instalada como mínimo cada 50 m e incluye no usar ropa suelta, no viajar sobre la faja, no retirar guardas y no cruzar sin puente.","El nivel de iluminación en la faja es de al menos 300 lux."]],["Bloqueo, limpieza y mantenimiento",["Todo trabajo sobre la faja se realiza con el equipo detenido y bloqueado según el procedimiento de control de energía.","La parada de emergencia no se usa como medio de bloqueo para trabajos de mantenimiento.","Los contrapesos están confinados en un recinto asegurado que impide el paso de personal por debajo de la carga.","Los anti-retrocesos o frenos están instalados en las fajas y alimentadores inclinados y declinados.","La estructura de la faja está limpia, sin acumulación de derrames que la sobrecarguen."]]]},{"k":"equipos-moviles-linea-amarilla","n":"Equipos móviles y línea amarilla","ft":"Check list de pre-uso diario antes de operar. Certificado de operatividad semestral emitido por representante autorizado del fabricante. Auditoría anual del programa de mantenimiento e inspección técnica vehicular según D.S. 025-2008-MTC.","c":["Código de equipo","Tipo","Operador"],"b":[["Documentación y operador",["El operador cuenta con licencia de conducir vigente del MTC y con licencia interna de operación del titular minero.","El operador de línea amarilla cuenta como mínimo con licencia A-I y con autorización para el equipo específico.","El check list de pre-uso del día está llenado, firmado y con las observaciones levantadas.","El certificado de operatividad del equipo está vigente.","El resultado del alcotest del operador es 0.00%.","El operador cumplió el descanso mínimo de 7 horas continuas antes del turno."]],["Sistemas de seguridad del equipo",["La alarma de retroceso es audible a 10 m de distancia en nivel de ruido normal.","El cinturón de seguridad está operativo y el sistema bloquea la operación si no está abrochado.","La cabina cuenta con estructura ROPS o FOPS según el riesgo de volcadura o caída de objetos.","La luz estroboscópica ámbar de mínimo 10 cm de diámetro está instalada y operativa.","Los equipos articulados cuentan con sensor de puerta abierta con bloqueo automático.","Los volquetes cuentan con inclinómetro y con alarma de levante de tolva operativos.","Los equipos de mina subterránea cuentan con sistema de supresión de incendios operativo y con inspección vigente."]],["Estado mecánico",["Los frenos de servicio, de estacionamiento y de emergencia fueron probados y están operativos.","Los neumáticos tienen la cocada mínima según el tipo de vía y no presentan cortes ni desgaste irregular.","No hay fugas de aceite, combustible ni refrigerante en el equipo.","El parabrisas es de vidrio laminado templado, sin fisuras ni adhesivos que obstruyan la visión.","Las luces delanteras, posteriores, de freno y direccionales funcionan correctamente."]],["Accesorios de emergencia",["El extintor de mínimo 4 kg está operativo, con precinto intacto y tarjeta vigente.","Las cuñas de seguridad tienen una altura igual o mayor a un cuarto del diámetro del neumático.","El equipo lleva dos conos de 0.60 m, cinta reflectiva de 2 pulgadas, botiquín, cable de remolque, llave de tuercas, gata y linterna con batería."]]]},{"k":"instalaciones-electricas-y-puesta-a-tierra","n":"Instalaciones eléctricas y puesta a tierra","ft":"Inspección mensual de tableros, extensiones y cables eléctricos. Verificación diaria de la conexión a tierra de los equipos eléctricos (art. 271). Medición de resistencia de pozos a tierra según el programa anual.","c":[],"b":[["Tableros y acometidas",["Los tableros están rotulados, cerrados con llave y con los circuitos identificados.","Los interruptores diferenciales fueron probados con instrumento y el resultado está registrado.","No hay cables expuestos, empalmes improvisados ni conductores fuera de canalización.","Los tableros están libres de materiales almacenados y con al menos 1 m de espacio libre de trabajo.","La señalización de riesgo eléctrico está instalada en tableros, celdas y subestaciones."]],["Puesta a tierra",["La conexión a tierra de los equipos eléctricos fue verificada en el turno y está registrada.","Los pozos a tierra cuentan con medición de resistencia vigente y dentro del valor de diseño.","Las estructuras metálicas, tanques y equipos están conectados al sistema de puesta a tierra.","Los cables de puesta a tierra no presentan cortes, corrosión ni conexiones flojas."]],["Trabajos eléctricos e iluminación",["Los trabajos sin tensión aplican las cinco reglas de oro: corte efectivo, bloqueo, verificación de ausencia de tensión, puesta a tierra y en cortocircuito, y señalización.","El EPP dieléctrico cuenta con hoja de vida actualizada y con ensayo dieléctrico vigente.","Se respetan las distancias mínimas de seguridad del Código Nacional de Electricidad.","El PETAR eléctrico está emitido y firmado cuando la tarea lo requiere.","Los niveles de iluminación en las labores cumplen los valores del Anexo 37 del reglamento.","Las extensiones y cables portátiles cuentan con la etiqueta del código de colores del trimestre vigente."]]]},{"k":"refugios-mineros-y-salvataje","n":"Refugios mineros y equipos de salvataje","ft":"Inspección mensual del refugio y de los equipos de salvataje. Simulacros y entrenamiento de la brigada según el Programa Anual de Seguridad y Salud Ocupacional.","c":["Código de refugio","Nivel","Capacidad"],"b":[["Estación de refugio",["El refugio está ubicado y señalizado conforme al plano de emergencia de la mina.","La puerta hermética cierra correctamente y el sello perimetral está íntegro.","La autonomía de aire u oxígeno cubre el número de personas y las horas de diseño del refugio.","Los cilindros de oxígeno están dentro de vigencia, con presión adecuada y asegurados.","El sistema de depuración de CO2 con cal sodada está vigente y en cantidad suficiente.","El refugio cuenta con agua, alimentos y frazadas dentro de fecha de vigencia.","El sistema de comunicación con superficie está operativo y fue probado.","La iluminación de emergencia y las baterías del refugio están operativas.","Los planos de escape y las instrucciones de uso están publicados en el interior del refugio.","La bitácora de inspección del refugio está firmada y al día."]],["Equipos de salvataje y autorrescate",["Los autorrescatadores del personal están sin abolladuras, con precinto intacto y dentro de vigencia.","Los equipos de respiración autónoma de la brigada tienen presión adecuada y prueba vigente.","El equipamiento de la brigada de salvataje está completo según el Anexo 20 del reglamento.","Los detectores multigas de la brigada cuentan con calibración vigente.","El registro de entrenamiento y simulacros de la brigada de salvataje está actualizado."]]]},{"k":"depositos-de-relaves-y-geotecnia","n":"Depósitos de relaves, pads, pilas de lixiviación y botaderos","ft":"Inspección permanente por ingeniero especializado en geotecnia, con reporte mensual de la supervisión de cada componente (art. 323, modificado por el D.S. 034-2023-EM).","c":[],"b":[["Geometría y estabilidad",["La cota de coronación y el borde libre o revancha están dentro del diseño aprobado.","La altura de banco, el ancho de berma y el ángulo de talud corresponden al diseño.","No se observan grietas de tracción, asentamientos ni abombamientos en el talud.","No hay evidencia de filtraciones, tubificación ni surgencias en el pie del talud."]],["Instrumentación y monitoreo",["Los piezómetros, inclinómetros y prismas están operativos y con lecturas dentro de los umbrales establecidos.","El nivel freático está por debajo del umbral definido en el diseño.","Los hitos de control topográfico están íntegros y con lectura vigente."]],["Manejo de aguas",["Los canales de coronación y de derivación están limpios y operativos.","El sistema de subdrenaje descarga libremente y con caudal dentro de lo esperado.","La poza de contingencia tiene capacidad disponible y la geomembrana está sin daños."]],["Operación y control documentario",["La tasa de riego de la pila de lixiviación no supera el valor de diseño.","La descarga de relaves sigue el plan operativo aprobado.","El reporte mensual del ingeniero especializado en geotecnia está emitido y firmado.","Los accesos, la señalización y el control de ingreso al depósito están operativos."]]]},{"k":"herramientas-y-accesorios-de-izaje","n":"Herramientas, equipos y accesorios de izaje","ft":"Inspección trimestral con código de colores para herramientas manuales y eléctricas (enero-marzo negro, abril-junio blanco, julio-setiembre verde, octubre-diciembre azul). Inspección mensual de accesorios de levante en almacén y verificación pre-uso diaria en operación.","c":["Código","Tipo de accesorio","Capacidad"],"b":[["Código de colores",["La herramienta lleva la cinta o etiqueta del color correspondiente al trimestre vigente.","La etiqueta está adherida al cable en herramientas eléctricas y al mango en herramientas no eléctricas.","No hay herramientas en uso con el color de un trimestre vencido."]],["Herramientas manuales",["Los mangos están completos, sin rajaduras y firmemente asegurados a la cabeza de la herramienta.","Llaves, alicates y destornilladores no presentan bocas deformadas ni puntas desgastadas.","Los cinceles y punzones no presentan deformación en hongo en la cabeza.","No hay herramientas hechizas sin validación de diseño, dossier de control de calidad y certificación externa."]],["Herramientas eléctricas",["El cable de alimentación está sin cortes, sin empalmes y sin reparaciones con cinta aislante.","El enchufe es de tres espigas con puesta a tierra verificada, o el equipo es de doble aislamiento.","Las guardas de disco o de sierra están instaladas y operativas.","El interruptor de hombre muerto funciona y no está bloqueado ni trabado."]],["Accesorios de izaje",["Eslingas, estrobos, grilletes, ganchos y cáncamos cuentan con código de identificación y carga de trabajo marcada.","Se descartan las eslingas con picaduras, oxidación avanzada, deformaciones, zonas aplanadas, grietas o deslizamiento del cable en los terminales.","Se retiran los cables con daño en el alma, daño por calor, seis alambres rotos en un paso o tres en un torón.","Los grilletes son de acero forjado, con pasador de seguridad recto y sin reemplazo por perno ni pasador roscado.","Los ganchos cuentan con seguro o clip y su apertura de garganta no excede el 15% de la medida original.","Las herramientas y accesorios defectuosos están retirados del servicio con tarjeta de NO OPERAR o FUERA DE SERVICIO."]]]}]},"hidrocarburos":{"n":"Hidrocarburos","i":[{"k":"tanques-de-almacenamiento","n":"Tanques de almacenamiento atmosféricos y a presión","ft":"Verificación externa periódica según el Programa Anual de Actividades de Seguridad (PAAS). Inspección formal según API 653 para tanques atmosféricos y API 510 para tanques a presión, con intervalo máximo de cinco años en tanques de GLP.","c":["Código de tanque","Producto","Capacidad"],"b":[["Integridad y registros",["El tanque cuenta con inspección periódica vigente según API 653 o API 510 en su última edición.","El intervalo desde la última inspección no excede los cinco años en tanques de GLP.","El inspector que emitió el informe está certificado API 653 o API 510, o acreditado por INDECOPI, IAF o ILAC.","El libro de registro de inspecciones está legalizado por notario y consigna fabricante, número de serie y pruebas periódicas.","El tanque no presenta corrosión, abolladuras ni deformaciones que comprometan su integridad y operación segura."]],["Accesorios de seguridad",["El tanque cuenta con medidor de nivel de líquido cuya lectura es accesible o visible desde el nivel del suelo.","Cuenta con medidor de nivel máximo, medidor flotante o rotativo y termómetro operativos.","El manómetro está calibrado, fijado directamente al recipiente, con rango de 0 a 300 psi y diámetro no menor a 0.15 m.","Las válvulas de seguridad están instaladas conforme a ASME Sección VIII o NFPA 58 y con calibración vigente.","Las válvulas están entubadas y protegidas contra el ingreso de elementos extraños.","El sistema de venteo normal y de emergencia está operativo, con malla o arrestallamas donde corresponde.","Las válvulas internas y de emergencia cuentan con cierre remoto y actuador térmico operativos.","La estación de cierre remoto está ubicada entre 7.60 m y 30.5 m del punto de trasiego."]],["Condiciones externas y accesos",["El tanque está pintado en colores claros para evitar la absorción de calor.","Los tanques de GLP en superficie están instalados a una altura no menor de 1 m desde el nivel del suelo.","Los tanques soterrados cuentan con anclaje antiflotación y cobertura conforme a NFPA 58.","La escalera de acceso es fija, metálica o incombustible, con peldaños completos y sin corrosión.","La pasarela entre tanques es metálica y cuenta con barandas de altura mínima de 1 m.","El tanque está conectado al sistema de puesta a tierra y la medición de resistencia está vigente.","Existen cercos, barreras o topes que protegen el tanque contra daños mecánicos."]],["Nivel de llenado",["El tanque no excede la cantidad máxima de llenado de GLP líquido establecida en las tablas de la NFPA 58.","El sistema de alarma o de corte automático por alto nivel está instalado y operativo."]]]},{"k":"diques-de-contencion-y-area-de-tanques","n":"Diques de contención y área de tanques","ft":"Inspección mensual del área de tanques dentro del Programa Anual de Actividades de Seguridad, con recorrido semanal de verificación de estanqueidad y limpieza.","c":[],"b":[["",["La capacidad volumétrica del dique no es menor al 110% del volumen del tanque mayor.","La altura interior del dique está entre 0.60 m y 1.80 m.","El pie exterior del dique está a no menos de 5 m del lindero de propiedad.","La pendiente del terreno hacia el exterior del dique no es menor al 1%.","En instalaciones de GLP la capacidad del dique es al menos el 25% del volumen del tanque mayor.","El dique es estanco y no presenta fisuras, perforaciones ni erosión.","La válvula de drenaje del dique está cerrada y asegurada con candado o precinto.","El interior del dique está libre de vegetación, residuos y materiales combustibles.","El sistema de encauzamiento de derrames conduce el producto hacia un punto seguro.","El drenaje pluvial pasa por trampa o separador de hidrocarburos operativo.","Las escaleras de acceso al dique están instaladas en los puntos requeridos.","Los pozos de monitoreo de napa están identificados, con tapa y con muestreo vigente.","La señalización de prohibido fumar, peligro inflamable y producto almacenado está instalada y legible.","El acceso al área de tanques está restringido y controlado."]]]},{"k":"lineas-tuberias-y-valvulas","n":"Líneas, tuberías, válvulas y bombas","ft":"Inspección de rutina mensual según el Programa Anual de Actividades de Seguridad. La medición de espesores se ejecuta según el plan de integridad mecánica de la instalación.","c":[],"b":[["Tuberías",["Las tuberías no presentan corrosión, abolladuras, fugas ni goteos.","Los soportes, anclajes y el alineamiento de las líneas están íntegros.","La medición de espesores está dentro del programa de integridad y con resultado vigente.","Las tuberías están pintadas con base anticorrosiva y con el código de colores de la NTP 399.009.","En instalaciones de GLP no se emplea fierro fundido, bronce, cobre ni mangueras en líneas fijas.","Las juntas y bridas están completas, con pernos y empaquetaduras, y sin fugas."]],["Válvulas y sistemas de alivio",["Las válvulas están identificadas y su posición abierta o cerrada corresponde al diagrama operativo.","Las válvulas de seguridad de líneas de GLP abren a una presión no menor de 400 psig.","Las válvulas de alivio hidrostático están instaladas en los tramos que pueden quedar bloqueados.","Las válvulas operan sin trabas y los vástagos y volantes están completos.","Las válvulas de cierre de emergencia fueron probadas y el registro está firmado."]],["Bombas y compresoras",["Las bombas están instaladas sobre base de concreto de dimensiones apropiadas y ancladas.","Las bombas cuentan con topes de concreto, guardas o postes que las protegen del impacto de vehículos.","Los motores instalados en área clasificada son a prueba de explosión y con interruptor automático.","La conexión a tierra para descarga de corriente estática está instalada y verificada.","Los acoples, fajas y partes móviles cuentan con guardas instaladas.","El sistema de retorno automático por mínimo flujo opera correctamente.","No se observan fugas en sellos mecánicos ni en empaquetaduras."]]]},{"k":"sistemas-contra-incendio","n":"Sistema contra incendio de agua, espuma y enfriamiento","ft":"Pruebas y mantenimiento por componente según NFPA 25 y el Programa Anual de Actividades de Seguridad: arranque semanal de bombas, verificación mensual de red y accesorios, y revisión anual integral con simulacro del Plan de Respuesta a Emergencias.","c":[],"b":[["Reserva de agua y bombas",["El volumen de agua almacenada garantiza cuatro horas de autonomía cuando no hay red pública ni compañía de bomberos.","El volumen garantiza dos horas de autonomía cuando existe compañía de bomberos y fuente permanente de agua.","El volumen garantiza una hora de autonomía cuando existe hidrante público a no más de 100 m.","La bomba contra incendio está listada o certificada conforme a NFPA 20.","La bomba arrancó en la prueba y el registro del arranque está firmado.","El sistema de activación automática de la bomba está operativo.","El tanque de combustible de la bomba diésel está por encima de dos tercios de su capacidad."]],["Red, enfriamiento y alarmas",["Las baterías de arranque y los cargadores de la bomba están operativos.","El grupo electrógeno o la alimentación alterna arranca y toma carga ante falla de la red.","El régimen de agua de enfriamiento es de al menos 10.2 litros por minuto por metro cuadrado de área expuesta.","Los aspersores de enfriamiento de tanques están instalados, sin remoción ni obstrucciones.","El sistema de enfriamiento por aspersión responde tanto en actuación automática como manual.","Las tuberías de la red no presentan obstrucciones, fugas ni corrosión.","Las válvulas remotas están ubicadas en lugares no comprometidos por el siniestro y están señalizadas.","Los monitores, hidrantes y gabinetes están operativos y con acceso libre.","El concentrado de espuma está dentro de vigencia y en cantidad suficiente, con conexiones instaladas según NFPA 11.","El sistema de alarma de incendio avisa en forma efectiva y oportuna a todo el personal y existe línea directa con la Central de Bomberos."]]]},{"k":"extintores-portatiles-y-rodantes","n":"Extintores portátiles y rodantes","ft":"Verificación mensual con tarjeta de inspección firmada. Mantenimiento y recarga anual, y prueba hidrostática según el intervalo de la NFPA 10.","c":["Código","Ubicación","Tipo","Clase","Capacidad"],"b":[["",["La cantidad de extintores corresponde al tipo de instalación y al riesgo evaluado.","En plantas envasadoras de GLP se cuenta con al menos ocho extintores portátiles de PQS con capacidad de extinción certificada mínima de 120BC.","En plantas envasadoras de GLP se cuenta con al menos dos extintores rodantes de PQS con capacidad de extinción certificada mínima de 320BC.","En grifos y estaciones de servicio los extintores son de PQS multipropósito ABC con rating no menor a 20A:80B:C y certificación UL.","La certificación del extintor está vigente y la etiqueta es legible.","El manómetro marca dentro del rango operativo y el precinto está intacto.","La tarjeta de inspección mensual está firmada y al día.","La recarga y la prueba hidrostática están dentro de vigencia.","La manguera, la boquilla y el percutor están en buen estado.","El extintor está instalado a la altura reglamentaria, señalizado y con acceso libre.","En establecimientos con GLP en cilindros existe un extintor de 80B:C a no más de 15 m de los racks.","No hay extintores vencidos, descargados, inoperativos ni obstruidos en servicio.","El personal del turno conoce la ubicación y el uso del extintor más cercano a su puesto."]]]},{"k":"clasificacion-de-areas-e-instalaciones-electricas","n":"Clasificación de áreas, instalaciones eléctricas y puesta a tierra","ft":"Verificación anual del plano de clasificación de áreas y de la certificación de equipos, con medición anual de resistencia de pozos a tierra. Verificación operativa de la puesta a tierra en cada operación de trasiego. Osinergmin tipifica varias de estas condiciones como de criticidad alta.","c":[],"b":[["Equipos en área clasificada",["Los equipos eléctricos instalados en zona de riesgo corresponden a la clase, división y grupo de la clasificación del área.","Los equipos a prueba de explosión llevan inscripción o certificado visible de marca, clase, división y entidad certificadora.","Las balanzas, motores y termoselladores en zona clasificada cuentan con aptitud certificada Clase I, División 1 o 2.","Las luminarias instaladas en zona clasificada cuentan con certificación de clase y división.","Los cables y el alambrado en zona clasificada cumplen los requisitos de Clase I, Grupo D y están entubados, empotrados o soterrados con sellos cortafuego."]],["Distancias y corte de energía",["No hay líneas eléctricas ajenas a la instalación cruzando el establecimiento.","Existen al menos dos interruptores operativos para el corte de energía general, uno interior y otro alejado del perímetro de riesgo.","La caja de interruptores está a más de 3 m de tubos de ventilación, bocas de llenado y equipos de despacho.","Los surtidores, conexiones de tanques y ventilaciones están a no menos de 7.60 m del lindero de estaciones o subestaciones eléctricas.","Se cumple la distancia mínima a la proyección horizontal de las líneas aéreas de electricidad.","El sistema de pararrayos está instalado donde la ubicación geográfica lo exige y con medición vigente."]],["Puesta a tierra y electricidad estática",["Todas las estructuras metálicas, bombas, plataformas y tanques están conectados al sistema de puesta a tierra.","La medición de resistencia de los pozos a tierra está vigente y dentro del valor de diseño.","El sistema de descarga de estática de los surtidores y dispensadores está operativo.","El cable y la pinza de conexión equipotencial para el camión cisterna están disponibles y en buen estado.","El dispositivo de descarga de estática para el personal está instalado en el ingreso a zonas de riesgo y es utilizado.","Las bridas de tuberías cuentan con puentes de continuidad eléctrica donde corresponde.","El cartel de no operar sin conexión a puesta a tierra está instalado en la zona de carga y descarga.","El plano de clasificación de áreas está disponible y coincide con lo instalado en campo."]]]},{"k":"atmosferas-explosivas-y-deteccion-de-gases","n":"Atmósferas explosivas y detección de gases","ft":"Prueba funcional mensual de los detectores fijos y sus alarmas según el Programa Anual de Actividades de Seguridad. Calibración según recomendación del fabricante y bump test antes de cada uso en los equipos portátiles.","c":[],"b":[["",["Los detectores fijos de gases combustibles están instalados en los puntos definidos por el Estudio de Riesgos.","Los detectores fijos están operativos y con calibración vigente.","La alarma sonora y visual asociada a los detectores se activa en la prueba de funcionamiento.","La señal de los detectores llega al panel de control y al puesto de vigilancia permanente.","Se cuenta con al menos dos exposímetros portátiles operativos y con calibración periódica.","El rango de medición de los equipos cubre el 100% del límite inferior de explosividad.","Los detectores portátiles cuentan con bump test del día registrado.","Existe registro de las calibraciones con el patrón de gas empleado y su fecha de vigencia.","Los puntos de detección no están obstruidos ni fuera de servicio sin señalización.","El sistema de alarma sonora de incendio está instalado, es audible en toda la instalación y está operativo.","El personal está entrenado en la lectura e interpretación de los equipos de detección."]]]},{"k":"trabajos-en-caliente","n":"Permiso de trabajo y trabajos en caliente","ft":"Por cada trabajo. El permiso tiene validez limitada al alcance, ubicación y horario que consigna, y se cierra formalmente al término de la tarea.","c":[],"b":[["Permiso y condiciones previas",["El permiso de trabajo está emitido por escrito, vigente y firmado por el emisor y por el ejecutor.","El permiso indica alcance, ubicación exacta, horario de validez y ejecutantes autorizados.","El área fue drenada, purgada, ventilada y aislada de fuentes de hidrocarburo.","Los drenajes, buzones y aberturas dentro del radio de trabajo están sellados.","El área está señalizada y acordonada para restringir el ingreso de terceros."]],["Control de la atmósfera",["Se realizó la medición de gases previa y el resultado es 0% del límite inferior de explosividad en el radio de trabajo.","El equipo de medición de gases tiene calibración vigente y se le realizó bump test.","Se mantiene monitoreo continuo de la atmósfera durante todo el trabajo."]],["Ejecución y cierre",["Se instalaron biombos o mantas ignífugas para contener chispas y escoria.","Existe extintor operativo o manguera presurizada al alcance inmediato del punto de trabajo.","Se designó un vigía de fuego que permanece durante el trabajo y al menos 30 minutos después de finalizado.","Los equipos de soldadura y oxicorte están en buen estado, con arrestallamas y sin fugas.","Los cilindros de gases están asegurados en posición vertical y con capuchón cuando no se usan.","El personal usa el EPP específico para trabajo en caliente: careta, mandil, escarpines y guantes.","Al cierre del permiso se verificó que no queden fuentes de ignición ni material caliente en el área."]]]},{"k":"espacios-confinados","n":"Ingreso a espacios confinados","ft":"Por cada ingreso. El permiso pierde validez ante cualquier cambio en las condiciones del espacio o al término del turno consignado.","c":[],"b":[["Permiso y aislamiento",["El permiso de ingreso a espacio confinado está emitido, vigente y firmado.","El espacio está identificado, señalizado e incluido en el inventario de espacios confinados.","Se ejecutó el aislamiento, bloqueo y colocación de bridas ciegas en todas las líneas de ingreso.","El espacio fue drenado, purgado y ventilado antes de autorizar el ingreso."]],["Control de la atmósfera",["La medición de oxígeno está entre 19.5% y 23.5%.","La medición de gases inflamables registra 0% del límite inferior de explosividad.","Los gases tóxicos como sulfuro de hidrógeno, monóxido de carbono y benceno están por debajo del límite permisible.","La medición se repite de forma continua o a intervalos definidos durante toda la permanencia.","Se mantiene ventilación forzada durante todo el trabajo."]],["Vigilancia y rescate",["Existe vigía u observador permanente en el exterior que no abandona su puesto.","El registro de entradas y salidas de personal se lleva en tiempo real.","Se cuenta con equipo de rescate: trípode, arnés, línea de vida y equipo de respiración autónoma.","La iluminación y las herramientas usadas en el interior son antichispa o de 24 voltios.","El plan de rescate está definido y la brigada de emergencia fue notificada del trabajo.","El personal cuenta con capacitación específica vigente y examen médico de aptitud."]]]},{"k":"bloqueo-y-etiquetado-loto","n":"Bloqueo y etiquetado de energías (LOTO)","ft":"Por cada intervención de mantenimiento o de trabajo sobre equipos con energías peligrosas, desde el aislamiento hasta el retiro del último candado.","c":[],"b":[["",["Se identificaron todas las fuentes de energía del equipo: eléctrica, hidráulica, neumática, térmica, gravitacional y química.","Cada ejecutante colocó su candado personal y su tarjeta de identificación en el punto de aislamiento.","Se emplea caja de bloqueo grupal cuando participan varias especialidades en el trabajo.","Se verificó la ausencia de energía mediante prueba de arranque antes de iniciar la intervención.","Las válvulas críticas están bloqueadas con dispositivo mecánico y no solamente cerradas.","Se instalaron bridas ciegas o se desconectaron líneas donde el bloqueo de válvula no es suficiente.","Se liberó y purgó la energía residual: presión, drenaje y descarga de condensadores.","Los elementos con energía gravitacional están calzados o soportados mecánicamente.","Las tarjetas de bloqueo indican responsable, fecha, hora y motivo de la intervención.","No existen candados huérfanos ni bloqueos vencidos sin responsable identificado.","El retiro del bloqueo lo realiza únicamente quien lo colocó, previa verificación del área.","El registro de bloqueo y desbloqueo está firmado por el responsable."]]]},{"k":"trasiego-carga-y-descarga","n":"Trasiego, carga y descarga de combustible","ft":"Por cada operación de transferencia, desde el posicionamiento de la unidad hasta la verificación final de cierre de válvulas y ausencia de fugas.","c":[],"b":[["Personal y posicionamiento",["El Supervisor de Seguridad está presente en el lugar durante las operaciones de trasiego y envasado.","El personal encargado permanece en el lugar desde el comienzo hasta el término de la transferencia.","La distancia entre el camión cisterna y el tanque estacionario es de al menos 3 metros.","El vehículo está calzado con tacos y con el motor apagado.","La conexión equipotencial de puesta a tierra está instalada antes de abrir cualquier válvula."]],["Mangueras y conexiones",["Las mangueras están libres de dobleces y pliegues, tanto en uso como en reposo.","Las mangueras cuentan con marcado de producto cada 3 m, presión de trabajo y fabricante.","Las mangueras de GLP tienen resistencia a la ruptura no menor a 120 kg/cm2 y presión de trabajo no menor a 24.6 kg/cm2.","La manguera cuenta con válvula de cierre rápido en el extremo libre.","La manguera cuenta con válvula de alivio hidrostático instalada.","Las tomas de carga están protegidas con tapón o capuchón cuando no están en uso y protegidas del rozamiento contra el piso."]],["Dispositivos de emergencia y cierre",["La válvula de emergencia cuenta con activador térmico, cierre manual remoto y cierre operativo en sitio.","La temperatura de fusión del elemento térmico no es superior a 121 grados Celsius.","El elemento sensible está ubicado a máximo 1.5 m y sin obstrucciones.","La tubería está anclada para prevenir tracción excesiva sobre la manguera.","Existe extintor operativo al alcance durante toda la operación y no hay fuentes de ignición activas en el radio de seguridad.","Al término se verificó el cierre de válvulas, la desconexión de mangueras y la ausencia de fugas."]]]},{"k":"unidades-de-transporte-cisternas","n":"Unidades de transporte de hidrocarburos y camiones cisterna","ft":"Verificación pre-uso diaria por el conductor y control en el ingreso y salida de planta. Inspección técnica vehicular y prueba de hermeticidad del tanque según la vigencia de cada certificado. Osinergmin y SUTRAN fiscalizan mediante operativos.","c":["Placa","Conductor","Producto"],"b":[["Documentación",["La unidad está inscrita en el Registro de Hidrocarburos de Osinergmin y la inscripción está vigente.","La unidad cuenta con póliza de responsabilidad civil vigente y con cobertura adecuada.","El conductor tiene licencia de la categoría requerida y capacitación vigente en materiales peligrosos.","La unidad cuenta con certificado de inspección técnica vehicular vigente.","La unidad lleva la hoja de datos de seguridad del producto transportado y la guía de remisión."]],["Tanque y sistemas",["El tanque cisterna no presenta abolladuras, fisuras, corrosión ni fugas.","La prueba de hermeticidad o hidrostática del tanque está vigente.","Las válvulas de carga, descarga, alivio y de emergencia están operativas y sin fugas.","Las conexiones y acoples están completos, sin roscas dañadas ni adaptaciones improvisadas.","Los rompeolas y compartimientos internos del tanque están íntegros.","El sistema de puesta a tierra del vehículo, con cable y pinza, está en buen estado."]],["Rotulado y equipamiento de seguridad",["Los rótulos de identificación de peligro, paneles naranjas y rombos NU, están instalados y legibles.","La unidad cuenta con extintores operativos, con la capacidad y certificación exigidas.","La unidad lleva conos, tacos, botiquín, kit antiderrame y linterna antiexplosiva.","El sistema eléctrico es a prueba de chispa y el tubo de escape cuenta con matachispas.","Los neumáticos, frenos y luces están operativos.","El GPS está operativo y el plan de ruta autorizado se encuentra a bordo."]]]},{"k":"surtidores-y-estaciones-de-servicio","n":"Grifos, estaciones de servicio y gasocentros","ft":"Inspección interna mensual del operador, con recorrido semanal de condiciones críticas. Osinergmin supervisa según programa y cualquier condición del listado de criticidad alta habilita la medida de seguridad de cierre total o parcial.","c":[],"b":[["Autorizaciones e instalaciones",["El establecimiento opera con inscripción vigente en el Registro de Hidrocarburos.","No existen modificaciones ni ampliaciones no autorizadas de tanques de almacenamiento.","No existe aumento ni reubicación no autorizada de surtidores o dispensadores.","Los planos aprobados coinciden con las instalaciones existentes en campo."]],["Tanques y tuberías",["Los tanques enterrados tienen cobertura de al menos 0.45 m de material estabilizado.","Los sistemas con bombas sumergibles cuentan con válvula de cierre automático que actúa a 80 grados Celsius o ante impacto.","Los venteos están instalados a la altura y en la posición reglamentaria, sin obstrucciones.","Las bocas de llenado están identificadas por producto, con tapa hermética y dentro de contención.","Los pozos de monitoreo están identificados, con tapa y con muestreo vigente."]],["Surtidores e islas de despacho",["El sistema de descarga de estática del surtidor o dispensador está operativo.","Las mangueras, pistolas y válvulas de desacople están en buen estado, sin fugas ni cortes.","Los surtidores están protegidos con topes o postes contra impacto vehicular.","No hay racks con cilindros de GLP sobre las islas de despacho."]],["Seguridad general y GLP en cilindros",["El interruptor de corte de energía de emergencia está operativo y en ubicación accesible.","Los servicios de vulcanización están a más de 10 m de venteos, bocas de llenado y equipos de despacho.","Los anuncios luminosos están instalados a más de 3 m de tubos de ventilación y bocas de llenado.","Los racks de cilindros de GLP son metálicos, con ventilación y a no menos de 0.50 m de edificaciones.","Los racks están a no menos de 1.50 m de salidas con dos puertas y a no menos de 3 m de colectores de desagüe.","Los racks de GLP están a no menos de 7.60 m de estaciones o subestaciones eléctricas.","La señalización de prohibido fumar, apague el motor, no use celular y velocidad máxima está instalada y legible."]]]},{"k":"plantas-envasadoras-de-glp","n":"Plantas envasadoras de GLP","ft":"Inspección interna mensual de la planta, con verificación diaria de las condiciones de trasiego y envasado. Osinergmin supervisa según procedimiento y cualquier condición insegura de alta criticidad habilita la medida de cierre.","c":[],"b":[["Tanques y trasiego",["Los tanques estacionarios cuentan con inspección periódica vigente según API 510.","Ningún tanque en operación presenta deterioro que afecte su integridad.","El tanque no excede la cantidad máxima de GLP líquido con la que debe llenarse.","Las estaciones de cierre remoto de válvulas internas y de emergencia están operativas y ubicadas entre 7.60 m y 30.5 m del punto de trasiego.","El Supervisor de Seguridad y el personal encargado permanecen en el lugar durante todo el trasiego y envasado."]],["Plataforma de envasado y múltiples de llenado",["La plataforma de envasado está construida con materiales incombustibles y con ventilación natural adecuada.","Los bordes de la zona de carga están protegidos para evitar chispas por impacto de vehículos.","La tubería, conexiones, válvulas y mangueras del múltiple soportan una presión no menor a 400 psig.","El sistema de envasado, el múltiple y las básculas están conectados a tierra.","La balanza de comprobación es exclusiva para verificación de pesos y su aferición ante INDECOPI está vigente."]],["Sistema contra incendio y detección",["El volumen de agua contra incendio garantiza al menos dos horas de autonomía según el máximo riesgo individual probable.","El sistema de enfriamiento por aspersión de los tanques responde en actuación automática y manual.","La bomba contra incendio está listada, arranca en la prueba y el generador de respaldo toma carga.","Se cuenta con al menos ocho extintores portátiles de 120BC y dos extintores rodantes de 320BC operativos.","Los detectores de gases combustibles y su alarma sonora están instalados y operativos.","Existe sistema de alarma de incendio que avisa en forma efectiva y oportuna a todo el personal."]],["Señalización, distancias y prohibiciones",["Existen al menos dos interruptores operativos para el corte general de energía eléctrica de la planta.","Los equipos eléctricos en zona de llenado y almacenaje son aptos para Clase I, Grupo D y cuentan con certificación visible.","Las áreas de almacenamiento de cilindros y de vehículos de distribución corresponden a lo establecido en el Estudio de Riesgos.","No existen talleres de reparación de unidades automotrices ni talleres generadores de chispas dentro de la planta.","Los carteles de prohibido fumar, velocidad máxima 20 km/h, no operar sin puesta a tierra, peligro gas inflamable y apague el motor están instalados y legibles.","Las vías de circulación interna están señalizadas, despejadas y libres de pastos, desechos y material combustible."]]]}]},"industria":{"n":"Industria (manufactura)","i":[{"k":"guardas-de-maquinas","n":"Guardas y resguardos de máquinas","ft":"Inspección planeada mensual, con verificación pre-uso diaria por el operador y revisión mensual del Comité de Seguridad y Salud en el Trabajo.","c":[],"b":[["",["Todas las partes móviles de máquinas, motores y transmisiones cuentan con resguardo instalado.","Los engranajes y ruedas dentadas están enteramente resguardados.","Las manivelas y vástagos cuentan con resguardo de construcción normalizada.","El resguardo brinda protección positiva e impide todo acceso a la zona de peligro durante la operación.","El resguardo no puede retirarse sin herramienta y no es fácilmente anulable de forma intencional o accidental.","Los resguardos están anclados, sin deformaciones, sin cortes y sin bordes filosos.","No hay máquinas operando con guardas retiradas, puenteadas o incompletas.","El retiro de resguardos se realiza únicamente con la máquina detenida y bloqueada, y con autorización.","Los enclavamientos de puertas y tapas de acceso detienen la máquina al abrirse.","Los pulsadores de parada de emergencia están accesibles, identificados y fueron probados.","La máquina cuenta con dispositivo de corte de energía identificado y accesible.","El área alrededor de la máquina está delimitada y libre de obstáculos.","El nivel de iluminación en el puesto de la máquina es adecuado para la tarea.","La ficha técnica y el procedimiento de operación de la máquina están disponibles en el puesto.","El operador está capacitado y autorizado para operar esa máquina específica.","Las máquinas nuevas fueron adquiridas especificando que incluyan los dispositivos de seguridad requeridos."]]]},{"k":"prensas-y-maquinas-de-accionamiento","n":"Prensas y máquinas de accionamiento","ft":"Prueba funcional mensual de los dispositivos de seguridad, con verificación pre-uso diaria y mantenimiento del freno y embrague según el programa preventivo.","c":[],"b":[["",["La prensa cuenta con mando a dos manos con sincronía y dispositivo anti-repetición de ciclo.","El mando bimanual está instalado a la distancia de seguridad calculada respecto del punto de operación.","La cortina de luz o barrera fotoeléctrica está alineada, sin puenteo y fue probada.","La interrupción de la cortina detiene el ciclo y la prueba está registrada.","El dispositivo antirepetición está instalado y operativo.","El punto de pinzamiento está resguardado mecánicamente.","El pedal de accionamiento está protegido contra activación accidental.","El freno y el embrague están dentro del programa de mantenimiento con registro vigente.","El tiempo de parada de la prensa fue medido y está dentro del valor de diseño.","Se usan herramientas de alimentación y extracción para no ingresar las manos a la zona de troquel.","El troquel o matriz está correctamente sujeto y con bloqueo de seguridad para el cambio.","El cambio de troquel se realiza con la prensa detenida y bloqueada.","Las señales de advertencia de riesgo de atrapamiento están instaladas y legibles.","El operador cuenta con capacitación específica y autorización vigente para la máquina."]]]},{"k":"calderas-y-recipientes-a-presion","n":"Calderas y recipientes a presión","ft":"Inspección y prueba hidrostática según la norma técnica aplicable, habitualmente anual, con libro de servicio autorizado ante el MTPE. Verificación por turno de bitácora, purgas y nivel de agua, y prueba mensual de los dispositivos de seguridad.","c":["Código","Marca","Presión máxima"],"b":[["Documentación",["El equipo cuenta con libro de servicio autorizado y actualizado, disponible para el inspector.","La placa del fabricante con presión máxima de trabajo, año y número de serie está instalada y legible.","El certificado de la última inspección y prueba hidrostática está vigente.","Los ensayos no destructivos y la medición de espesores están dentro del plan de integridad.","El operador cuenta con capacitación o certificación vigente como operador de calderas."]],["Dispositivos de seguridad",["Las válvulas de seguridad están instaladas, calibradas y con certificado vigente.","La válvula de seguridad fue probada manualmente y descarga libremente hacia zona segura.","El manómetro está calibrado, es legible y tiene marcada en rojo la presión máxima de trabajo.","El control de nivel de agua, columna de agua o visor, es legible y está operativo.","El corte por bajo nivel de agua fue probado y detiene el quemador.","El presostato de trabajo y el presostato de seguridad están operativos.","El sistema de purga de fondo y de superficie opera y la purga está registrada por turno."]],["Condiciones de operación y entorno",["No hay fugas de vapor, agua ni combustible en el cuerpo, bridas ni accesorios.","El aislamiento térmico está íntegro y las superficies calientes están protegidas o señalizadas.","La sala de calderas tiene ventilación adecuada, dos salidas y puertas de apertura hacia afuera.","El área está libre de materiales combustibles y con extintor apropiado a la vista.","El tratamiento de agua está controlado y los análisis del período están registrados.","La bitácora de operación del turno está llenada y firmada."]]]},{"k":"montacargas","n":"Montacargas y autoelevadores","ft":"Check list de pre-uso por turno antes de operar. Mantenimiento preventivo según el fabricante y certificación de operatividad periódica; el empleador conserva constancia visible de las inspecciones periódicas.","c":["Código de equipo","Marca y modelo","Operador"],"b":[["Antes de encender",["El operador cuenta con licencia interna o certificación vigente para el tipo de montacargas.","El check list de pre-uso del turno está llenado y firmado.","No hay fugas de aceite hidráulico, combustible ni refrigerante bajo el equipo.","Los neumáticos no presentan cortes, desgaste excesivo ni objetos incrustados.","Las horquillas no presentan fisuras, deformación ni desgaste mayor al 10% del espesor original.","El pasador o seguro de las horquillas está instalado.","Las cadenas de elevación están lubricadas, sin eslabones dañados y con tensión pareja.","El respaldo de carga y el techo protector están instalados y sin deformaciones.","La placa de capacidad de carga está instalada y legible."]],["Con el equipo encendido",["Los frenos de servicio y de estacionamiento operan correctamente.","La dirección responde sin juego excesivo.","La bocina, la alarma de retroceso y la baliza funcionan.","Las luces delanteras y posteriores funcionan.","El mástil sube, baja e inclina sin trabas ni descuelgue de la carga.","El cinturón de seguridad está operativo y el operador lo utiliza.","Los mandos hidráulicos retornan a neutro al soltarlos.","El extintor del equipo está operativo y con tarjeta vigente."]],["Operación",["El montacargas circula con la carga a baja altura y con el mástil inclinado hacia atrás.","No se transportan personas sobre las horquillas ni en el contrapeso.","Se respetan las vías señalizadas, la velocidad máxima y los cruces con peatones.","La estación de carga de baterías está en área ventilada, con lavaojos y sin fuentes de ignición."]]]},{"k":"almacenes-y-racks","n":"Almacenes, racks y estanterías","ft":"Verificación visual semanal por el responsable de almacén e inspección técnica anual de la estructura de racks por personal competente.","c":[],"b":[["",["Los racks cuentan con placa de capacidad de carga por nivel, visible y legible.","No se excede la carga máxima por nivel ni por módulo.","Los parantes están anclados al piso, sin deformaciones, golpes ni corrosión.","Los protectores de columna y guardarraíles están instalados en los puntos de tránsito de montacargas.","Las vigas o largueros tienen sus pasadores de seguridad instalados.","No hay elementos del rack faltantes, improvisados ni reparados con soldadura no autorizada.","Las cargas están estables, centradas sobre la parihuela y sin volados peligrosos.","Las parihuelas están en buen estado, sin tablas rotas ni clavos salidos.","El apilamiento directo respeta la altura máxima y la relación base-altura definida.","Los pasillos tienen el ancho señalizado y están libres de obstáculos.","La demarcación de pasillos peatonales y de tránsito de montacargas está pintada y visible.","El nivel de iluminación del almacén cumple lo requerido para la tarea.","Los extintores están señalizados, accesibles y con tarjeta vigente.","Las salidas de emergencia están señalizadas, despejadas y con apertura hacia afuera.","Los rociadores y detectores no están obstruidos por la mercadería y se respeta la distancia libre al techo.","Los productos químicos están segregados por compatibilidad y con contención secundaria.","El registro de inspección de racks está firmado y al día."]]]},{"k":"sistemas-electricos","n":"Sistemas e instalaciones eléctricas","ft":"Inspección planeada mensual y prueba mensual de interruptores diferenciales. Termografía de tableros y medición de resistencia de pozos a tierra con periodicidad anual.","c":["Código de tablero","Ubicación"],"b":[["",["Los tableros están rotulados, cerrados y con los circuitos identificados.","Los tableros cuentan con protección diferencial y la prueba del botón de test está registrada.","Existe espacio libre de trabajo frente al tablero de al menos 1 m, sin materiales almacenados.","No hay cables expuestos, empalmes con cinta ni conductores fuera de canalización.","Los tomacorrientes tienen línea a tierra y no presentan sobrecarga por adaptadores múltiples.","Las extensiones eléctricas están en buen estado y no reemplazan instalaciones permanentes.","Las luminarias están completas, con difusor y sin cables colgando.","La señalización de riesgo eléctrico está instalada en tableros, celdas y subestaciones.","El sistema de puesta a tierra tiene medición de resistencia vigente.","Las máquinas y estructuras metálicas están conectadas al sistema de puesta a tierra.","Los trabajos sin tensión aplican las cinco reglas de oro: corte efectivo de fuentes, enclavamiento y bloqueo, verificación de ausencia de tensión, puesta a tierra y en cortocircuito, y señalización.","El EPP dieléctrico cuenta con hoja de vida actualizada y con ensayo dieléctrico vigente.","Se respetan las distancias mínimas de seguridad del Código Nacional de Electricidad.","Los grupos electrógenos y UPS cuentan con mantenimiento y prueba de arranque registrados.","Las instalaciones son inspeccionadas conforme a lo establecido en el Reglamento Interno de Seguridad y Salud en el Trabajo."]]]},{"k":"extintores-y-sistemas-contra-incendio","n":"Extintores y sistemas contra incendio","ft":"Verificación mensual de extintores y equipos, prueba semanal de bombas contra incendio y simulacros conforme al Programa Anual de Seguridad y Salud en el Trabajo.","c":["Código","Ubicación","Tipo","Clase"],"b":[["",["La cantidad, tipo y ubicación de extintores corresponde a la carga combustible y al riesgo del área.","El extintor está en su soporte señalizado, a la altura reglamentaria y con acceso libre.","El manómetro marca dentro del rango operativo y el precinto está intacto.","La tarjeta de inspección mensual está firmada y al día.","La recarga anual y la prueba hidrostática están dentro de vigencia.","La manguera, la boquilla y el gatillo están en buen estado.","Los gabinetes contra incendio están completos con manguera, pitón y llave, y sin candado.","La presión de la red contra incendio está dentro del rango de diseño.","La bomba contra incendio arrancó en la prueba semanal y el registro está firmado.","Los rociadores están libres de obstrucciones, con al menos 45 cm libres bajo el deflector.","Los detectores de humo y las alarmas fueron probados y funcionan.","Las luces de emergencia encienden en la prueba y tienen autonomía suficiente.","Las rutas de evacuación están señalizadas, iluminadas y despejadas.","Las puertas de emergencia abren hacia afuera y la barra antipánico está operativa.","El plano de evacuación está publicado y corresponde a la distribución real del local.","El simulacro del período está ejecutado y cuenta con informe.","Los desperdicios combustibles como trapos con aceite y virutas se disponen en recipientes metálicos con tapa."]]]},{"k":"ergonomia-de-puestos-de-trabajo","n":"Ergonomía de puestos de trabajo","ft":"Evaluación de riesgo disergonómico y monitoreo de factores ergonómicos con periodicidad anual o ante cambio de condiciones del puesto. Verificación del puesto en la inspección planeada mensual.","c":[],"b":[["Manipulación manual de cargas",["La carga manipulada manualmente por varones no supera los 25 kg.","La carga no supera los 15 kg en varones cuando se requiere mayor protección del trabajador.","La carga manipulada por mujeres y adolescentes no supera los 15 kg, y 9 kg cuando se requiere mayor protección.","Se dispone de ayudas mecánicas cuando la carga supera 25 kg en varones o 15 kg en mujeres.","Las cargas con ancho o profundidad mayores a 60 cm fueron reducidas o se manipulan entre dos personas.","Las trabajadoras gestantes están excluidas de la manipulación manual de cargas."]],["Puesto de trabajo de pie",["La altura del plano de trabajo corresponde al tipo de tarea: precisión, fuerza moderada o fuerzas demandantes.","No se realizan tareas por encima de los hombros ni por debajo de las rodillas.","Se evita la combinación de flexión y torsión del tronco.","Se provee tapete antifatiga o apoyo alterno para los pies."]],["Puesto sentado y pantallas de visualización",["La silla es regulable en altura y permite apoyar los pies planos con los muslos en posición horizontal.","La silla tiene cinco ruedas, respaldo lumbar regulable y acolchamiento de al menos 20 mm.","Se provee apoyapiés cuando el trabajador no alcanza el suelo.","La pantalla está a la altura de los ojos y a una distancia no superior al alcance del brazo extendido.","El teclado es independiente y está en el mismo plano que el mouse.","Se provee atril para documentos en tareas de digitación.","La entrada de datos no supera las cinco horas diarias y se aplican pausas de 10 minutos cada 50 minutos."]],["Herramientas y condiciones ambientales",["Las herramientas manuales permiten que todos los dedos rodeen el mango y se usan en postura cómoda.","El nivel de ruido en el puesto no supera los 85 dB para jornada de 8 horas.","En puestos de atención constante y alta exigencia intelectual el ruido no supera los 65 dB.","El nivel de iluminación corresponde a la tarea según la tabla de la norma.","La evaluación de riesgo disergonómico del puesto está ejecutada y cuenta con plan de acción."]]]},{"k":"agentes-fisicos-ruido-iluminacion-ventilacion","n":"Agentes físicos: ruido, iluminación y ventilación","ft":"Monitoreo de agentes físicos con periodicidad anual como mínimo, o ante cambio de las condiciones de trabajo. Verificación de condiciones en la inspección planeada mensual.","c":[],"b":[["",["El monitoreo de ruido ocupacional del período está ejecutado y cuenta con informe.","Los puestos con exposición igual o mayor a 85 dBA en 8 horas están identificados y señalizados.","El personal expuesto usa protección auditiva con nivel de reducción de ruido adecuado al nivel medido.","Los trabajadores expuestos están incluidos en el programa de vigilancia audiométrica.","Los equipos ruidosos cuentan con encapsulamiento, silenciadores o aislamiento.","El nivel de iluminación medido cumple el valor requerido por tipo de tarea.","Las luminarias están completas, limpias y sin lámparas quemadas.","No hay deslumbramiento directo ni reflejos sobre las superficies de trabajo.","La ventilación general renueva el aire y no hay acumulación de calor, vapores ni humos.","Los sistemas de extracción localizada están operativos, con campana en el punto de emisión.","Las mediciones están dentro de los límites y el registro de monitoreo está actualizado.","Los equipos de medición cuentan con certificado de calibración vigente.","Las radiaciones electromagnéticas, cuando aplican al proceso, están evaluadas y controladas."]]]},{"k":"sustancias-quimicas-peligrosas","n":"Sustancias químicas peligrosas","ft":"Inspección mensual del área de almacenamiento y uso, con verificación semanal de duchas y lavaojos. Monitoreo de agentes químicos con periodicidad anual.","c":[],"b":[["",["Todos los productos químicos del área cuentan con hoja de datos de seguridad en español, accesible en el punto de uso.","Los envases están rotulados con el nombre del producto y el pictograma SGA o rombo NFPA legible.","No se usan envases de bebidas ni de alimentos para contener productos químicos.","Los productos incompatibles están segregados según la matriz de compatibilidad.","El almacenamiento cuenta con contención secundaria del 110% del mayor envase.","El área de almacenamiento está ventilada, techada y con acceso restringido.","Existe kit antiderrame completo, señalizado y accesible.","La ducha de emergencia y el lavaojos están operativos, con prueba semanal registrada.","El personal cuenta con capacitación vigente en el manejo de la sustancia y en el uso de la hoja de datos de seguridad.","Se provee y se usa el EPP indicado en la hoja de datos de seguridad.","Los cilindros de gases comprimidos están asegurados en posición vertical, con capuchón y separados por tipo.","El inventario de sustancias químicas está actualizado.","La concentración de contaminantes químicos ambientales está dentro de los valores límite permisibles.","La disposición de envases vacíos y residuos peligrosos sigue el procedimiento, con manifiesto y empresa operadora registrada."]]]},{"k":"equipos-de-proteccion-personal","n":"Equipos de protección personal","ft":"Inspección formal mensual del EPP asignado, con verificación diaria por el supervisor durante la actividad e inspección trimestral del EPP contra caídas.","c":["Nombres y apellidos","DNI","Cargo"],"b":[["",["La entrega de EPP está registrada con firma del trabajador y el registro está actualizado.","El EPP entregado corresponde al riesgo identificado en la matriz IPERC del puesto.","El casco no presenta fisuras, deformación ni degradación por exposición solar, y el tafilete está completo.","Los lentes de seguridad están sin rayaduras que impidan la visión y cuentan con protección lateral.","El protector auditivo es del tipo y nivel de reducción de ruido adecuados al nivel medido en el puesto.","El respirador tiene el filtro o cartucho correcto para el contaminante y dentro de vigencia.","La prueba de ajuste para respiradores de ajuste hermético está ejecutada y registrada.","Los guantes corresponden al riesgo mecánico, químico, térmico o dieléctrico y están sin cortes ni perforaciones.","El calzado de seguridad tiene puntera y suela en buen estado, sin desgaste que anule la propiedad antideslizante.","El arnés de cuerpo entero y la línea de vida tienen inspección vigente, sin cortes ni costuras dañadas.","El EPP dañado se retira del servicio y se reemplaza sin costo alguno para el trabajador.","El EPP se almacena limpio, en el lugar asignado y protegido de la intemperie.","El personal usa correctamente el EPP durante la actividad observada."]]]},{"k":"bloqueo-y-etiquetado-loto","n":"Bloqueo y etiquetado de energías en mantenimiento","ft":"Por cada intervención de mantenimiento sobre equipos con energías peligrosas, desde el aislamiento hasta el retiro del último candado y la reinstalación de resguardos.","c":[],"b":[["",["Se identificaron todas las fuentes de energía del equipo antes de intervenir.","Cada ejecutante colocó su candado y su tarjeta personal en el punto de aislamiento.","Se emplea caja de bloqueo grupal cuando intervienen varias especialidades.","Se verificó la ausencia de energía con prueba de arranque antes de iniciar el trabajo.","La energía residual de presión, vapor, resortes, gravedad y condensadores fue liberada o bloqueada.","Los elementos suspendidos están calzados o soportados mecánicamente.","Las válvulas están bloqueadas con dispositivo mecánico y no solamente cerradas.","Las tarjetas indican responsable, fecha, hora y motivo del bloqueo.","El área está señalizada y delimitada durante la intervención.","El desbloqueo lo realiza únicamente quien colocó el candado, tras verificar que no haya personal en zona de riesgo.","El registro de bloqueo y desbloqueo está firmado.","Los resguardos retirados fueron reinstalados al término del trabajo, antes de energizar el equipo."]]]},{"k":"trabajos-en-altura-y-medios-de-acceso","n":"Trabajos en altura y medios de acceso","ft":"Por cada trabajo mediante permiso. Inspección mensual de escaleras portátiles, semestral de escaleras fijas y trimestral del EPP contra caídas.","c":[],"b":[["",["El trabajo por encima de 1.80 m cuenta con permiso de trabajo en altura vigente y firmado.","El trabajador cuenta con examen médico de aptitud para trabajo en altura vigente.","El arnés de cuerpo entero está inspeccionado, sin cortes, quemaduras ni costuras dañadas.","La línea de vida y el absorbedor de impacto están vigentes y sin evidencia de activación previa.","El punto de anclaje resiste la carga requerida y está certificado o validado por ingeniería.","El factor de caída y la distancia de caída libre fueron calculados y son adecuados al espacio disponible.","Las escaleras portátiles están completas, con zapatas antideslizantes y aseguradas en la parte superior.","La escalera portátil sobresale al menos 1 m del punto de desembarque y guarda la relación 4 a 1.","Las escaleras fijas tienen ancho mínimo de 0.90 m y barandas cuando superan los cuatro peldaños.","Los andamios fueron montados por personal competente y cuentan con tarjeta verde de habilitación.","Los andamios tienen plataformas completas, barandas, rodapiés y acceso interno.","Los andamios están nivelados, arriostrados y con ruedas bloqueadas cuando corresponde.","Las plataformas elevadoras cuentan con certificación e inspección vigentes y con operador autorizado.","El área inferior está delimitada y señalizada para evitar la caída de objetos sobre terceros.","Las herramientas están aseguradas con drizas o portaherramientas.","Las aberturas en piso están cubiertas o protegidas con baranda."]]]},{"k":"lineas-de-produccion-orden-y-limpieza","n":"Líneas de producción, orden y limpieza","ft":"Inspección planeada mensual, con verificación diaria del supervisor al inicio y término de turno.","c":[],"b":[["",["Los pasillos y vías de circulación están demarcados, despejados y con el ancho reglamentario.","Las salidas y rutas de evacuación no están obstruidas.","Los pisos están limpios, sin derrames de aceite, agua o producto, y sin desniveles peligrosos.","Los desagües y canaletas están cubiertos y a nivel del piso.","Los materiales en proceso están en zonas demarcadas y apilados de forma estable.","Las herramientas están en su lugar asignado y no dispersas sobre las máquinas.","Los residuos están segregados en los contenedores señalizados y no acumulados.","Los desperdicios combustibles se disponen en recipientes metálicos con tapa.","La señalización de seguridad del área está instalada, legible y vigente.","Los equipos de emergencia como extintores, ducha, lavaojos, botiquín y camilla están accesibles y señalizados.","El nivel de iluminación es adecuado y no hay luminarias quemadas.","La ventilación y la extracción localizada están operativas.","Los servicios higiénicos y vestuarios están operativos, limpios y en cantidad suficiente.","La altura del local es de al menos 3.5 m en el primer piso y 3 m en los pisos superiores.","Se respeta el aforo de 10 metros cuadrados por trabajador.","Las escaleras internas tienen ancho mínimo de 0.90 m y barandas cuando superan los cuatro peldaños.","Los tableros y equipos energizados no tienen materiales apoyados ni están obstruidos."]]]},{"k":"comite-sst-y-verificacion-documentaria","n":"Comité de SST y verificación documentaria","ft":"Inspección y reunión ordinaria mensual del Comité de Seguridad y Salud en el Trabajo. La notificación al MTPE de accidentes mortales e incidentes peligrosos se realiza dentro de las 24 horas.","c":[],"b":[["Organización",["El Comité de SST está constituido en empresas con 20 o más trabajadores, o existe Supervisor de SST elegido en empresas con menos de 20.","La composición del Comité es paritaria y tiene entre 4 y 12 integrantes.","El acta de elección de los representantes de los trabajadores está suscrita y archivada.","El Libro de Actas registra la constitución, instalación, reuniones y acuerdos del Comité.","Se realizan reuniones ordinarias mensuales y reuniones extraordinarias ante accidente grave."]],["Documentos del sistema de gestión",["El Reglamento Interno de SST está aprobado, actualizado y entregado a los trabajadores bajo cargo.","La política y los objetivos de SST están difundidos y publicados.","El Programa Anual de SST está aprobado y con el avance registrado.","La matriz IPERC está actualizada y fue elaborada con participación de los trabajadores.","El mapa de riesgos está publicado y corresponde a la distribución real del centro de trabajo."]],["Registros obligatorios",["El registro de accidentes de trabajo, incidentes peligrosos y enfermedades ocupacionales está actualizado.","El registro de exámenes médicos ocupacionales está actualizado.","El registro de monitoreo de agentes físicos, químicos, biológicos, ergonómicos y psicosociales está actualizado.","El registro de inspecciones internas de SST está actualizado y consigna el tipo de inspección, objetivo, resultados, causa y recomendaciones.","El registro de estadísticas de SST está actualizado.","El registro de entrega de equipos de protección personal cuenta con la firma del trabajador.","El registro de inducción, capacitación, entrenamiento y simulacros está actualizado.","El registro de auditoría del sistema de gestión está disponible.","El libro autorizado de servicio de equipos a presión, calderos y compresoras está vigente.","La notificación al MTPE de accidentes mortales e incidentes peligrosos se realizó dentro de las 24 horas."]],["Cierre de ciclo",["Los hallazgos de la inspección anterior fueron levantados dentro del plazo establecido.","Las recomendaciones se registraron con responsable asignado y fecha de implementación."]]]}]},"salud":{"n":"Salud","i":[{"k":"residuos-de-salud","n":"Residuos del establecimiento de salud","ft":"Inspección mensual de los puntos de generación y de los almacenamientos intermedio y central.","c":[],"b":[["Segregación donde se genera",["Cada ambiente tiene tachos con bolsa roja (biocontaminados), negra (comunes) y amarilla (especiales).","En la bolsa roja no hay residuos comunes y en la negra no hay residuos con sangre ni fluidos.","Los químicos peligrosos y los medicamentos vencidos se separan como especiales (bolsa amarilla).","Los recipientes se llenan solo hasta 3/4 de su capacidad."]],["Punzocortantes",["Hay recipiente rígido, impermeable y resistente a la perforación donde se usan agujas.","El recipiente tiene tapa hermética y el rótulo «RESIDUO PUNZOCORTANTE» con el símbolo de bioseguridad.","Ningún recipiente pasa de 3/4 y ninguno se reutiliza.","Las agujas no se reencapuchan."]],["Almacenamiento intermedio",["Existe en las áreas que generan más de 150 litros por día.","Los residuos no permanecen más de 12 horas.","Los contenedores están tapados y limpios, y las bolsas no se comprimen.","El acceso está restringido y señalizado, con control de vectores."]],["Almacenamiento central y personal",["Biocontaminados y comunes no pasan de 48 horas (72 horas solo como excepción, con informe).","Los especiales no pasan de 30 días calendario.","El personal que recolecta está capacitado y usa su equipo de protección personal.","Se usan carros: las cargas manuales no pasan de 25 kg (varones) ni de 15 kg (mujeres)."]]]},{"k":"movilizacion-de-pacientes","n":"Movilización de pacientes y ayudas mecánicas","ft":"Inspección mensual de los servicios que movilizan pacientes (hospitalización, emergencia, sala de operaciones).","c":[],"b":[["Ayudas mecánicas",["Hay grúa de pacientes, tabla de transferencia o sábana deslizante en el servicio.","Las ayudas mecánicas funcionan y tienen su mantenimiento al día.","El personal sabe usarlas (capacitación registrada)."]],["Organización",["Los pacientes dependientes se movilizan entre dos o más personas o con ayuda mecánica.","Las trabajadoras gestantes no movilizan pacientes ni cargas a mano.","Camas y camillas tienen altura regulable y frenos operativos."]],["Posturas y reporte",["Al acomodar al paciente se evita la flexión del tronco combinada con torsión.","Las molestias y lesiones de espalda del personal se registran y se investigan."]]]},{"k":"epp-del-personal","n":"Equipos de protección personal","ft":"Verificación diaria del supervisor; inspección formal mensual por trabajador","c":["Nombres y apellidos","DNI","Cargo"],"b":[["EPP por trabajador",["Casco de seguridad","Lentes de seguridad","Barbiquejo","Zapatos de seguridad","Polo con cinta reflectiva","Pantalón drill","Chaleco","Guantes de cuero","Guantes de badana","Guantes de nitrilo","Protector auditivo","Respirador y filtros","Careta facial","Arnés de cuerpo entero","Línea de vida con absorbedor","Uniforme completo y limpio"]]]},{"k":"extintores","n":"Extintores","ft":"Verificación mensual por extintor; recarga anual y prueba hidrostática según norma","c":["Código","Serie","Ubicación","Tipo","Clase","Peso","Marca","Año de fabricación","Fecha de vencimiento","Última prueba hidrostática","Próxima prueba hidrostática"],"b":[["Estado del extintor",["La presión del manómetro está en la zona verde.","El precinto y el seguro están intactos.","La señalización del extintor es visible desde cualquier punto del área.","El acceso al extintor está libre de obstáculos.","La tarjeta de inspección está firmada y vigente.","La manguera y la boquilla están sin fisuras ni obstrucciones.","El cilindro no presenta abolladuras, corrosión ni pintura desprendida.","El soporte o gabinete está fijo y a la altura reglamentaria.","La cinta del color del mes corresponde al mes en curso.","El extintor está dentro de su fecha de vencimiento."]]]},{"k":"tableros-electricos","n":"Tableros eléctricos","ft":"Inspección mensual por tablero; prueba del diferencial mensual","c":["Código","Ubicación"],"b":[["Caja",["La caja es de material aislante o metálica con puesta a tierra.","Cuenta con parada de emergencia accesible e identificada.","El tablero está identificado con su código y el circuito que alimenta.","Tiene punto de bloqueo para candado (LOTO).","El candado de bloqueo está disponible en el tablero."]],["Protección e interior",["El interruptor diferencial está instalado y la prueba del botón de test quedó registrada.","La tapa interna está colocada y sin partes energizadas expuestas.","Los cables entran por prensaestopas, sin empalmes con cinta ni conductores sueltos.","Los bornes están ajustados y sin señales de recalentamiento.","El tablero cierra completamente y su puerta tiene seguro."]],["Señalización",["Tiene señal de riesgo eléctrico y la indicación del voltaje.","El diagrama unifilar está pegado en el interior y actualizado.","Está libre el espacio de trabajo frente al tablero.","Solo personal autorizado tiene acceso al tablero."]]]},{"k":"botiquin","n":"Botiquín de primeros auxilios","ft":"Verificación mensual del contenido y de las fechas de vencimiento","c":[],"b":[["Botiquín de obra",["02 paquetes de guantes quirúrgicos.","01 frasco de yodopovidona 120 ml solución antiséptica.","01 frasco de agua oxigenada mediano 120 ml.","01 frasco de alcohol mediano 250 ml.","05 paquetes de gasas esterilizadas de 10 cm x 10 cm.","08 paquetes de apósitos.","01 rollo de esparadrapo de 5 cm x 4.50 m.","02 rollos de venda elástica de 3 pulgadas x 5 yardas.","02 rollos de venda elástica de 4 pulgadas x 5 yardas.","01 paquete de algodón x 100 g.","01 venda triangular.","10 paletas bajalenguas para entablillado de dedos.","10 venditas autoadhesivas.","01 frasco de cloruro de sodio al 9/1000 x 1 L para lavado de heridas.","02 paquetes de gasa tipo jelonet para quemaduras.","02 frascos de colirio de 10 ml.","01 tijera punta roma.","01 pinza.","01 frazada.","Resucitador manual o pocket mask.","Ningún insumo está vencido.","El botiquín está señalizado, cerrado y con acceso libre."]],["Botiquín de equipos y vehículos",["01 alcohol de 70° de 120 ml.","01 jabón antiséptico.","05 gasas esterilizadas fraccionadas de 10 cm x 10 cm.","01 apósito esterilizado de 10 cm x 10 cm.","01 esparadrapo de 2.5 cm x 5 cm.","01 venda elástica de 4 pulgadas x 5 yardas.","10 bandas adhesivas (curitas).","01 tijera punta roma de 3 pulgadas.","01 par de guantes quirúrgicos esterilizados 7 1/2.","01 paquete de algodón x 50 g."]]]},{"k":"estacion-de-emergencia","n":"Estación de emergencia","ft":"Verificación mensual de la estación completa","c":[],"b":[["Estación de emergencia",["Botiquín completo y señalizado.","Camilla rígida en buen estado.","Camilla tipo canastilla disponible.","Collarín regulable operativo.","Férula inmovilizadora completa.","Lavaojos portátil con solución vigente.","Frazada limpia y disponible.","Manual o instructivo de primeros auxilios a la vista.","Registro de control y salida de insumos al día.","Extintor operativo y con tarjeta vigente."]],["Camilla rígida y canastilla",["Inmovilizador de cabeza completo.","Correas de seguridad completas y en buen estado.","Collarín cervical regulable operativo.","Eslinga para canastilla de rescate certificada y sin daños."]]]},{"k":"senalizacion-y-codigo-de-colores","n":"Señalización y código de colores","ft":"Inspección mensual por área de trabajo","c":[],"b":[["Servicios de bienestar",["Las oficinas, servicios higiénicos y comedor están debidamente señalizados.","En servicios higiénicos y comedor se señaliza el correcto lavado y desinfección de manos.","Las vías de acceso a los servicios de bienestar están señalizadas.","Los tableros eléctricos internos tienen señal de riesgo eléctrico.","Los extintores del área están señalizados."]],["Estación de emergencia",["El compartimento del extintor está señalizado.","El extintor tiene la cinta del mes acorde a su inspección.","El compartimento del botiquín está señalizado.","El compartimento del lavaojos está señalizado."]],["Frentes de trabajo",["Las herramientas están inspeccionadas y con la cinta del color del mes.","El área se señaliza antes de comenzar la actividad.","El área cuenta con señal de prohibido el ingreso a personal no autorizado.","Los aparejos de izaje están inspeccionados y con la cinta del color del mes.","La grúa cuenta con señaléticas de punto ciego.","Las señales están ubicadas en lugares que permiten su clara visualización.","Se realiza limpieza y mantenimiento periódico de señaléticas y protecciones colectivas."]],["Taller de soldadura",["El taller de soldadura cuenta con la señalización adecuada.","Las áreas de especial peligro están señalizadas como de acceso restringido.","Está señalizada la obligatoriedad del uso de EPP en todas las zonas necesarias.","Los extintores del taller están señalizados.","Los tableros eléctricos del taller están señalizados."]]]},{"k":"orden-y-limpieza","n":"Orden y limpieza","ft":"Verificación diaria del supervisor; inspección formal semanal","c":[],"b":[["",["Los pasillos y vías de circulación están libres y demarcados.","Los materiales están apilados de forma estable y dentro de zonas demarcadas.","Los residuos están segregados en los contenedores que corresponden.","Los cables y mangueras están ordenados y no cruzan vías de tránsito a nivel del piso.","Las herramientas están guardadas en su lugar asignado al terminar la jornada.","Las zonas de trabajo están demarcadas y señalizadas.","No hay clavos expuestos en la madera de encofrado retirada.","Los desniveles y aberturas están protegidos o señalizados.","El área está libre de acumulación de agua y de superficies resbaladizas.","Los accesos a extintores, botiquín y tableros están despejados."]]]},{"k":"productos-quimicos","n":"Manejo de productos químicos","ft":"Inspección mensual del almacén y del uso en campo","c":[],"b":[["Almacenamiento de materiales peligrosos",["Se cuenta con almacén exclusivo para productos químicos.","El almacén tiene bandeja antiderrame con capacidad para el 110% del volumen almacenado.","El almacén cuenta con señalización, candado y rombo NFPA.","Los productos químicos del almacén están etiquetados y rotulados.","El almacén tiene el listado actualizado de productos químicos y sus hojas MSDS en español con las 16 secciones.","El acceso al almacén está restringido a personal autorizado.","El almacén cuenta con kit antiderrame completo y extintor.","Los productos están almacenados según su compatibilidad.","El almacén está ordenado, sin derrames ni residuos peligrosos acumulados."]],["Manejo en campo",["Los productos químicos en campo tienen bandeja antiderrame, rombo NFPA, etiqueta y hoja MSDS.","Las bandejas antiderrame de campo cubren el 110% del volumen a contener.","Las bandejas antiderrame no presentan roturas ni fugas por desgaste.","Las hojas MSDS están en español, completas y con el rombo NFPA diferenciado por color.","Los envases y embudos son de material apropiado; no se usan recipientes de bebidas ni de alimentos."]],["Almacenamiento de combustible",["El contenedor de combustible y la cisterna cuentan con kit antiderrame y extintor.","El contenedor de combustible tiene techo y bandeja antiderrame.","El contenedor y la cisterna cuentan con señalización y hojas MSDS."]]]},{"k":"servicios-de-bienestar","n":"Servicios de bienestar (SSBB)","ft":"Inspección semanal; limpieza diaria con responsable asignado","c":[],"b":[["Baños y duchas",["La cantidad de servicios de bienestar corresponde al número de trabajadores y a su sexo.","El acceso a baños y duchas está libre de obstrucciones.","Las duchas y los lavamanos están operativos.","No hay fugas de agua en cañerías ni tuberías.","Los baños se mantienen limpios y desinfectados.","Cada baño cuenta con papelera.","Cada baño cuenta con jabonera abastecida.","Los inodoros tienen separaciones y puertas en buen estado.","Existen baños y duchas independientes para hombres y mujeres.","Las aguas servidas se conducen al alcantarillado.","Hay un encargado asignado para la limpieza de baños y duchas."]],["Vestidores",["Se cuenta con casillero para cada trabajador.","Los artículos personales están guardados dentro de los casilleros.","Los vestidores se mantienen limpios.","Los vestidores cuentan con iluminación y red eléctrica en buen estado.","Los vestidores tienen ventilación natural o artificial.","No se usan los vestidores como comedor.","No se usan los vestidores para almacenar materiales.","Los pisos se mantienen libres de acumulación de agua."]],["Comedor",["Hay bancas y mesas suficientes para los trabajadores.","Las mesas y bancas son de material fácilmente lavable.","El comedor tiene piso de cemento u otro material equivalente.","El comedor cuenta con ventilación adecuada.","Se cuenta con dispensador de agua abastecido.","Se cuenta con artefacto de refrigeración para los alimentos.","El comedor cuenta con iluminación y red eléctrica en buen estado.","Hay contenedores suficientes para la disposición de residuos.","El comedor cuenta con extintor operativo.","El comedor se mantiene ordenado y limpio.","Hay un encargado asignado para la limpieza del comedor."]]]}]},"educacion":{"n":"Educación","i":[{"k":"evacuacion-de-la-institucion","n":"Rutas de evacuación y zonas seguras","ft":"Inspección mensual de rutas, zonas seguras y punto de reunión; revisión después de cada simulacro.","c":[],"b":[["Rutas",["Las rutas de evacuación están señalizadas (señales verdes) y se ven desde las aulas.","Pasadizos, escaleras y salidas están libres de carpetas, cajas u otros obstáculos.","Las puertas de salida se abren sin llave durante el horario de clases."]],["Zonas seguras y punto de reunión",["Las zonas seguras del aula y el punto de reunión están señalizados.","El punto de reunión alcanza para todos los estudiantes y el personal del turno."]],["Organización",["Cada docente tiene la lista de su sección para el conteo.","Cada estudiante con discapacidad tiene asignado quién lo acompaña y por dónde baja.","La institución participó en los simulacros nacionales del año y los registró (fecha, hora, tiempo y lo que falló)."]]]},{"k":"proteccion-solar-escolar","n":"Protección solar en la institución","ft":"Inspección mensual, y al armar el horario del año escolar.","c":[],"b":[["Actividades al aire libre",["Las formaciones, actuaciones y actividades deportivas se hacen en ambientes protegidos de la radiación solar.","Si no hay protección, se programan hasta las 10:00 en el turno mañana (hasta las 9:00 en la Sierra) o desde las 16:00."]],["Sombra y avisos",["Hay áreas cubiertas en los espacios donde se realizan actividades al aire libre.","Está el cartel «La exposición prolongada a la radiación solar produce daño a la salud».","Se promueve la arborización para sombra natural."]],["Estudiantes",["Al inicio del año escolar se informó a los estudiantes y se recomendó sombrero de ala ancha, manga larga, bloqueador de factor 30 o más y lentes con filtro UV.","La información considera a los estudiantes con discapacidad."]],["Personal expuesto",["El IPERC incluye la exposición a radiación solar del personal (educación física, auxiliares, vigilancia).","El personal de riesgo alto rota y fue informado de sus riesgos.","Se le entregó su EPP y sus exámenes incluyen evaluación de ojos y piel."]]]},{"k":"extintores","n":"Extintores","ft":"Verificación mensual por extintor; recarga anual y prueba hidrostática según norma","c":["Código","Serie","Ubicación","Tipo","Clase","Peso","Marca","Año de fabricación","Fecha de vencimiento","Última prueba hidrostática","Próxima prueba hidrostática"],"b":[["Estado del extintor",["La presión del manómetro está en la zona verde.","El precinto y el seguro están intactos.","La señalización del extintor es visible desde cualquier punto del área.","El acceso al extintor está libre de obstáculos.","La tarjeta de inspección está firmada y vigente.","La manguera y la boquilla están sin fisuras ni obstrucciones.","El cilindro no presenta abolladuras, corrosión ni pintura desprendida.","El soporte o gabinete está fijo y a la altura reglamentaria.","La cinta del color del mes corresponde al mes en curso.","El extintor está dentro de su fecha de vencimiento."]]]},{"k":"tableros-electricos","n":"Tableros eléctricos","ft":"Inspección mensual por tablero; prueba del diferencial mensual","c":["Código","Ubicación"],"b":[["Caja",["La caja es de material aislante o metálica con puesta a tierra.","Cuenta con parada de emergencia accesible e identificada.","El tablero está identificado con su código y el circuito que alimenta.","Tiene punto de bloqueo para candado (LOTO).","El candado de bloqueo está disponible en el tablero."]],["Protección e interior",["El interruptor diferencial está instalado y la prueba del botón de test quedó registrada.","La tapa interna está colocada y sin partes energizadas expuestas.","Los cables entran por prensaestopas, sin empalmes con cinta ni conductores sueltos.","Los bornes están ajustados y sin señales de recalentamiento.","El tablero cierra completamente y su puerta tiene seguro."]],["Señalización",["Tiene señal de riesgo eléctrico y la indicación del voltaje.","El diagrama unifilar está pegado en el interior y actualizado.","Está libre el espacio de trabajo frente al tablero.","Solo personal autorizado tiene acceso al tablero."]]]},{"k":"botiquin","n":"Botiquín de primeros auxilios","ft":"Verificación mensual del contenido y de las fechas de vencimiento","c":[],"b":[["Botiquín de obra",["02 paquetes de guantes quirúrgicos.","01 frasco de yodopovidona 120 ml solución antiséptica.","01 frasco de agua oxigenada mediano 120 ml.","01 frasco de alcohol mediano 250 ml.","05 paquetes de gasas esterilizadas de 10 cm x 10 cm.","08 paquetes de apósitos.","01 rollo de esparadrapo de 5 cm x 4.50 m.","02 rollos de venda elástica de 3 pulgadas x 5 yardas.","02 rollos de venda elástica de 4 pulgadas x 5 yardas.","01 paquete de algodón x 100 g.","01 venda triangular.","10 paletas bajalenguas para entablillado de dedos.","10 venditas autoadhesivas.","01 frasco de cloruro de sodio al 9/1000 x 1 L para lavado de heridas.","02 paquetes de gasa tipo jelonet para quemaduras.","02 frascos de colirio de 10 ml.","01 tijera punta roma.","01 pinza.","01 frazada.","Resucitador manual o pocket mask.","Ningún insumo está vencido.","El botiquín está señalizado, cerrado y con acceso libre."]],["Botiquín de equipos y vehículos",["01 alcohol de 70° de 120 ml.","01 jabón antiséptico.","05 gasas esterilizadas fraccionadas de 10 cm x 10 cm.","01 apósito esterilizado de 10 cm x 10 cm.","01 esparadrapo de 2.5 cm x 5 cm.","01 venda elástica de 4 pulgadas x 5 yardas.","10 bandas adhesivas (curitas).","01 tijera punta roma de 3 pulgadas.","01 par de guantes quirúrgicos esterilizados 7 1/2.","01 paquete de algodón x 50 g."]]]},{"k":"senalizacion-y-codigo-de-colores","n":"Señalización y código de colores","ft":"Inspección mensual por área de trabajo","c":[],"b":[["Servicios de bienestar",["Las oficinas, servicios higiénicos y comedor están debidamente señalizados.","En servicios higiénicos y comedor se señaliza el correcto lavado y desinfección de manos.","Las vías de acceso a los servicios de bienestar están señalizadas.","Los tableros eléctricos internos tienen señal de riesgo eléctrico.","Los extintores del área están señalizados."]],["Estación de emergencia",["El compartimento del extintor está señalizado.","El extintor tiene la cinta del mes acorde a su inspección.","El compartimento del botiquín está señalizado.","El compartimento del lavaojos está señalizado."]],["Frentes de trabajo",["Las herramientas están inspeccionadas y con la cinta del color del mes.","El área se señaliza antes de comenzar la actividad.","El área cuenta con señal de prohibido el ingreso a personal no autorizado.","Los aparejos de izaje están inspeccionados y con la cinta del color del mes.","La grúa cuenta con señaléticas de punto ciego.","Las señales están ubicadas en lugares que permiten su clara visualización.","Se realiza limpieza y mantenimiento periódico de señaléticas y protecciones colectivas."]],["Taller de soldadura",["El taller de soldadura cuenta con la señalización adecuada.","Las áreas de especial peligro están señalizadas como de acceso restringido.","Está señalizada la obligatoriedad del uso de EPP en todas las zonas necesarias.","Los extintores del taller están señalizados.","Los tableros eléctricos del taller están señalizados."]]]},{"k":"orden-y-limpieza","n":"Orden y limpieza","ft":"Verificación diaria del supervisor; inspección formal semanal","c":[],"b":[["",["Los pasillos y vías de circulación están libres y demarcados.","Los materiales están apilados de forma estable y dentro de zonas demarcadas.","Los residuos están segregados en los contenedores que corresponden.","Los cables y mangueras están ordenados y no cruzan vías de tránsito a nivel del piso.","Las herramientas están guardadas en su lugar asignado al terminar la jornada.","Las zonas de trabajo están demarcadas y señalizadas.","No hay clavos expuestos en la madera de encofrado retirada.","Los desniveles y aberturas están protegidos o señalizados.","El área está libre de acumulación de agua y de superficies resbaladizas.","Los accesos a extintores, botiquín y tableros están despejados."]]]},{"k":"escaleras-portatiles","n":"Escaleras portátiles","ft":"Antes de cada uso, por quien la va a usar; revisión mensual con la cinta del color del mes","c":["Código","Tipo de escalera","Ubicación"],"b":[["Estado de la escalera",["Los largueros están completos, rectos y sin rajaduras, abolladuras ni corrosión.","Los peldaños están completos, firmes y a la misma distancia uno de otro.","No tiene peldaños, largueros ni uniones reparados con alambre, clavos o soldadura improvisada.","Tiene zapatas antideslizantes en buen estado en los dos largueros.","Está limpia: sin grasa, aceite ni barro en los peldaños.","Si es de tijera: los tirantes o seguros de apertura están completos y traban bien.","Si es extensible: los seguros y la cuerda traban bien, y los tramos se traslapan lo necesario.","No es metálica si el trabajo es cerca de instalaciones eléctricas.","Tiene su código y la cinta del color del mes."]],["Dónde y cómo se coloca",["Se apoya sobre piso firme y nivelado; nunca sobre cajas, ladrillos o cilindros.","La inclinación es de un metro de separación en la base por cada cuatro de altura.","Sobresale por lo menos un metro por encima del punto de llegada.","Está amarrada arriba o la sujeta otra persona mientras se usa.","El pie de la escalera está libre y señalizado: no queda frente a una puerta ni en una vía de paso sin resguardo."]],["Uso",["Sube y baja una persona a la vez, de frente a la escalera y con las manos libres.","Las herramientas y los materiales se suben con soga o en cinturón portaherramientas, no en las manos.","No se usa como plataforma, pasarela ni andamio.","Sobre 1.80 m de altura se usa arnés, anclado a un punto independiente de la escalera."]]]},{"k":"servicios-de-bienestar","n":"Servicios de bienestar (SSBB)","ft":"Inspección semanal; limpieza diaria con responsable asignado","c":[],"b":[["Baños y duchas",["La cantidad de servicios de bienestar corresponde al número de trabajadores y a su sexo.","El acceso a baños y duchas está libre de obstrucciones.","Las duchas y los lavamanos están operativos.","No hay fugas de agua en cañerías ni tuberías.","Los baños se mantienen limpios y desinfectados.","Cada baño cuenta con papelera.","Cada baño cuenta con jabonera abastecida.","Los inodoros tienen separaciones y puertas en buen estado.","Existen baños y duchas independientes para hombres y mujeres.","Las aguas servidas se conducen al alcantarillado.","Hay un encargado asignado para la limpieza de baños y duchas."]],["Vestidores",["Se cuenta con casillero para cada trabajador.","Los artículos personales están guardados dentro de los casilleros.","Los vestidores se mantienen limpios.","Los vestidores cuentan con iluminación y red eléctrica en buen estado.","Los vestidores tienen ventilación natural o artificial.","No se usan los vestidores como comedor.","No se usan los vestidores para almacenar materiales.","Los pisos se mantienen libres de acumulación de agua."]],["Comedor",["Hay bancas y mesas suficientes para los trabajadores.","Las mesas y bancas son de material fácilmente lavable.","El comedor tiene piso de cemento u otro material equivalente.","El comedor cuenta con ventilación adecuada.","Se cuenta con dispensador de agua abastecido.","Se cuenta con artefacto de refrigeración para los alimentos.","El comedor cuenta con iluminación y red eléctrica en buen estado.","Hay contenedores suficientes para la disposición de residuos.","El comedor cuenta con extintor operativo.","El comedor se mantiene ordenado y limpio.","Hay un encargado asignado para la limpieza del comedor."]]]}]},"oficinas":{"n":"Oficinas, comercio y servicios","i":[{"k":"puesto-con-pantalla","n":"Puesto con pantalla","ft":"Evaluación anual de cada puesto, y cuando cambia el puesto o la persona; verificación en la inspección planeada.","c":[],"b":[["La silla",["Es de altura regulable: los pies apoyan planos y los muslos quedan horizontales (90 a 110 grados).","Tiene cinco ruedas y el respaldo se regula en altura e inclinación."]],["La pantalla y el teclado",["El borde superior de la pantalla está a la altura de los ojos.","La pantalla no está más lejos que el alcance del brazo extendido con la espalda apoyada.","El teclado es independiente y está en el mismo plano que el ratón.","Hay atril o soporte cuando se digita desde documentos."]],["Tiempo y pausas",["La entrada efectiva de datos no pasa de 5 horas al día.","Se hace una pausa de 10 minutos cada 50 minutos y se promueven los estiramientos."]],["Ambiente",["Hay al menos 300 lux en oficinas y 500 lux en captura y procesamiento de información y salas de cómputo.","El ruido está por debajo de 65 dB en los puestos de atención constante y alta exigencia intelectual."]]]},{"k":"teletrabajo","n":"Puesto de teletrabajo","ft":"Al empezar el teletrabajo, cada vez que cambia el lugar y una vez al año.","c":[],"b":[["La evaluación",["El empleador identificó los peligros y evaluó los riesgos del espacio habilitado para teletrabajar.","La visita (física o digital) se avisó con al menos 48 horas.","Si el lugar cambió, se volvió a evaluar el puesto.","Si hubo autoevaluación, fue de común acuerdo y el trabajador recibió capacitación para llenar el formulario."]],["El puesto",["Se revisaron los peligros locativos y eléctricos del espacio (cables, extensiones, tomacorrientes).","El puesto con pantalla cumple la R.M. 375-2008-TR (silla regulable, altura de la pantalla, teclado aparte).","Se revisaron los factores psicosociales (carga de trabajo y horario)."]],["Pausas y equipos",["El empleador comunicó los periodos de pausas activas.","El acuerdo detalla las medidas de seguridad y el mantenimiento de los equipos entregados."]]]},{"k":"extintores","n":"Extintores","ft":"Verificación mensual por extintor; recarga anual y prueba hidrostática según norma","c":["Código","Serie","Ubicación","Tipo","Clase","Peso","Marca","Año de fabricación","Fecha de vencimiento","Última prueba hidrostática","Próxima prueba hidrostática"],"b":[["Estado del extintor",["La presión del manómetro está en la zona verde.","El precinto y el seguro están intactos.","La señalización del extintor es visible desde cualquier punto del área.","El acceso al extintor está libre de obstáculos.","La tarjeta de inspección está firmada y vigente.","La manguera y la boquilla están sin fisuras ni obstrucciones.","El cilindro no presenta abolladuras, corrosión ni pintura desprendida.","El soporte o gabinete está fijo y a la altura reglamentaria.","La cinta del color del mes corresponde al mes en curso.","El extintor está dentro de su fecha de vencimiento."]]]},{"k":"tableros-electricos","n":"Tableros eléctricos","ft":"Inspección mensual por tablero; prueba del diferencial mensual","c":["Código","Ubicación"],"b":[["Caja",["La caja es de material aislante o metálica con puesta a tierra.","Cuenta con parada de emergencia accesible e identificada.","El tablero está identificado con su código y el circuito que alimenta.","Tiene punto de bloqueo para candado (LOTO).","El candado de bloqueo está disponible en el tablero."]],["Protección e interior",["El interruptor diferencial está instalado y la prueba del botón de test quedó registrada.","La tapa interna está colocada y sin partes energizadas expuestas.","Los cables entran por prensaestopas, sin empalmes con cinta ni conductores sueltos.","Los bornes están ajustados y sin señales de recalentamiento.","El tablero cierra completamente y su puerta tiene seguro."]],["Señalización",["Tiene señal de riesgo eléctrico y la indicación del voltaje.","El diagrama unifilar está pegado en el interior y actualizado.","Está libre el espacio de trabajo frente al tablero.","Solo personal autorizado tiene acceso al tablero."]]]},{"k":"botiquin","n":"Botiquín de primeros auxilios","ft":"Verificación mensual del contenido y de las fechas de vencimiento","c":[],"b":[["Botiquín de obra",["02 paquetes de guantes quirúrgicos.","01 frasco de yodopovidona 120 ml solución antiséptica.","01 frasco de agua oxigenada mediano 120 ml.","01 frasco de alcohol mediano 250 ml.","05 paquetes de gasas esterilizadas de 10 cm x 10 cm.","08 paquetes de apósitos.","01 rollo de esparadrapo de 5 cm x 4.50 m.","02 rollos de venda elástica de 3 pulgadas x 5 yardas.","02 rollos de venda elástica de 4 pulgadas x 5 yardas.","01 paquete de algodón x 100 g.","01 venda triangular.","10 paletas bajalenguas para entablillado de dedos.","10 venditas autoadhesivas.","01 frasco de cloruro de sodio al 9/1000 x 1 L para lavado de heridas.","02 paquetes de gasa tipo jelonet para quemaduras.","02 frascos de colirio de 10 ml.","01 tijera punta roma.","01 pinza.","01 frazada.","Resucitador manual o pocket mask.","Ningún insumo está vencido.","El botiquín está señalizado, cerrado y con acceso libre."]],["Botiquín de equipos y vehículos",["01 alcohol de 70° de 120 ml.","01 jabón antiséptico.","05 gasas esterilizadas fraccionadas de 10 cm x 10 cm.","01 apósito esterilizado de 10 cm x 10 cm.","01 esparadrapo de 2.5 cm x 5 cm.","01 venda elástica de 4 pulgadas x 5 yardas.","10 bandas adhesivas (curitas).","01 tijera punta roma de 3 pulgadas.","01 par de guantes quirúrgicos esterilizados 7 1/2.","01 paquete de algodón x 50 g."]]]},{"k":"senalizacion-y-codigo-de-colores","n":"Señalización y código de colores","ft":"Inspección mensual por área de trabajo","c":[],"b":[["Servicios de bienestar",["Las oficinas, servicios higiénicos y comedor están debidamente señalizados.","En servicios higiénicos y comedor se señaliza el correcto lavado y desinfección de manos.","Las vías de acceso a los servicios de bienestar están señalizadas.","Los tableros eléctricos internos tienen señal de riesgo eléctrico.","Los extintores del área están señalizados."]],["Estación de emergencia",["El compartimento del extintor está señalizado.","El extintor tiene la cinta del mes acorde a su inspección.","El compartimento del botiquín está señalizado.","El compartimento del lavaojos está señalizado."]],["Frentes de trabajo",["Las herramientas están inspeccionadas y con la cinta del color del mes.","El área se señaliza antes de comenzar la actividad.","El área cuenta con señal de prohibido el ingreso a personal no autorizado.","Los aparejos de izaje están inspeccionados y con la cinta del color del mes.","La grúa cuenta con señaléticas de punto ciego.","Las señales están ubicadas en lugares que permiten su clara visualización.","Se realiza limpieza y mantenimiento periódico de señaléticas y protecciones colectivas."]],["Taller de soldadura",["El taller de soldadura cuenta con la señalización adecuada.","Las áreas de especial peligro están señalizadas como de acceso restringido.","Está señalizada la obligatoriedad del uso de EPP en todas las zonas necesarias.","Los extintores del taller están señalizados.","Los tableros eléctricos del taller están señalizados."]]]},{"k":"orden-y-limpieza","n":"Orden y limpieza","ft":"Verificación diaria del supervisor; inspección formal semanal","c":[],"b":[["",["Los pasillos y vías de circulación están libres y demarcados.","Los materiales están apilados de forma estable y dentro de zonas demarcadas.","Los residuos están segregados en los contenedores que corresponden.","Los cables y mangueras están ordenados y no cruzan vías de tránsito a nivel del piso.","Las herramientas están guardadas en su lugar asignado al terminar la jornada.","Las zonas de trabajo están demarcadas y señalizadas.","No hay clavos expuestos en la madera de encofrado retirada.","Los desniveles y aberturas están protegidos o señalizados.","El área está libre de acumulación de agua y de superficies resbaladizas.","Los accesos a extintores, botiquín y tableros están despejados."]]]},{"k":"servicios-de-bienestar","n":"Servicios de bienestar (SSBB)","ft":"Inspección semanal; limpieza diaria con responsable asignado","c":[],"b":[["Baños y duchas",["La cantidad de servicios de bienestar corresponde al número de trabajadores y a su sexo.","El acceso a baños y duchas está libre de obstrucciones.","Las duchas y los lavamanos están operativos.","No hay fugas de agua en cañerías ni tuberías.","Los baños se mantienen limpios y desinfectados.","Cada baño cuenta con papelera.","Cada baño cuenta con jabonera abastecida.","Los inodoros tienen separaciones y puertas en buen estado.","Existen baños y duchas independientes para hombres y mujeres.","Las aguas servidas se conducen al alcantarillado.","Hay un encargado asignado para la limpieza de baños y duchas."]],["Vestidores",["Se cuenta con casillero para cada trabajador.","Los artículos personales están guardados dentro de los casilleros.","Los vestidores se mantienen limpios.","Los vestidores cuentan con iluminación y red eléctrica en buen estado.","Los vestidores tienen ventilación natural o artificial.","No se usan los vestidores como comedor.","No se usan los vestidores para almacenar materiales.","Los pisos se mantienen libres de acumulación de agua."]],["Comedor",["Hay bancas y mesas suficientes para los trabajadores.","Las mesas y bancas son de material fácilmente lavable.","El comedor tiene piso de cemento u otro material equivalente.","El comedor cuenta con ventilación adecuada.","Se cuenta con dispensador de agua abastecido.","Se cuenta con artefacto de refrigeración para los alimentos.","El comedor cuenta con iluminación y red eléctrica en buen estado.","Hay contenedores suficientes para la disposición de residuos.","El comedor cuenta con extintor operativo.","El comedor se mantiene ordenado y limpio.","Hay un encargado asignado para la limpieza del comedor."]]]}]},"agro":{"n":"Agroindustria","i":[{"k":"plaguicidas","n":"Almacén de plaguicidas y envases vacíos","ft":"Inspección mensual del almacén y del punto de triple lavado; revisión antes de cada campaña.","c":[],"b":[["El almacén",["Los plaguicidas no se guardan donde hay alimentos, piensos, bebidas o medicamentos.","Cada producto conserva su etiqueta legible.","Cada producto tiene su Ficha de Datos de Seguridad y el almacén es de acceso restringido.","Los vencidos o con envase dañado están separados para su retiro."]],["Envases vacíos",["Los envases usados tienen triple lavado y están inutilizados (perforados).","Se entregan a un centro de acopio autorizado, sin acumularlos.","Los que no se pueden lavar se guardan en un lugar seguro, lejos del agua, de las personas y de los animales, sin tocar el suelo.","No hay quema ni entierro de envases y nadie se los lleva a su casa."]],["Transporte y aplicación",["Los plaguicidas no viajan con alimentos, bebidas o medicinas, ni en vehículos de pasajeros.","El aplicador usa el EPP que indica la etiqueta.","Los nuevos y los que no saben leer fueron capacitados en el manejo de los agroquímicos.","El que aplica se lava antes de comer y no se lleva a su casa nada contaminado.","Nadie entra al lote tratado antes del tiempo de reingreso de la etiqueta y el lote está señalizado."]]]},{"k":"sol-en-el-campo","n":"Exposición solar en el campo","ft":"Inspección mensual en campo, y al programar cada campaña.","c":[],"b":[["Evaluación",["El IPERC incluye la exposición a la radiación solar en cada labor al aire libre.","Están identificados los trabajadores de riesgo alto (exposición directa de 10:00 a 16:00 con índice UV de 6 o más, o 30 % o más de la jornada)."]],["Controles",["Las labores al sol se programan, en lo posible, fuera de las 10:00 a 16:00 (9:00 a 16:00 en la Sierra).","Los trabajadores de riesgo alto rotan periódicamente.","Los trabajadores fueron informados de los riesgos y de los controles."]],["EPP y salud",["Se entregó el EPP según la jerarquía de controles y la entrega está registrada.","Se entregaron sombrero de ala ancha o cubrenuca, lentes con filtro UV y bloqueador, y se enseñó a usarlos.","El bloqueador es FPS 50 o más, con protección UVA y UVB, y alcanza para toda la cuadrilla.","Si hay estrés térmico, el trabajador tiene su tiempo de recuperación.","Los exámenes médicos incluyen evaluación oftalmológica y de la piel (tamizaje dermatológico)."]]]},{"k":"condiciones-del-regimen-agrario","n":"Condiciones mínimas del régimen agrario","ft":"Inspección mensual en el fundo y donde trabaja cada cuadrilla.","c":[],"b":[["Traslado",["Si no hay transporte público, el personal viaja en transporte terrestre especial de personas.","Nadie viaja en camiones ni en vehículos de carga, y se respetan los asientos fijos."]],["Agua, sombra y comedor",["Hay agua potable durante toda la jornada, en bebederos cerca de cada cuadrilla.","Hay zonas de descanso a la sombra durante la jornada.","El comedor protege de la intemperie, está limpio, iluminado y ventilado, con mesas, sillas y agua para lavarse las manos y el rostro, lejos de los agroquímicos.","Nadie come en el lugar de trabajo ni durante la labor."]],["Servicios higiénicos, duchas y vestuarios",["Hay servicios higiénicos separados para hombres y mujeres, en la cantidad que pide la norma.","Están limpios, con agua potable, jabón y papel.","Si se usan productos químicos tóxicos, hay duchas, y vestuarios ventilados con casilleros."]]]},{"k":"epp-del-personal","n":"Equipos de protección personal","ft":"Verificación diaria del supervisor; inspección formal mensual por trabajador","c":["Nombres y apellidos","DNI","Cargo"],"b":[["EPP por trabajador",["Casco de seguridad","Lentes de seguridad","Barbiquejo","Zapatos de seguridad","Polo con cinta reflectiva","Pantalón drill","Chaleco","Guantes de cuero","Guantes de badana","Guantes de nitrilo","Protector auditivo","Respirador y filtros","Careta facial","Arnés de cuerpo entero","Línea de vida con absorbedor","Uniforme completo y limpio"]]]},{"k":"extintores","n":"Extintores","ft":"Verificación mensual por extintor; recarga anual y prueba hidrostática según norma","c":["Código","Serie","Ubicación","Tipo","Clase","Peso","Marca","Año de fabricación","Fecha de vencimiento","Última prueba hidrostática","Próxima prueba hidrostática"],"b":[["Estado del extintor",["La presión del manómetro está en la zona verde.","El precinto y el seguro están intactos.","La señalización del extintor es visible desde cualquier punto del área.","El acceso al extintor está libre de obstáculos.","La tarjeta de inspección está firmada y vigente.","La manguera y la boquilla están sin fisuras ni obstrucciones.","El cilindro no presenta abolladuras, corrosión ni pintura desprendida.","El soporte o gabinete está fijo y a la altura reglamentaria.","La cinta del color del mes corresponde al mes en curso.","El extintor está dentro de su fecha de vencimiento."]]]},{"k":"tableros-electricos","n":"Tableros eléctricos","ft":"Inspección mensual por tablero; prueba del diferencial mensual","c":["Código","Ubicación"],"b":[["Caja",["La caja es de material aislante o metálica con puesta a tierra.","Cuenta con parada de emergencia accesible e identificada.","El tablero está identificado con su código y el circuito que alimenta.","Tiene punto de bloqueo para candado (LOTO).","El candado de bloqueo está disponible en el tablero."]],["Protección e interior",["El interruptor diferencial está instalado y la prueba del botón de test quedó registrada.","La tapa interna está colocada y sin partes energizadas expuestas.","Los cables entran por prensaestopas, sin empalmes con cinta ni conductores sueltos.","Los bornes están ajustados y sin señales de recalentamiento.","El tablero cierra completamente y su puerta tiene seguro."]],["Señalización",["Tiene señal de riesgo eléctrico y la indicación del voltaje.","El diagrama unifilar está pegado en el interior y actualizado.","Está libre el espacio de trabajo frente al tablero.","Solo personal autorizado tiene acceso al tablero."]]]},{"k":"botiquin","n":"Botiquín de primeros auxilios","ft":"Verificación mensual del contenido y de las fechas de vencimiento","c":[],"b":[["Botiquín de obra",["02 paquetes de guantes quirúrgicos.","01 frasco de yodopovidona 120 ml solución antiséptica.","01 frasco de agua oxigenada mediano 120 ml.","01 frasco de alcohol mediano 250 ml.","05 paquetes de gasas esterilizadas de 10 cm x 10 cm.","08 paquetes de apósitos.","01 rollo de esparadrapo de 5 cm x 4.50 m.","02 rollos de venda elástica de 3 pulgadas x 5 yardas.","02 rollos de venda elástica de 4 pulgadas x 5 yardas.","01 paquete de algodón x 100 g.","01 venda triangular.","10 paletas bajalenguas para entablillado de dedos.","10 venditas autoadhesivas.","01 frasco de cloruro de sodio al 9/1000 x 1 L para lavado de heridas.","02 paquetes de gasa tipo jelonet para quemaduras.","02 frascos de colirio de 10 ml.","01 tijera punta roma.","01 pinza.","01 frazada.","Resucitador manual o pocket mask.","Ningún insumo está vencido.","El botiquín está señalizado, cerrado y con acceso libre."]],["Botiquín de equipos y vehículos",["01 alcohol de 70° de 120 ml.","01 jabón antiséptico.","05 gasas esterilizadas fraccionadas de 10 cm x 10 cm.","01 apósito esterilizado de 10 cm x 10 cm.","01 esparadrapo de 2.5 cm x 5 cm.","01 venda elástica de 4 pulgadas x 5 yardas.","10 bandas adhesivas (curitas).","01 tijera punta roma de 3 pulgadas.","01 par de guantes quirúrgicos esterilizados 7 1/2.","01 paquete de algodón x 50 g."]]]},{"k":"productos-quimicos","n":"Manejo de productos químicos","ft":"Inspección mensual del almacén y del uso en campo","c":[],"b":[["Almacenamiento de materiales peligrosos",["Se cuenta con almacén exclusivo para productos químicos.","El almacén tiene bandeja antiderrame con capacidad para el 110% del volumen almacenado.","El almacén cuenta con señalización, candado y rombo NFPA.","Los productos químicos del almacén están etiquetados y rotulados.","El almacén tiene el listado actualizado de productos químicos y sus hojas MSDS en español con las 16 secciones.","El acceso al almacén está restringido a personal autorizado.","El almacén cuenta con kit antiderrame completo y extintor.","Los productos están almacenados según su compatibilidad.","El almacén está ordenado, sin derrames ni residuos peligrosos acumulados."]],["Manejo en campo",["Los productos químicos en campo tienen bandeja antiderrame, rombo NFPA, etiqueta y hoja MSDS.","Las bandejas antiderrame de campo cubren el 110% del volumen a contener.","Las bandejas antiderrame no presentan roturas ni fugas por desgaste.","Las hojas MSDS están en español, completas y con el rombo NFPA diferenciado por color.","Los envases y embudos son de material apropiado; no se usan recipientes de bebidas ni de alimentos."]],["Almacenamiento de combustible",["El contenedor de combustible y la cisterna cuentan con kit antiderrame y extintor.","El contenedor de combustible tiene techo y bandeja antiderrame.","El contenedor y la cisterna cuentan con señalización y hojas MSDS."]]]},{"k":"herramientas-manuales","n":"Herramientas manuales y eléctricas","ft":"Inspección mensual por herramienta, con la cinta del color del mes","c":["Código","Tipo de herramienta","Responsable"],"b":[["Estado general",["La herramienta tiene la cinta del color del mes, vigente y visible.","La herramienta corresponde al trabajo que se va a hacer; no está improvisada ni modificada.","El mango está firme, sin rajaduras, astillas ni cinta que tape un defecto.","La cabeza o la parte útil no está deformada, rebabeada ni con filo mellado.","No hay uniones soldadas ni reparaciones caseras en partes que soportan esfuerzo.","La herramienta está limpia, sin grasa ni aceite en la zona de agarre."]],["Herramientas eléctricas",["El cable no tiene empalmes con cinta, cortes ni conductores a la vista.","El enchufe está completo, con espiga a tierra y sin quemaduras.","El interruptor prende y apaga con firmeza y no queda trabado.","La guarda de seguridad está instalada y no fue retirada ni bloqueada.","La carcasa no está rajada ni le faltan tornillos.","El disco o accesorio tiene RPM iguales o mayores que las del equipo.","El equipo se conecta a un tablero con interruptor diferencial.","El equipo tiene su ficha técnica o manual disponible y el operador está autorizado."]],["Uso y guardado",["La herramienta se transporta en portaherramientas o caja, no en el bolsillo ni en la mano al subir.","En altura la herramienta va asegurada con driza.","Al terminar la jornada se guarda en su lugar asignado.","Las herramientas observadas se retiran de servicio con tarjeta roja y no se dejan en el frente."]]]},{"k":"senalizacion-y-codigo-de-colores","n":"Señalización y código de colores","ft":"Inspección mensual por área de trabajo","c":[],"b":[["Servicios de bienestar",["Las oficinas, servicios higiénicos y comedor están debidamente señalizados.","En servicios higiénicos y comedor se señaliza el correcto lavado y desinfección de manos.","Las vías de acceso a los servicios de bienestar están señalizadas.","Los tableros eléctricos internos tienen señal de riesgo eléctrico.","Los extintores del área están señalizados."]],["Estación de emergencia",["El compartimento del extintor está señalizado.","El extintor tiene la cinta del mes acorde a su inspección.","El compartimento del botiquín está señalizado.","El compartimento del lavaojos está señalizado."]],["Frentes de trabajo",["Las herramientas están inspeccionadas y con la cinta del color del mes.","El área se señaliza antes de comenzar la actividad.","El área cuenta con señal de prohibido el ingreso a personal no autorizado.","Los aparejos de izaje están inspeccionados y con la cinta del color del mes.","La grúa cuenta con señaléticas de punto ciego.","Las señales están ubicadas en lugares que permiten su clara visualización.","Se realiza limpieza y mantenimiento periódico de señaléticas y protecciones colectivas."]],["Taller de soldadura",["El taller de soldadura cuenta con la señalización adecuada.","Las áreas de especial peligro están señalizadas como de acceso restringido.","Está señalizada la obligatoriedad del uso de EPP en todas las zonas necesarias.","Los extintores del taller están señalizados.","Los tableros eléctricos del taller están señalizados."]]]},{"k":"servicios-de-bienestar","n":"Servicios de bienestar (SSBB)","ft":"Inspección semanal; limpieza diaria con responsable asignado","c":[],"b":[["Baños y duchas",["La cantidad de servicios de bienestar corresponde al número de trabajadores y a su sexo.","El acceso a baños y duchas está libre de obstrucciones.","Las duchas y los lavamanos están operativos.","No hay fugas de agua en cañerías ni tuberías.","Los baños se mantienen limpios y desinfectados.","Cada baño cuenta con papelera.","Cada baño cuenta con jabonera abastecida.","Los inodoros tienen separaciones y puertas en buen estado.","Existen baños y duchas independientes para hombres y mujeres.","Las aguas servidas se conducen al alcantarillado.","Hay un encargado asignado para la limpieza de baños y duchas."]],["Vestidores",["Se cuenta con casillero para cada trabajador.","Los artículos personales están guardados dentro de los casilleros.","Los vestidores se mantienen limpios.","Los vestidores cuentan con iluminación y red eléctrica en buen estado.","Los vestidores tienen ventilación natural o artificial.","No se usan los vestidores como comedor.","No se usan los vestidores para almacenar materiales.","Los pisos se mantienen libres de acumulación de agua."]],["Comedor",["Hay bancas y mesas suficientes para los trabajadores.","Las mesas y bancas son de material fácilmente lavable.","El comedor tiene piso de cemento u otro material equivalente.","El comedor cuenta con ventilación adecuada.","Se cuenta con dispensador de agua abastecido.","Se cuenta con artefacto de refrigeración para los alimentos.","El comedor cuenta con iluminación y red eléctrica en buen estado.","Hay contenedores suficientes para la disposición de residuos.","El comedor cuenta con extintor operativo.","El comedor se mantiene ordenado y limpio.","Hay un encargado asignado para la limpieza del comedor."]]]}]},"pesca":{"n":"Pesca","i":[{"k":"chata-y-descarga","n":"Chata y descarga de pesca","ft":"En cada descarga, antes de empezar.","c":[],"b":[["El personal de la chata",["Cada uno con su casco con barbiquejo puesto (D.S. 010-73-PE, art. 90).","Guantes de cuero y lona (D.S. 010-73-PE, art. 90)."]],["La chata y el muelle",["Barandas completas y firmes.","Pisos antideslizantes, sin pescado, agua ni aceite acumulados.","Bitas en buen estado para amarrar.","Salvavidas en su sitio y a la vista."]]]},{"k":"bodega-con-pescado","n":"Entrada a la bodega con pescado","ft":"Antes de cada entrada a una bodega con pescado.","c":[],"b":[["Antes de entrar",["Quien entra lleva máscara con manguera de aire (art. 89).","Quien entra lleva arnés con cabos para izarlo (art. 89).","Hay alguien afuera, atento, para izarlo con los cabos."]]]},{"k":"guardas-de-maquinas","n":"Guardas y resguardos de máquinas","ft":"Inspección planeada mensual, con verificación pre-uso diaria por el operador y revisión mensual del Comité de Seguridad y Salud en el Trabajo.","c":[],"b":[["",["Todas las partes móviles de máquinas, motores y transmisiones cuentan con resguardo instalado.","Los engranajes y ruedas dentadas están enteramente resguardados.","Las manivelas y vástagos cuentan con resguardo de construcción normalizada.","El resguardo brinda protección positiva e impide todo acceso a la zona de peligro durante la operación.","El resguardo no puede retirarse sin herramienta y no es fácilmente anulable de forma intencional o accidental.","Los resguardos están anclados, sin deformaciones, sin cortes y sin bordes filosos.","No hay máquinas operando con guardas retiradas, puenteadas o incompletas.","El retiro de resguardos se realiza únicamente con la máquina detenida y bloqueada, y con autorización.","Los enclavamientos de puertas y tapas de acceso detienen la máquina al abrirse.","Los pulsadores de parada de emergencia están accesibles, identificados y fueron probados.","La máquina cuenta con dispositivo de corte de energía identificado y accesible.","El área alrededor de la máquina está delimitada y libre de obstáculos.","El nivel de iluminación en el puesto de la máquina es adecuado para la tarea.","La ficha técnica y el procedimiento de operación de la máquina están disponibles en el puesto.","El operador está capacitado y autorizado para operar esa máquina específica.","Las máquinas nuevas fueron adquiridas especificando que incluyan los dispositivos de seguridad requeridos."]]]},{"k":"calderas-y-recipientes-a-presion","n":"Calderas y recipientes a presión","ft":"Inspección y prueba hidrostática según la norma técnica aplicable, habitualmente anual, con libro de servicio autorizado ante el MTPE. Verificación por turno de bitácora, purgas y nivel de agua, y prueba mensual de los dispositivos de seguridad.","c":["Código","Marca","Presión máxima"],"b":[["Documentación",["El equipo cuenta con libro de servicio autorizado y actualizado, disponible para el inspector.","La placa del fabricante con presión máxima de trabajo, año y número de serie está instalada y legible.","El certificado de la última inspección y prueba hidrostática está vigente.","Los ensayos no destructivos y la medición de espesores están dentro del plan de integridad.","El operador cuenta con capacitación o certificación vigente como operador de calderas."]],["Dispositivos de seguridad",["Las válvulas de seguridad están instaladas, calibradas y con certificado vigente.","La válvula de seguridad fue probada manualmente y descarga libremente hacia zona segura.","El manómetro está calibrado, es legible y tiene marcada en rojo la presión máxima de trabajo.","El control de nivel de agua, columna de agua o visor, es legible y está operativo.","El corte por bajo nivel de agua fue probado y detiene el quemador.","El presostato de trabajo y el presostato de seguridad están operativos.","El sistema de purga de fondo y de superficie opera y la purga está registrada por turno."]],["Condiciones de operación y entorno",["No hay fugas de vapor, agua ni combustible en el cuerpo, bridas ni accesorios.","El aislamiento térmico está íntegro y las superficies calientes están protegidas o señalizadas.","La sala de calderas tiene ventilación adecuada, dos salidas y puertas de apertura hacia afuera.","El área está libre de materiales combustibles y con extintor apropiado a la vista.","El tratamiento de agua está controlado y los análisis del período están registrados.","La bitácora de operación del turno está llenada y firmada."]]]},{"k":"montacargas","n":"Montacargas y autoelevadores","ft":"Check list de pre-uso por turno antes de operar. Mantenimiento preventivo según el fabricante y certificación de operatividad periódica; el empleador conserva constancia visible de las inspecciones periódicas.","c":["Código de equipo","Marca y modelo","Operador"],"b":[["Antes de encender",["El operador cuenta con licencia interna o certificación vigente para el tipo de montacargas.","El check list de pre-uso del turno está llenado y firmado.","No hay fugas de aceite hidráulico, combustible ni refrigerante bajo el equipo.","Los neumáticos no presentan cortes, desgaste excesivo ni objetos incrustados.","Las horquillas no presentan fisuras, deformación ni desgaste mayor al 10% del espesor original.","El pasador o seguro de las horquillas está instalado.","Las cadenas de elevación están lubricadas, sin eslabones dañados y con tensión pareja.","El respaldo de carga y el techo protector están instalados y sin deformaciones.","La placa de capacidad de carga está instalada y legible."]],["Con el equipo encendido",["Los frenos de servicio y de estacionamiento operan correctamente.","La dirección responde sin juego excesivo.","La bocina, la alarma de retroceso y la baliza funcionan.","Las luces delanteras y posteriores funcionan.","El mástil sube, baja e inclina sin trabas ni descuelgue de la carga.","El cinturón de seguridad está operativo y el operador lo utiliza.","Los mandos hidráulicos retornan a neutro al soltarlos.","El extintor del equipo está operativo y con tarjeta vigente."]],["Operación",["El montacargas circula con la carga a baja altura y con el mástil inclinado hacia atrás.","No se transportan personas sobre las horquillas ni en el contrapeso.","Se respetan las vías señalizadas, la velocidad máxima y los cruces con peatones.","La estación de carga de baterías está en área ventilada, con lavaojos y sin fuentes de ignición."]]]},{"k":"almacenes-y-racks","n":"Almacenes, racks y estanterías","ft":"Verificación visual semanal por el responsable de almacén e inspección técnica anual de la estructura de racks por personal competente.","c":[],"b":[["",["Los racks cuentan con placa de capacidad de carga por nivel, visible y legible.","No se excede la carga máxima por nivel ni por módulo.","Los parantes están anclados al piso, sin deformaciones, golpes ni corrosión.","Los protectores de columna y guardarraíles están instalados en los puntos de tránsito de montacargas.","Las vigas o largueros tienen sus pasadores de seguridad instalados.","No hay elementos del rack faltantes, improvisados ni reparados con soldadura no autorizada.","Las cargas están estables, centradas sobre la parihuela y sin volados peligrosos.","Las parihuelas están en buen estado, sin tablas rotas ni clavos salidos.","El apilamiento directo respeta la altura máxima y la relación base-altura definida.","Los pasillos tienen el ancho señalizado y están libres de obstáculos.","La demarcación de pasillos peatonales y de tránsito de montacargas está pintada y visible.","El nivel de iluminación del almacén cumple lo requerido para la tarea.","Los extintores están señalizados, accesibles y con tarjeta vigente.","Las salidas de emergencia están señalizadas, despejadas y con apertura hacia afuera.","Los rociadores y detectores no están obstruidos por la mercadería y se respeta la distancia libre al techo.","Los productos químicos están segregados por compatibilidad y con contención secundaria.","El registro de inspección de racks está firmado y al día."]]]},{"k":"sistemas-electricos","n":"Sistemas e instalaciones eléctricas","ft":"Inspección planeada mensual y prueba mensual de interruptores diferenciales. Termografía de tableros y medición de resistencia de pozos a tierra con periodicidad anual.","c":["Código de tablero","Ubicación"],"b":[["",["Los tableros están rotulados, cerrados y con los circuitos identificados.","Los tableros cuentan con protección diferencial y la prueba del botón de test está registrada.","Existe espacio libre de trabajo frente al tablero de al menos 1 m, sin materiales almacenados.","No hay cables expuestos, empalmes con cinta ni conductores fuera de canalización.","Los tomacorrientes tienen línea a tierra y no presentan sobrecarga por adaptadores múltiples.","Las extensiones eléctricas están en buen estado y no reemplazan instalaciones permanentes.","Las luminarias están completas, con difusor y sin cables colgando.","La señalización de riesgo eléctrico está instalada en tableros, celdas y subestaciones.","El sistema de puesta a tierra tiene medición de resistencia vigente.","Las máquinas y estructuras metálicas están conectadas al sistema de puesta a tierra.","Los trabajos sin tensión aplican las cinco reglas de oro: corte efectivo de fuentes, enclavamiento y bloqueo, verificación de ausencia de tensión, puesta a tierra y en cortocircuito, y señalización.","El EPP dieléctrico cuenta con hoja de vida actualizada y con ensayo dieléctrico vigente.","Se respetan las distancias mínimas de seguridad del Código Nacional de Electricidad.","Los grupos electrógenos y UPS cuentan con mantenimiento y prueba de arranque registrados.","Las instalaciones son inspeccionadas conforme a lo establecido en el Reglamento Interno de Seguridad y Salud en el Trabajo."]]]},{"k":"extintores-y-sistemas-contra-incendio","n":"Extintores y sistemas contra incendio","ft":"Verificación mensual de extintores y equipos, prueba semanal de bombas contra incendio y simulacros conforme al Programa Anual de Seguridad y Salud en el Trabajo.","c":["Código","Ubicación","Tipo","Clase"],"b":[["",["La cantidad, tipo y ubicación de extintores corresponde a la carga combustible y al riesgo del área.","El extintor está en su soporte señalizado, a la altura reglamentaria y con acceso libre.","El manómetro marca dentro del rango operativo y el precinto está intacto.","La tarjeta de inspección mensual está firmada y al día.","La recarga anual y la prueba hidrostática están dentro de vigencia.","La manguera, la boquilla y el gatillo están en buen estado.","Los gabinetes contra incendio están completos con manguera, pitón y llave, y sin candado.","La presión de la red contra incendio está dentro del rango de diseño.","La bomba contra incendio arrancó en la prueba semanal y el registro está firmado.","Los rociadores están libres de obstrucciones, con al menos 45 cm libres bajo el deflector.","Los detectores de humo y las alarmas fueron probados y funcionan.","Las luces de emergencia encienden en la prueba y tienen autonomía suficiente.","Las rutas de evacuación están señalizadas, iluminadas y despejadas.","Las puertas de emergencia abren hacia afuera y la barra antipánico está operativa.","El plano de evacuación está publicado y corresponde a la distribución real del local.","El simulacro del período está ejecutado y cuenta con informe.","Los desperdicios combustibles como trapos con aceite y virutas se disponen en recipientes metálicos con tapa."]]]},{"k":"agentes-fisicos-ruido-iluminacion-ventilacion","n":"Agentes físicos: ruido, iluminación y ventilación","ft":"Monitoreo de agentes físicos con periodicidad anual como mínimo, o ante cambio de las condiciones de trabajo. Verificación de condiciones en la inspección planeada mensual.","c":[],"b":[["",["El monitoreo de ruido ocupacional del período está ejecutado y cuenta con informe.","Los puestos con exposición igual o mayor a 85 dBA en 8 horas están identificados y señalizados.","El personal expuesto usa protección auditiva con nivel de reducción de ruido adecuado al nivel medido.","Los trabajadores expuestos están incluidos en el programa de vigilancia audiométrica.","Los equipos ruidosos cuentan con encapsulamiento, silenciadores o aislamiento.","El nivel de iluminación medido cumple el valor requerido por tipo de tarea.","Las luminarias están completas, limpias y sin lámparas quemadas.","No hay deslumbramiento directo ni reflejos sobre las superficies de trabajo.","La ventilación general renueva el aire y no hay acumulación de calor, vapores ni humos.","Los sistemas de extracción localizada están operativos, con campana en el punto de emisión.","Las mediciones están dentro de los límites y el registro de monitoreo está actualizado.","Los equipos de medición cuentan con certificado de calibración vigente.","Las radiaciones electromagnéticas, cuando aplican al proceso, están evaluadas y controladas."]]]},{"k":"sustancias-quimicas-peligrosas","n":"Sustancias químicas peligrosas","ft":"Inspección mensual del área de almacenamiento y uso, con verificación semanal de duchas y lavaojos. Monitoreo de agentes químicos con periodicidad anual.","c":[],"b":[["",["Todos los productos químicos del área cuentan con hoja de datos de seguridad en español, accesible en el punto de uso.","Los envases están rotulados con el nombre del producto y el pictograma SGA o rombo NFPA legible.","No se usan envases de bebidas ni de alimentos para contener productos químicos.","Los productos incompatibles están segregados según la matriz de compatibilidad.","El almacenamiento cuenta con contención secundaria del 110% del mayor envase.","El área de almacenamiento está ventilada, techada y con acceso restringido.","Existe kit antiderrame completo, señalizado y accesible.","La ducha de emergencia y el lavaojos están operativos, con prueba semanal registrada.","El personal cuenta con capacitación vigente en el manejo de la sustancia y en el uso de la hoja de datos de seguridad.","Se provee y se usa el EPP indicado en la hoja de datos de seguridad.","Los cilindros de gases comprimidos están asegurados en posición vertical, con capuchón y separados por tipo.","El inventario de sustancias químicas está actualizado.","La concentración de contaminantes químicos ambientales está dentro de los valores límite permisibles.","La disposición de envases vacíos y residuos peligrosos sigue el procedimiento, con manifiesto y empresa operadora registrada."]]]},{"k":"equipos-de-proteccion-personal","n":"Equipos de protección personal","ft":"Inspección formal mensual del EPP asignado, con verificación diaria por el supervisor durante la actividad e inspección trimestral del EPP contra caídas.","c":["Nombres y apellidos","DNI","Cargo"],"b":[["",["La entrega de EPP está registrada con firma del trabajador y el registro está actualizado.","El EPP entregado corresponde al riesgo identificado en la matriz IPERC del puesto.","El casco no presenta fisuras, deformación ni degradación por exposición solar, y el tafilete está completo.","Los lentes de seguridad están sin rayaduras que impidan la visión y cuentan con protección lateral.","El protector auditivo es del tipo y nivel de reducción de ruido adecuados al nivel medido en el puesto.","El respirador tiene el filtro o cartucho correcto para el contaminante y dentro de vigencia.","La prueba de ajuste para respiradores de ajuste hermético está ejecutada y registrada.","Los guantes corresponden al riesgo mecánico, químico, térmico o dieléctrico y están sin cortes ni perforaciones.","El calzado de seguridad tiene puntera y suela en buen estado, sin desgaste que anule la propiedad antideslizante.","El arnés de cuerpo entero y la línea de vida tienen inspección vigente, sin cortes ni costuras dañadas.","El EPP dañado se retira del servicio y se reemplaza sin costo alguno para el trabajador.","El EPP se almacena limpio, en el lugar asignado y protegido de la intemperie.","El personal usa correctamente el EPP durante la actividad observada."]]]},{"k":"bloqueo-y-etiquetado-loto","n":"Bloqueo y etiquetado de energías en mantenimiento","ft":"Por cada intervención de mantenimiento sobre equipos con energías peligrosas, desde el aislamiento hasta el retiro del último candado y la reinstalación de resguardos.","c":[],"b":[["",["Se identificaron todas las fuentes de energía del equipo antes de intervenir.","Cada ejecutante colocó su candado y su tarjeta personal en el punto de aislamiento.","Se emplea caja de bloqueo grupal cuando intervienen varias especialidades.","Se verificó la ausencia de energía con prueba de arranque antes de iniciar el trabajo.","La energía residual de presión, vapor, resortes, gravedad y condensadores fue liberada o bloqueada.","Los elementos suspendidos están calzados o soportados mecánicamente.","Las válvulas están bloqueadas con dispositivo mecánico y no solamente cerradas.","Las tarjetas indican responsable, fecha, hora y motivo del bloqueo.","El área está señalizada y delimitada durante la intervención.","El desbloqueo lo realiza únicamente quien colocó el candado, tras verificar que no haya personal en zona de riesgo.","El registro de bloqueo y desbloqueo está firmado.","Los resguardos retirados fueron reinstalados al término del trabajo, antes de energizar el equipo."]]]},{"k":"trabajos-en-altura-y-medios-de-acceso","n":"Trabajos en altura y medios de acceso","ft":"Por cada trabajo mediante permiso. Inspección mensual de escaleras portátiles, semestral de escaleras fijas y trimestral del EPP contra caídas.","c":[],"b":[["",["El trabajo por encima de 1.80 m cuenta con permiso de trabajo en altura vigente y firmado.","El trabajador cuenta con examen médico de aptitud para trabajo en altura vigente.","El arnés de cuerpo entero está inspeccionado, sin cortes, quemaduras ni costuras dañadas.","La línea de vida y el absorbedor de impacto están vigentes y sin evidencia de activación previa.","El punto de anclaje resiste la carga requerida y está certificado o validado por ingeniería.","El factor de caída y la distancia de caída libre fueron calculados y son adecuados al espacio disponible.","Las escaleras portátiles están completas, con zapatas antideslizantes y aseguradas en la parte superior.","La escalera portátil sobresale al menos 1 m del punto de desembarque y guarda la relación 4 a 1.","Las escaleras fijas tienen ancho mínimo de 0.90 m y barandas cuando superan los cuatro peldaños.","Los andamios fueron montados por personal competente y cuentan con tarjeta verde de habilitación.","Los andamios tienen plataformas completas, barandas, rodapiés y acceso interno.","Los andamios están nivelados, arriostrados y con ruedas bloqueadas cuando corresponde.","Las plataformas elevadoras cuentan con certificación e inspección vigentes y con operador autorizado.","El área inferior está delimitada y señalizada para evitar la caída de objetos sobre terceros.","Las herramientas están aseguradas con drizas o portaherramientas.","Las aberturas en piso están cubiertas o protegidas con baranda."]]]},{"k":"lineas-de-produccion-orden-y-limpieza","n":"Líneas de producción, orden y limpieza","ft":"Inspección planeada mensual, con verificación diaria del supervisor al inicio y término de turno.","c":[],"b":[["",["Los pasillos y vías de circulación están demarcados, despejados y con el ancho reglamentario.","Las salidas y rutas de evacuación no están obstruidas.","Los pisos están limpios, sin derrames de aceite, agua o producto, y sin desniveles peligrosos.","Los desagües y canaletas están cubiertos y a nivel del piso.","Los materiales en proceso están en zonas demarcadas y apilados de forma estable.","Las herramientas están en su lugar asignado y no dispersas sobre las máquinas.","Los residuos están segregados en los contenedores señalizados y no acumulados.","Los desperdicios combustibles se disponen en recipientes metálicos con tapa.","La señalización de seguridad del área está instalada, legible y vigente.","Los equipos de emergencia como extintores, ducha, lavaojos, botiquín y camilla están accesibles y señalizados.","El nivel de iluminación es adecuado y no hay luminarias quemadas.","La ventilación y la extracción localizada están operativas.","Los servicios higiénicos y vestuarios están operativos, limpios y en cantidad suficiente.","La altura del local es de al menos 3.5 m en el primer piso y 3 m en los pisos superiores.","Se respeta el aforo de 10 metros cuadrados por trabajador.","Las escaleras internas tienen ancho mínimo de 0.90 m y barandas cuando superan los cuatro peldaños.","Los tableros y equipos energizados no tienen materiales apoyados ni están obstruidos."]]]}]}};
var FMT_EQ = [{"k":"chk-amoladora","n":"Check list de amoladora","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Identificación y disco correcto",["Tiene su código y la cinta del color del mes, visibles.","El disco es del diámetro de la máquina (4½″, 7″ o 9″).","Las RPM del disco son iguales o mayores a las de la máquina.","El disco es el del trabajo: de corte para cortar, de desbaste para desbastar."]],["Carcasa y mango lateral",["La carcasa no tiene rajaduras, piezas sueltas ni tornillos faltantes.","El mango lateral está puesto y bien ajustado.","Las rejillas de ventilación están limpias, sin polvo acumulado."]],["Guarda y disco",["La guarda está completa, bien fijada y orientada hacia el operador.","El disco no está rajado, desportillado, gastado, vencido ni húmedo.","La brida y la tuerca están completas y ajustadas con su llave.","El seguro del eje (botón de bloqueo) funciona."]],["Cable, enchufe e interruptor",["El cable no tiene cortes, empalmes, cinta aislante ni partes peladas.","El enchufe está entero y tiene su espiga a tierra.","El interruptor enciende y apaga bien, y no se queda trabado.","El cable va por donde no lo pisen, no lo mojen ni lo corten bordes filosos."]],["Prueba en vacío",["En vacío gira sin vibración, ruido raro ni olor a quemado.","El disco gira sin bamboleo ni juego."]],["EPP y entorno",["El operador usa careta facial sobre los lentes, guantes y protección auditiva.","No hay material inflamable cerca y hay biombo o manta contra las chispas.","Se conecta a un tablero con interruptor diferencial."]]]},{"k":"chk-taladro","n":"Check list de taladro y rotomartillo","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Carcasa y empuñaduras",["La carcasa no tiene rajaduras, piezas sueltas ni tornillos faltantes.","La empuñadura auxiliar (mango lateral) está puesta y bien ajustada.","Las rejillas de ventilación están limpias, sin polvo acumulado."]],["Mandril y broca",["El mandril (o el portabrocas SDS) sujeta la broca sin juego.","La llave del mandril se retira antes de encender.","La broca está afilada, recta y es la del material.","El selector (giro, percusión o cincel) cambia bien y queda firme.","El tope de profundidad (si tiene) está firme."]],["Cable, enchufe e interruptor",["El cable no tiene cortes, empalmes, cinta aislante ni partes peladas.","El enchufe está entero y tiene su espiga a tierra.","El interruptor enciende y apaga bien, y no se queda trabado.","El cable va por donde no lo pisen, no lo mojen ni lo corten bordes filosos."]],["Prueba en vacío",["En vacío gira sin vibración, ruido raro ni olor a quemado."]],["Identificación, EPP y entorno",["Tiene su código y la cinta del color del mes, visibles.","Se conecta a un tablero con interruptor diferencial.","El operador usa lentes, guantes y protección auditiva."]],["Antes de perforar",["Se verificó que no haya cables ni tuberías ocultas donde se va a perforar."]]]},{"k":"chk-sierra-circular","n":"Check list de sierra circular","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Carcasa y empuñaduras",["La carcasa no tiene rajaduras, piezas sueltas ni tornillos faltantes.","Las empuñaduras están enteras y firmes.","Las rejillas de ventilación están limpias, sin polvo acumulado."]],["Guardas",["La guarda superior está completa y fija.","La guarda inferior (móvil) baja sola y no se traba.","La guarda inferior no está amarrada, calzada ni retirada."]],["Disco, cuchillo y base",["El disco está afilado, sin dientes rotos ni rajaduras.","El diámetro y las RPM del disco son los de la sierra.","El cuchillo divisor está puesto y alineado con el disco.","La base está plana y los ajustes de profundidad y ángulo quedan firmes."]],["Cable, enchufe e interruptor",["El cable no tiene cortes, empalmes, cinta aislante ni partes peladas.","El enchufe está entero y tiene su espiga a tierra.","El interruptor enciende y apaga bien, y no se queda trabado.","El cable va por donde no lo pisen, no lo mojen ni lo corten bordes filosos."]],["Prueba en vacío",["En vacío gira sin vibración, ruido raro ni olor a quemado.","El disco se detiene al soltar el gatillo."]],["EPP y entorno",["El operador usa careta o lentes, guantes y protección auditiva.","La pieza va apoyada y sujeta; nunca se corta sosteniéndola con la mano.","Se conecta a un tablero con interruptor diferencial.","Tiene su código y la cinta del color del mes, visibles."]]]},{"k":"chk-esmeril","n":"Check list de esmeril","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Montaje",["Está anclado a su banco o pedestal y no se mueve.","La carcasa no tiene rajaduras, piezas sueltas ni tornillos faltantes."]],["Guardas y apoyos",["Las guardas laterales cubren las piedras.","El apoya-piezas está a no más de 3 mm de la piedra.","La guarda superior está a no más de 6 mm de la piedra.","La pantalla transparente está entera y limpia."]],["Piedras",["Las piedras no tienen rajaduras, desportilladuras ni desgaste disparejo.","Las RPM de las piedras son iguales o mayores a las del esmeril.","Las bridas y tuercas están completas y ajustadas."]],["Eléctrico",["El cable no tiene cortes, empalmes, cinta aislante ni partes peladas.","El enchufe está entero y tiene su espiga a tierra.","El interruptor enciende y apaga bien, y no se queda trabado."]],["Prueba en vacío",["Se arranca parado a un costado, no frente a la piedra.","En vacío gira sin vibración, ruido raro ni olor a quemado."]],["EPP y entorno",["El operador usa careta facial sobre los lentes y guantes ajustados.","No hay material inflamable cerca.","Tiene su código y la cinta del color del mes, visibles."]]]},{"k":"chk-pulidora","n":"Check list de pulidora","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Carcasa y empuñaduras",["La carcasa no tiene rajaduras, piezas sueltas ni tornillos faltantes.","La empuñadura auxiliar (mango lateral) está puesta y bien ajustada.","Las rejillas de ventilación están limpias, sin polvo acumulado."]],["Plato y paño",["El plato está entero, bien roscado y sin golpes.","El paño, la lija o la esponja están bien sujetos y sin desgaste.","Las RPM del accesorio son las de la máquina."]],["Cable, enchufe e interruptor",["El cable no tiene cortes, empalmes, cinta aislante ni partes peladas.","El enchufe está entero y tiene su espiga a tierra.","El interruptor enciende y apaga bien, y no se queda trabado.","El cable va por donde no lo pisen, no lo mojen ni lo corten bordes filosos."]],["Prueba en vacío",["En vacío gira sin vibración, ruido raro ni olor a quemado."]],["Identificación, EPP y entorno",["Tiene su código y la cinta del color del mes, visibles.","Se conecta a un tablero con interruptor diferencial.","El operador usa lentes, guantes y protección auditiva."]]]},{"k":"chk-soldadora","n":"Check list de máquina de soldar","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Equipo",["La carcasa no tiene rajaduras, piezas sueltas ni tornillos faltantes.","Las rejillas están libres y el ventilador funciona.","Los controles (amperaje) y el indicador de encendido responden."]],["Cables y conexiones",["Los cables de soldar no tienen cortes, empalmes ni partes peladas.","Las conexiones a la máquina están ajustadas y aisladas.","El porta-electrodo está entero y aislado.","La pinza de tierra está completa y va cerca de la zona de soldadura."]],["Alimentación",["El cable de alimentación y el enchufe están enteros, con tierra.","Se conecta a un tablero con diferencial y su propio interruptor."]],["Entorno",["Hay un extintor a la mano.","No hay material inflamable cerca, o está cubierto.","Hay biombos o mantas que protegen a los demás de la luz y las chispas.","La zona está seca y ventilada."]],["EPP e identificación",["El soldador usa careta con el filtro adecuado, guantes de cuero, casaca o mandil y escarpines.","Tiene su código y la cinta del color del mes, visibles."]]]},{"k":"chk-extension","n":"Check list de extensión eléctrica","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Cable",["El cable es vulcanizado y del calibre que pide la carga.","El cable no tiene cortes, empalmes, cinta aislante ni partes peladas.","No está aplastado, deformado ni con nudos."]],["Enchufe y tomacorrientes",["El enchufe está entero y tiene su espiga a tierra.","La caja de tomacorrientes es industrial, entera y con sus tapas.","Los tomacorrientes no están quemados ni flojos."]],["Uso",["Se desenrolla completa antes de usarla (enrollada se calienta).","El cable va por donde no lo pisen, no lo mojen ni lo corten bordes filosos.","No se conectan más equipos de los que soporta.","Se conecta a un tablero con interruptor diferencial."]],["Identificación",["Tiene su código y la cinta del color del mes, visibles."]]]},{"k":"chk-herr-electrica","n":"Check list de herramienta eléctrica","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Carcasa y empuñaduras",["La carcasa no tiene rajaduras, piezas sueltas ni tornillos faltantes.","La empuñadura auxiliar (mango lateral) está puesta y bien ajustada.","Las rejillas de ventilación están limpias, sin polvo acumulado."]],["Accesorio y guardas",["El accesorio de trabajo (broca, disco, cuchilla) está en buen estado y es el adecuado.","Las guardas están completas y en su sitio."]],["Cable, enchufe e interruptor",["El cable no tiene cortes, empalmes, cinta aislante ni partes peladas.","El enchufe está entero y tiene su espiga a tierra.","El interruptor enciende y apaga bien, y no se queda trabado.","El cable va por donde no lo pisen, no lo mojen ni lo corten bordes filosos."]],["Prueba en vacío",["En vacío gira sin vibración, ruido raro ni olor a quemado."]],["Identificación, EPP y entorno",["Tiene su código y la cinta del color del mes, visibles.","Se conecta a un tablero con interruptor diferencial.","El operador usa lentes, guantes y protección auditiva."]]]},{"k":"chk-herr-manual","n":"Check list de herramienta manual","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Identificación",["Tiene su código y la cinta del color del mes, visibles.","Es la herramienta adecuada para el trabajo (no se improvisa)."]],["Mango",["El mango está entero, sin rajaduras, astillas ni cinta.","El mango está bien encajado, sin juego.","El mango está limpio, sin grasa ni aceite."]],["Cabeza o parte de trabajo",["La cabeza no tiene rebabas, hongos ni deformaciones.","Los filos y las puntas están en buen estado.","Las bocas o mordazas no están gastadas ni abiertas.","No tiene soldaduras ni reparaciones caseras."]],["Aislamiento (si es dieléctrica)",["El aislamiento está entero y con su marca de tensión."]],["Uso y guardado",["En altura va amarrada con su driza.","Se guarda limpia en su caja o tablero."]]]},{"k":"chk-carretilla","n":"Check list de carretilla","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Tolva y bastidor",["La tolva no tiene rajaduras, huecos ni bordes cortantes.","El bastidor no está doblado ni tiene soldaduras rotas.","Las patas de apoyo están firmes."]],["Rueda",["La llanta está inflada y sin cortes.","El eje gira libre y está ajustado."]],["Manijas",["Las manijas están rectas, firmes y con sus puños."]],["Uso",["No se carga por encima del borde ni más de lo que soporta.","El recorrido está libre, sin desniveles bruscos.","Tiene su código y la cinta del color del mes, visibles."]]]},{"k":"chk-caja","n":"Check list de caja de herramientas","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["La caja",["Está entera, cierra bien y tiene su asa.","Tiene su código y la lista de lo que lleva."]],["Contenido",["Está completa: no falta ninguna de la lista.","Cada herramienta tiene su código y la cinta del mes.","No hay herramientas dañadas ni hechizas."]],["Orden",["Las herramientas cortantes van protegidas.","No guarda químicos ni comida.","Está limpia y ordenada."]]]},{"k":"chk-eslinga","n":"Check list de eslinga","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Etiqueta",["Tiene su etiqueta legible, con el fabricante y la carga límite de trabajo.","Tiene su código y la cinta del color del mes, visibles."]],["Cuerpo",["No tiene cortes, desgarros ni hilos rotos.","No tiene quemaduras, partes derretidas ni endurecidas.","No tiene manchas de químicos ni decoloración.","Las costuras están completas.","No tiene nudos."]],["Ojales",["Los ojales no están gastados ni abiertos.","El hilo testigo (si tiene) no está a la vista."]],["Uso",["Los cantos vivos de la carga se protegen.","Se respeta la carga según el enganche (directo, ahorcado o canasta)."]]]},{"k":"chk-estrobo","n":"Check list de estrobo","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Identificación",["Tiene su placa o etiqueta con la carga límite de trabajo.","Tiene su código y la cinta del color del mes, visibles."]],["Cable",["No tiene alambres rotos a la vista.","No tiene aplastamientos, cocas, jaula de pájaro ni torones salidos.","No tiene corrosión y está lubricado.","Su diámetro no está reducido."]],["Terminales",["Los casquillos prensados no tienen fisuras ni deslizamiento.","Los guardacabos están en su sitio y sin deformación.","Los ojales no están deformados."]],["Uso",["Los cantos vivos de la carga se protegen.","Los ganchos y grilletes que van con él son de la capacidad necesaria."]]]},{"k":"chk-grillete","n":"Check list de grillete","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Identificación",["Tiene marcada la carga límite de trabajo y el fabricante.","Tiene su código y la cinta del color del mes, visibles."]],["Cuerpo",["No está abierto, torcido ni deformado.","No tiene fisuras, desgaste ni corrosión.","No tiene soldaduras ni fue calentado."]],["Pasador",["El pasador es el original y entra completo, a mano.","La rosca está en buen estado.","El de pasador con tuerca lleva su chaveta."]],["Uso",["La carga va en línea, sin tirones laterales."]]]},{"k":"chk-tecle","n":"Check list de tecle","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Identificación",["Tiene marcada su capacidad.","Tiene su código y la cinta del color del mes, visibles."]],["Ganchos",["Los ganchos no están abiertos, torcidos ni con fisuras.","Los pestillos cierran solos.","El gancho gira libre."]],["Cadena",["La cadena no tiene eslabones estirados, doblados ni gastados.","La cadena de mano está completa y sin nudos.","La cadena está lubricada."]],["Mecanismo y freno",["Sube y baja sin trabarse ni saltar.","El freno sostiene la carga (se prueba con poca carga).","La carcasa está completa."]],["Montaje",["Cuelga de un punto firme y de la capacidad necesaria.","El área de maniobra está delimitada y nadie pasa debajo de la carga."]]]},{"k":"chk-grua-torre","n":"Check list de grúa torre","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Operador y documentos",["El operador está capacitado y autorizado para este equipo.","Su certificado de operatividad y su mantenimiento están vigentes.","El libro o registro de la grúa está al día.","Hay permiso de izaje para la maniobra crítica (si lo es).","El rigger y el señalero están designados y se comunican por radio o con señales."]],["Cabina y mandos",["La cabina está limpia, con buena visibilidad y el asiento firme.","Los mandos vuelven solos a cero.","La parada de emergencia funciona.","La tabla de cargas está a la vista.","La radio funciona."]],["Estructura",["La base, el lastre y los anclajes están firmes y sin fisuras.","Los tramos de la torre, sus pernos y pasadores están completos y ajustados.","La pluma y la contrapluma no tienen deformaciones ni fisuras.","Los contrapesos están en su sitio y asegurados.","Las escaleras, plataformas y barandas de acceso están completas.","La línea de vida para subir está instalada."]],["Cables, poleas y gancho",["Los cables no tienen hilos rotos, aplastamientos, cocas ni corrosión.","Los cables enrollan parejo en el tambor.","Las poleas giran libres y sin desgaste.","El carro se desplaza sin saltos.","El gancho no está abierto ni deformado, y su pestillo cierra solo."]],["Dispositivos de seguridad",["El limitador de carga y el de momento funcionan.","Los finales de carrera de altura, carro y giro funcionan.","El anemómetro funciona y se respeta el viento máximo.","Los frenos de elevación, carro y giro sostienen.","Las luces de balizaje y la bocina funcionan."]],["Área de maniobra",["El área de maniobra está delimitada y nadie pasa debajo de la carga.","No hay líneas eléctricas dentro del radio de trabajo.","Las eslingas, estrobos y grilletes están inspeccionados y son de la capacidad necesaria."]]]},{"k":"chk-grua-movil","n":"Check list de grúa móvil","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Operador y documentos",["El operador está capacitado y autorizado para este equipo.","Su certificado de operatividad y su mantenimiento están vigentes.","La tabla de cargas está en la cabina.","Hay permiso de izaje para la maniobra crítica (si lo es).","El rigger y el señalero están designados y se comunican por radio o con señales."]],["Cabina y mandos",["La cabina está limpia, con buena visibilidad y el asiento firme.","Los mandos responden y vuelven solos a neutro.","La radio funciona.","Hay extintor en la cabina."]],["Chasis, llantas y estabilizadores",["Las llantas están infladas y sin cortes.","No hay fugas de aceite, combustible ni hidráulico.","Los estabilizadores salen completos, sobre tacos o placas.","La grúa está nivelada.","El terreno es firme y no hay zanjas cerca."]],["Pluma, cables y gancho",["La pluma sale y entra sin golpes.","Las secciones de la pluma no tienen fisuras ni deformaciones.","Los cables no tienen hilos rotos, aplastamientos, cocas ni corrosión.","El gancho no está abierto ni deformado, y su pestillo cierra solo."]],["Dispositivos de seguridad",["El indicador de momento de carga (LMI) funciona.","El limitador de fin de carrera del gancho (anti dos bloques) funciona.","La alarma de retroceso, la bocina y las luces funcionan.","Los frenos y el freno de estacionamiento funcionan."]],["Área de maniobra",["El área de maniobra está delimitada y nadie pasa debajo de la carga.","No hay líneas eléctricas dentro del radio de trabajo.","Las eslingas, estrobos y grilletes están inspeccionados y son de la capacidad necesaria."]]]},{"k":"chk-camion-grua","n":"Check list de camión grúa","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Operador y documentos",["El operador está capacitado y autorizado para este equipo.","Su certificado de operatividad y su mantenimiento están vigentes.","Su SOAT y su revisión técnica están vigentes.","Hay permiso de izaje para la maniobra crítica (si lo es).","El rigger y el señalero están designados y se comunican por radio o con señales."]],["Camión",["Las llantas están infladas y sin cortes.","Las luces, la bocina y la alarma de retroceso funcionan.","Los frenos y el freno de estacionamiento funcionan.","No hay fugas de aceite, combustible ni hidráulico.","Lleva extintor, botiquín, conos y tacos."]],["Estabilizadores",["Los estabilizadores salen completos, sobre tacos o placas.","El camión queda nivelado sobre terreno firme."]],["Pluma, cables y gancho",["La pluma sale, gira y se recoge sin golpes.","Los cilindros hidráulicos no tienen fugas.","Los cables no tienen hilos rotos, aplastamientos, cocas ni corrosión.","El gancho no está abierto ni deformado, y su pestillo cierra solo."]],["Dispositivos de seguridad",["El limitador de carga funciona.","Los mandos vuelven solos a neutro y la parada de emergencia funciona."]],["Carga y área",["La carga en la plataforma va asegurada.","El área de maniobra está delimitada y nadie pasa debajo de la carga.","No hay líneas eléctricas dentro del radio de trabajo."]]]},{"k":"chk-puente-grua","n":"Check list de puente grúa","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Operador y documentos",["El operador está capacitado y autorizado para este equipo.","Su capacidad está marcada en la viga, visible desde el piso.","Su certificado de operatividad y su mantenimiento están vigentes."]],["Botonera",["La botonera está entera y sus botones rotulados.","La parada de emergencia funciona.","Cada movimiento responde en el sentido indicado."]],["Estructura y rieles",["Las vigas, rieles y topes finales están completos y sin deformaciones.","Los rieles están libres de obstáculos."]],["Cable, tambor y gancho",["Los cables no tienen hilos rotos, aplastamientos, cocas ni corrosión.","El cable enrolla parejo en el tambor.","El polipasto no hace ruidos raros ni tiene fugas.","El gancho no está abierto ni deformado, y su pestillo cierra solo."]],["Dispositivos de seguridad",["Los finales de carrera de subida, bajada y traslación funcionan.","El freno sostiene la carga.","La alarma sonora o luminosa funciona al moverse."]],["Área",["El área de maniobra está delimitada y nadie pasa debajo de la carga.","La zona de maniobra está libre."]]]},{"k":"chk-arnes","n":"Check list de arnés","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Etiqueta",["Tiene su etiqueta legible (fabricante, fecha y norma).","Está dentro de la vida útil que indica el fabricante.","Tiene su código y la cinta del color del mes, visibles."]],["Correas",["No tienen cortes, deshilachados ni quemaduras.","No tienen manchas de químicos, pintura ni decoloración.","Las costuras están completas, sin hilos sueltos.","El indicador de impacto (si tiene) está intacto."]],["Anillos y hebillas",["El anillo D dorsal no está deformado ni con fisuras.","Las hebillas cierran y ajustan bien.","Los herrajes no tienen corrosión ni bordes filosos."]],["Uso",["Se ajusta al cuerpo: piernas, pecho y hombros.","Nunca detuvo una caída (si detuvo una, se da de baja)."]]]},{"k":"chk-linea-vida","n":"Check list de línea de vida","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Etiqueta",["Tiene su etiqueta legible (fabricante, fecha y norma).","Está dentro de la vida útil que indica el fabricante.","Tiene su código y la cinta del color del mes, visibles."]],["Cinta o cuerda",["No tiene cortes, deshilachados ni quemaduras.","No tiene nudos.","Las costuras están completas."]],["Absorbedor de impacto",["El absorbedor está cerrado: no está abierto ni desplegado.","Su funda está entera."]],["Ganchos y conectores",["Los ganchos cierran solos y tienen doble seguro.","No están deformados ni con corrosión.","Los resortes funcionan."]],["Uso",["Se ancla a un punto firme, por encima del hombro.","Nunca detuvo una caída (si detuvo una, se da de baja)."]]]},{"k":"chk-retractil","n":"Check list de tambor retráctil","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Identificación",["Tiene su etiqueta legible (fabricante, fecha y norma).","Su mantenimiento o recertificación está vigente según el fabricante.","Tiene su código y la cinta del color del mes, visibles."]],["Carcasa",["La carcasa no tiene golpes, fisuras ni tornillos faltantes.","El indicador de impacto (si tiene) no está activado."]],["Cable o cinta",["Sale y se recoge completo, sin trabarse.","No tiene hilos rotos, cortes ni dobleces."]],["Freno",["Al jalar fuerte, bloquea al instante."]],["Conectores y anclaje",["El gancho gira y su seguro cierra solo.","Se ancla a un punto firme, por encima del trabajador.","Nunca detuvo una caída (si detuvo una, se da de baja)."]]]},{"k":"chk-lavaojos","n":"Check list de lavaojos","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Ubicación",["Está señalizado y a no más de 10 segundos de donde se usan químicos.","El acceso está libre."]],["Funcionamiento",["Se activa con un solo movimiento y queda abierto solo.","El agua sale por las dos boquillas a la vez, con chorro suave.","Las tapas de las boquillas están puestas."]],["Agua",["El agua sale limpia (se deja correr cada semana).","Si es portátil, el agua o la solución está vigente."]],["Registro",["Su tarjeta de inspección está al día y a la vista."]]]},{"k":"chk-camilla","n":"Check list de camilla","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Estructura",["La tabla no tiene rajaduras, astillas ni bordes filosos.","Las asas están completas y firmes."]],["Inmovilización",["Tiene sus correas completas y sus hebillas cierran.","Tiene inmovilizador de cabeza.","Hay un collarín cervical a la mano."]],["Ubicación",["Está señalizada, limpia y a la vista.","El acceso está libre."]],["Registro",["Su tarjeta de inspección está al día y a la vista."]]]},{"k":"chk-luz-emergencia","n":"Check list de luz de emergencia","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Equipo",["Está entera y bien fijada.","El indicador de carga está encendido."]],["Prueba",["Al cortar la energía o apretar su botón de prueba, enciende sola.","Alumbra la ruta de evacuación o la salida.","La batería sostiene la luz durante la prueba."]],["Conexión",["Está conectada a un tomacorriente sin interruptor.","El cable no está pelado ni con empalmes."]],["Registro",["Su tarjeta de inspección está al día y a la vista."]]]},{"k":"chk-alarma","n":"Check list de alarma de emergencia","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Equipo",["Está entera, fijada y señalizada.","Su batería o su conexión funcionan."]],["Prueba",["Suena al activarla.","Se escucha en toda la obra o en toda su zona.","El pulsador o la manivela están a la mano."]],["El personal",["El personal reconoce el sonido y sabe qué hacer al oírlo."]],["Registro",["Su tarjeta de inspección está al día y a la vista."]]]},{"k":"chk-tablero","n":"Check list de tablero eléctrico","ft":"Cada mes, y antes de usarlo si hay dudas","c":["Código","Equipo","Ubicación"],"b":[["Gabinete",["El gabinete está entero y tiene su puerta.","La puerta cierra y tiene su chapa o candado.","Está protegido de la lluvia y elevado del piso."]],["Rotulado y señalización",["Tiene la señal de riesgo eléctrico.","Cada interruptor está rotulado con lo que alimenta.","Tiene el diagrama o la lista de circuitos en la puerta."]],["Protecciones",["Tiene interruptor general.","Cada circuito de tomacorrientes tiene interruptor diferencial.","El diferencial salta al apretar su botón de prueba.","No hay interruptores puenteados."]],["Conexiones y cables",["No hay cables pelados, empalmes ni conexiones sueltas.","Los cables entran por prensaestopas, no por la puerta.","No hay partes calientes, quemadas ni con olor.","Los tomacorrientes son industriales y están enteros."]],["Puesta a tierra",["El tablero está conectado a tierra.","El pozo a tierra tiene su medición vigente."]],["Acceso",["El frente del tablero está libre.","Solo lo opera el electricista autorizado.","Hay un extintor para fuego eléctrico (CO₂ o PQS) cerca.","Tiene su código y la cinta del color del mes, visibles."]]]},{"k":"chk-montacargas","n":"Check list de montacargas","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Operador y documentos",["El operador está capacitado y autorizado para este equipo.","Su capacidad está marcada en la placa.","Su mantenimiento está al día."]],["Mástil, horquillas y cadenas",["Las horquillas no tienen fisuras, dobleces ni desgaste.","Los seguros de las horquillas están puestos.","Las cadenas del mástil están parejas, tensas y lubricadas.","El mástil sube, baja e inclina sin golpes ni fugas.","El respaldo de carga está completo."]],["Llantas y chasis",["Las llantas no tienen cortes ni desgaste excesivo.","No hay fugas de aceite, combustible ni hidráulico.","El techo protector está completo."]],["Seguridad",["El cinturón de seguridad funciona y se usa.","La bocina, la alarma de retroceso y las luces funcionan.","Los frenos y el freno de estacionamiento funcionan.","La dirección responde sin juego.","Tiene extintor."]],["Combustible o batería",["El balón de GLP está sujeto y sin fugas (si es a gas).","La batería está sujeta y sus bornes limpios (si es eléctrico)."]],["Área",["Los pasillos están libres y señalizados.","Se circula con la carga baja y despacio."]]]},{"k":"chk-compresora","n":"Check list de compresora","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Equipo",["La carcasa y las guardas de las correas están completas.","No hay fugas de aceite, combustible ni hidráulico.","El nivel de aceite está correcto."]],["Presión",["El manómetro funciona y marca dentro de su rango.","La válvula de seguridad está en su sitio y no fue manipulada.","El tanque no tiene corrosión ni golpes.","Se purga el agua del tanque."]],["Mangueras y acoples",["Las mangueras no tienen cortes, abultamientos ni fugas.","Los acoples tienen su seguro y su cable o cadena anti-látigo.","Las abrazaderas están completas y ajustadas."]],["Motor",["El cable y el enchufe están enteros, con tierra (si es eléctrica).","El escape va lejos de lugares cerrados (si es a combustión)."]],["Entorno",["Está nivelada y con las ruedas trabadas.","Hay un extintor a la mano.","El aire nunca se dirige al cuerpo.","Tiene su código y la cinta del color del mes, visibles."]]]},{"k":"chk-generador","n":"Check list de grupo electrógeno","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Equipo",["La carcasa y sus puertas están completas.","No hay fugas de combustible, aceite ni refrigerante.","Los niveles de aceite, refrigerante y combustible están bien."]],["Eléctrico",["Está conectado a tierra.","Tiene interruptor termomagnético y diferencial a la salida.","Los cables de salida están enteros y bien conectados.","El panel de control y sus indicadores funcionan."]],["Escape",["Está al aire libre o con el escape hacia afuera.","El silenciador y el tubo de escape están completos."]],["Seguridad",["La parada de emergencia funciona.","Hay un extintor a la mano.","Se carga combustible con el motor apagado y frío.","Está delimitado y señalizado (riesgo eléctrico y ruido)."]],["Ubicación",["Está nivelado sobre una base firme.","Tiene bandeja o kit antiderrames.","Tiene su código y la cinta del color del mes, visibles."]]]},{"k":"chk-mezcladora","n":"Check list de mezcladora","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Estructura",["El chasis y el tambor no tienen fisuras.","Está nivelada y trabada, con tacos en las ruedas."]],["Partes en movimiento",["Las guardas de la correa, la cadena o los engranajes están completas.","El volante de volteo funciona y queda trabado.","El tambor gira sin golpes."]],["Motor",["No hay fugas de aceite, combustible ni hidráulico.","El cable y el enchufe están enteros, con tierra (si es eléctrica).","El arranque y la parada funcionan."]],["Uso y EPP",["Nadie mete las manos ni herramientas al tambor en movimiento.","Se usan lentes, guantes, mascarilla y protección auditiva.","La zona está limpia de concreto y sin charcos.","Tiene su código y la cinta del color del mes, visibles."]]]},{"k":"chk-vibradora","n":"Check list de vibradora","ft":"Antes de usarlo, cada día","c":["Código","Equipo","Ubicación"],"b":[["Motor",["La carcasa está completa y las rejillas limpias.","El cable y el enchufe están enteros, con tierra (si es eléctrica).","No hay fugas de combustible (si es a gasolina).","El interruptor enciende y apaga bien, y no se queda trabado."]],["Manguera y cabezal",["La manguera no tiene cortes ni dobleces.","El acople al motor está firme.","El cabezal no tiene golpes ni desgaste excesivo."]],["Uso y EPP",["El motor va sobre una base firme, fuera del encofrado.","Se usan guantes, botas de jebe, lentes y protección auditiva.","El cable va por donde no lo pisen, no lo mojen ni lo corten bordes filosos.","Tiene su código y la cinta del color del mes, visibles."]]]}];
