/* ══ 9/11/2026 · LA SECCIÓN «FORMATOS» DE LA WEB ══════════════════════════════════════════════════════════════════════
   Los mismos formatos en blanco de la app (FMT, arriba): las tres pestañas, el buscador y, en cada uno, su código, su
   versión y su fecha de versión (se cambian aquí o en la app: son los de sst_estado «formatos», los mismos de «Códigos de
   formato») y «⬇ PDF», con el logo de la empresa. Los check list de equipos y las inspecciones de obra vienen de la app
   (FMT_CAT y FMT_EQ, los arma herr/formatos-web.js). */
var FMTW = { tab:'reg', q:'', ed:'', fm:null, emp:null, logo:null, obra:null };
var FMTW_TABS = [['reg', '🧾', 'Registros'], ['eq', '🏷️', 'Check list de equipos'], ['obra', '✅', 'Inspecciones de obra']];
function _fmtwSector(){ var s=String((YO.obra && YO.obra.sector) || '').toLowerCase(); return FMT_CAT[s] ? s : 'construccion'; }
function _fmtwItems(){ return FMT.lista(_fmtwSector(), FMT_CAT, FMT_EQ); }
function _fmtwItem(k){ var l=_fmtwItems(); for(var i=0;i<l.length;i++) if(l[i].k===k) return l[i]; return null; }
function _fmtwCodigo(it){
  var o=FMTW.fm || {}, x=it.tipo==='reg' ? ((o.items||{})[it.k] || {}) : ((o.insp||{})[it.k] || {});
  return { cod:String(x.cod||''), rev:String(x.rev||'00'), fecha:String(x.fecha||'') };
}
function _fmtwCss(){
  if($('fmtw-css')) return;
  var st=document.createElement('style'); st.id='fmtw-css';
  st.textContent=[
    '.fmtw-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:0 0 14px}',
    '.fmtw-tabs button{appearance:none;-webkit-appearance:none;display:flex;align-items:center;justify-content:center;gap:8px;padding:11px 10px;border-radius:12px;border:1px solid var(--raya);background:var(--panel);color:var(--texto);font:inherit;font-size:13.5px;font-weight:600;cursor:pointer;transition:border-color .15s ease,background .15s ease,transform .15s ease}',
    '.fmtw-tabs button:hover{border-color:var(--raya2)}.fmtw-tabs button.on{border-color:var(--tinta);box-shadow:0 0 0 1px var(--tinta) inset;background:var(--fondo)}',
    '.fmtw-busca{display:flex;align-items:center;gap:8px;border:1px solid var(--raya);border-radius:11px;padding:0 12px;background:var(--panel)}.fmtw-busca input{border:0;outline:0;flex:1;padding:11px 0;font:inherit;background:none;color:var(--texto)}',
    '.fmtw-lista{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:10px;margin:14px 0 0}',
    '.fmtw-f{display:flex;flex-direction:column;gap:8px;border:1px solid var(--raya);border-radius:13px;background:var(--panel);padding:13px 14px;transition:border-color .15s ease,box-shadow .15s ease,transform .15s ease}',
    '.fmtw-f:hover{border-color:var(--raya2);box-shadow:0 6px 20px rgba(11,42,58,.07);transform:translateY(-1px)}',
    '.fmtw-f .cab{display:flex;gap:11px;align-items:flex-start}.fmtw-f .ic{flex:0 0 auto;width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:var(--fondo);font-size:19px}',
    '.fmtw-f b{display:block;font-weight:600;color:var(--tinta);font-size:14.5px;line-height:1.3}.fmtw-f small{display:block;color:var(--gris);font-size:12.5px;line-height:1.45;margin-top:2px}',
    '.fmtw-cod{align-self:flex-start;font-size:12px;padding:3px 9px;border-radius:999px;background:var(--fondo);color:var(--tinta)}.fmtw-cod.sin{background:#FFF6DA;color:#8A6100}',
    '.fmtw-acc{display:flex;gap:8px;margin-top:auto}.fmtw-acc .bt{flex:1}',
    '.fmtw-ed{display:grid;grid-template-columns:2fr 1fr 1.5fr;gap:8px;border-top:1px dashed var(--raya);padding-top:10px}.fmtw-ed label{font-size:12px;color:var(--gris)}.fmtw-ed input{width:100%}',
    '@media (max-width:700px){.fmtw-tabs{grid-template-columns:1fr}.fmtw-ed{grid-template-columns:1fr 1fr}}'
  ].join('\n');
  document.head.appendChild(st);
}
function fmtVista(caja){
  _fmtwCss();
  var oid=(YO.obra||{}).id;
  if(FMTW.obra!==oid){ FMTW.obra=oid; FMTW.fm=null; FMTW.emp=null; FMTW.logo=null; FMTW.ed=''; }
  FMTW.caja=caja;
  var ac=$('acciones'); if(ac) ac.innerHTML='';
  _fmtwPintar();
  Promise.all([estadoLeerP('formatos').then(null, function(){ return null; }), empleadorP().then(null, function(){ return null; })]).then(function(r){
    if(FMTW.obra!==oid) return;
    var v=r[0] && r[0].valor; FMTW.fm=(v && typeof v==='object') ? v : {};
    FMTW.emp=r[1] || {};
    _fmtwPintar();
  });
}
function _fmtwListaHTML(){
  var q=String(FMTW.q||'').toLowerCase().trim();
  try{ q=q.normalize('NFD').replace(/[̀-ͯ]/g, ''); }catch(_n){}
  var l=_fmtwItems().filter(function(it){
    if(!q) return it.g===FMTW.tab;
    var t=(it.n+' '+(it.d||'')).toLowerCase(); try{ t=t.normalize('NFD').replace(/[̀-ͯ]/g, ''); }catch(_t){}
    return t.indexOf(q)>-1;
  });
  if(!l.length) return '<p class="gris">Ningún formato con ese nombre.</p>';
  return l.map(function(it){
    var C=_fmtwCodigo(it), id=esc(it.k);
    var cod=C.cod ? '<span class="fmtw-cod">'+esc(C.cod+' · v'+C.rev+(C.fecha ? ' · '+C.fecha.slice(0, 10).split('-').reverse().join('/') : ''))+'</span>'
                  : '<span class="fmtw-cod sin">Sin código: ponlo con ✏️</span>';
    var h='<div class="fmtw-f" data-k="'+id+'"><div class="cab"><span class="ic" aria-hidden="true">'+it.ic+'</span><span><b>'+esc(it.n)+'</b>'+(it.d ? '<small>'+esc(it.d)+'</small>' : '')+'</span></div>'+cod+
      '<div class="fmtw-acc"><button type="button" class="bt sec" data-ed="'+id+'">✏️ Código</button><button type="button" class="bt" data-pdf="'+id+'">⬇ Descargar PDF</button></div>';
    if(FMTW.ed===it.k) h+='<div class="fmtw-ed"><div><label for="fmtw-cod">Código</label><input id="fmtw-cod" maxlength="40" value="'+esc(C.cod)+'" placeholder="SSOMA-FR-001"></div>'+
      '<div><label for="fmtw-rev">Versión</label><input id="fmtw-rev" maxlength="10" value="'+esc(C.rev)+'" placeholder="00"></div>'+
      '<div><label for="fmtw-fec">Fecha de versión</label><input id="fmtw-fec" type="date" value="'+esc(C.fecha.slice(0, 10))+'"></div>'+
      '<button type="button" class="bt" data-guarda="'+id+'" style="grid-column:1/-1">Guardar</button></div>';
    return h+'</div>';
  }).join('');
}
function _fmtwPintar(){
  var caja=FMTW.caja; if(!caja) return;
  caja.innerHTML='<p class="gris" style="margin:0 0 14px">En blanco, para imprimir y llenar a mano, con el logo de tu empresa, su código, su versión y su fecha de versión. Los códigos son los mismos de la app.</p>'+
    '<div class="fmtw-tabs" role="tablist" aria-label="Formatos">'+FMTW_TABS.map(function(t){ var on=(t[0]===FMTW.tab);
      return '<button type="button" role="tab" data-tab="'+t[0]+'" class="'+(on ? 'on' : '')+'" aria-selected="'+(on ? 'true' : 'false')+'"><span aria-hidden="true">'+t[1]+'</span>'+esc(t[2])+'</button>'; }).join('')+'</div>'+
    '<div class="fmtw-busca"><span aria-hidden="true">🔎</span><input id="fmtw-q" placeholder="Buscar: ATS, asistencia, acta, amoladora, andamio…" autocomplete="off" value="'+esc(FMTW.q)+'"></div>'+
    '<div class="fmtw-lista" id="fmtw-lista">'+_fmtwListaHTML()+'</div>';
  caja.querySelector('.fmtw-tabs').onclick=function(ev){ var b=ev.target.closest ? ev.target.closest('button[data-tab]') : null; if(!b) return; FMTW.tab=b.getAttribute('data-tab'); FMTW.ed=''; _fmtwPintar(); };
  $('fmtw-q').oninput=function(){ FMTW.q=this.value; var l=$('fmtw-lista'); if(l) l.innerHTML=_fmtwListaHTML(); };
  $('fmtw-lista').onclick=function(ev){
    var b=ev.target.closest ? ev.target.closest('button') : null; if(!b) return;
    if(b.getAttribute('data-ed')){ var k=b.getAttribute('data-ed'); FMTW.ed=(FMTW.ed===k) ? '' : k; var l=$('fmtw-lista'); if(l) l.innerHTML=_fmtwListaHTML(); return; }
    if(b.getAttribute('data-pdf')){ fmtWebBajar(b.getAttribute('data-pdf'), b); return; }
    if(b.getAttribute('data-guarda')) _fmtwGuardar(b.getAttribute('data-guarda'), b);
  };
}
/* se guarda sobre lo que el servidor tiene en ese momento (como la app), sin pisar los demás códigos */
function _fmtwGuardar(k, bt){
  var it=_fmtwItem(k); if(!it) return;
  var cod=String(($('fmtw-cod')||{}).value||'').trim().slice(0, 40), rev=String(($('fmtw-rev')||{}).value||'').trim().slice(0, 10) || '00', fe=String(($('fmtw-fec')||{}).value||'').trim();
  if(bt) bt.disabled=true;
  estadoLeerP('formatos').then(function(r){
    var o=(r && r.valor && typeof r.valor==='object') ? r.valor : {};
    var donde=it.tipo==='reg' ? 'items' : 'insp'; o[donde]=o[donde] || {};
    var x=o[donde][k] || {}; x.cod=cod; x.rev=rev; x.fecha=fe; if(donde==='insp' && !x.extra) x.extra=[];
    o[donde][k]=x;
    return estadoEscribirP('formatos', o).then(function(){ FMTW.fm=o; });
  }).then(function(){ FMTW.ed=''; _fmtwPintar(); toast('Guardado: sale así en el formato y en los registros de la app.'); },
          function(){ if(bt) bt.disabled=false; toast('No se pudo guardar. Revisa tu conexión e inténtalo otra vez.'); });
}
/* el logo con su proporción (para la cabecera del PDF) */
function _fmtwLogo(du){
  if(!/^data:image\//.test(String(du||''))) return Promise.resolve(null);
  if(FMTW.logo && FMTW.logo.src===du) return Promise.resolve(FMTW.logo);
  return new Promise(function(ok){
    var im=new Image();
    im.onload=function(){ FMTW.logo={ src:du, du:du, r:(im.naturalWidth || 2) / (im.naturalHeight || 1) }; ok(FMTW.logo); };
    im.onerror=function(){ ok(null); };
    im.src=du;
  });
}
function fmtWebBajar(k, bt){
  var it=_fmtwItem(k); if(!it) return Promise.resolve(null);
  if(bt) bt.disabled=true;
  var suelta=function(){ if(bt) bt.disabled=false; };
  var cod=null;
  return Promise.all([cargarEvPDF(), FMTW.fm ? FMTW.fm : estadoLeerP('formatos').then(function(r){ FMTW.fm=(r && r.valor) || {}; return FMTW.fm; }, function(){ return {}; }),
                      FMTW.emp ? FMTW.emp : empleadorP().then(function(e){ FMTW.emp=e || {}; return FMTW.emp; }, function(){ return {}; })]).then(function(){
    return _fmtwLogo((FMTW.emp||{}).logo);
  }).then(function(L){
    cod=_fmtwCodigo(it);
    var C={ razon:(FMTW.emp||{}).razon || '', obra:String(nombreObraP()||''), logo:L, cod:cod.cod, rev:cod.cod ? cod.rev : '', fecha:cod.fecha ? cod.fecha.slice(0, 10).split('-').reverse().join('/') : '' };
    var doc=FMT.pdf(it, C);
    bajarBlob(doc.output('blob'), FMT.nombreArchivo(it, C));
    suelta(); toast('Formato descargado: imprímelo al 100 %.');
    return true;
  }).then(null, function(){ suelta(); toast('No se pudo armar el PDF. Revisa tu conexión e inténtalo otra vez.'); return null; });
}
